import{m as k,r as l}from"./manifestTechniquePhotos-CkADNGG3.js";const x=[{id:"M01",title:"Ryan & Deci · 2000 · Self-determination theory",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Motivation can reflect personally endorsed values without enjoyment. The framework proposes autonomy, competence, and relatedness as basic needs.",limitation:"Theory and narrative review, not a trial of ODA prompts. Autonomy is not independence; rewards and obligations do not automatically make a goal unowned."},{id:"M02",title:"Ntoumanis et al. · 2021 · Need-supportive health interventions",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 studies showed modest average benefits for autonomous motivation and later health behavior. Immediate physical-health improvement was not statistically significant.",limitation:"Multicomponent health programs with substantial heterogeneity and design limits. A values prompt alone does not reproduce the program or establish effects for all goals."},{id:"M03",title:"Duckworth et al. · 2013 · Academic MCII protocol",url:"https://www.researchgate.net/publication/256294319_From_Fantasy_to_Action_Mental_Contrasting_With_Implementation_Intentions_MCII_Improves_Academic_Performance_in_Children",type:"research",finding:"A trial with 77 fifth graders used three one-hour small-group sessions and repeated outcome-obstacle-response planning. Some academic outcomes improved.",limitation:"One school, later nonsignificant between-group differences, and child-specific support/dose. No established effect for a brief adult phone exercise."},{id:"M04",title:"Cerasoli, Nicklin & Ford · 2014 · Motivation and incentives",url:"https://selfdeterminationtheory.org/wp-content/uploads/2017/06/2014_Cerasoli_Intrinsic.pdf",type:"research",finding:"Across 183 samples, intrinsic motivation and incentives both related to performance, with different quality and quantity patterns.",limitation:"Associational, heterogeneous findings do not establish universal reward prescriptions or show that socially rewarded goals are inauthentic."},{id:"M05",title:"Lally et al. · 2010 · Modeling habit formation",url:"https://www.flexyourbrain.com/wp-content/uploads/2015/10/UL-STUDY-66-Days-IJSP_998-1009.pdf",type:"research",finding:"Among 39 well-fitting curves, median modeled time to 95 percent of the automaticity plateau was 66 days. One missed opportunity did not materially disrupt the modeled process.",limitation:"Observed for 84 days; 254 days was extrapolated. Not observed completion dates, a universal timetable, or evidence about long interruptions."},{id:"M07",title:"Wood & Rünger · 2016 · Psychology of habit",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"Recurring contexts and repeated responses can support habit learning; deliberate goals and habitual responses can coexist.",limitation:"Narrative review, not a trial of ODA's minimum or anchor recipe. Cues do not guarantee action; small behaviors need not inevitably expand."},{id:"M08",title:"Gollwitzer & Sheeran · 2006 · If-then planning",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Specific if-then plans improved goal attainment on average across 94 independent tests. The historical standardized effect was d = 0.65.",limitation:"Varied older evidence. Not a 65 percent improvement, guaranteed execution, or benchmark for an app reminder."},{id:"M10",title:"Wang, Wang & Gai · 2021 · Mental contrasting and planning",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 articles and 24 independent effects showed small-to-medium average goal-attainment benefits from outcome-obstacle-response planning.",limitation:"Heterogeneity and publication-bias signals limit the magnitude. No guaranteed wishes, outside-event causality, or validation of every WOOP format."},{id:"M13",title:"Harkin et al. · 2016 · Progress monitoring",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Monitoring interventions improved goal attainment on average across 138 randomized studies.",limitation:"Varied goals and methods. Moderator associations do not isolate recording or sharing causally; no optimal weekly cadence or required public disclosure."},{id:"M15",title:"Fogg · Tiny Habits design instructions",url:"https://tinyhabits.com/design/",type:"technique",finding:"The practitioner recipe pairs an existing routine with a tiny behavior and recommends revising unsuccessful pairings.",limitation:"No controlled estimate on this page validates the complete recipe, celebration necessity, optimal sub-minute dose, or inevitable growth."},{id:"M20",title:"NIMH · Caring for your mental health",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Persistent severe or distressing symptoms, loss of interest, or inability to complete usual activities warrant professional help. Urgent danger needs immediate assistance.",limitation:"Public guidance, not an ODA efficacy trial or diagnosis from low motivation. No need to wait two weeks, a streak, or course completion when concerned."},{id:"motivation-sdt",title:"Ryan & Deci · 2000 · Self-determination theory",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Motivation can reflect personally endorsed values without enjoyment. The framework proposes autonomy, competence, and relatedness as basic needs.",limitation:"Theory and narrative review, not a trial of ODA prompts. Autonomy is not independence; rewards and obligations do not automatically make a goal unowned."},{id:"motivation-sdt-meta",title:"Ntoumanis et al. · 2021 · Need-supportive health interventions",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 studies showed modest average benefits for autonomous motivation and later health behavior. Immediate physical-health improvement was not statistically significant.",limitation:"Multicomponent health programs with substantial heterogeneity and design limits. A values prompt alone does not reproduce the program or establish effects for all goals."},{id:"M16",title:"Fogg · Tiny Habits positive gesture instructions",url:"https://tinyhabits.com/rewire/",type:"technique",finding:"Fogg recommends an immediate, self-chosen positive gesture after a tiny behavior.",limitation:"Practitioner page without a controlled estimate. Celebration necessity, faster neural wiring, and checkmark equivalence were not independently established."}],c=[{schemaVersion:2,revision:2,id:"motivation-1",courseId:"motivation",locale:"en",title:"Hate the task? Check the goal.",goal:"Choose whether a goal deserves its cost, then sample one behavior that serves it.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Does the goal on your list feel costly? Check what its effort would change in your life.",reason:{id:"motivation-1-reason",label:"What life change is worth this goal's weekly cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Build options for my family","Make time for curiosity","Keep a responsibility I endorse"]},why:{id:"motivation-1-why",label:"What life change is worth this goal's weekly cost?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A task can reflect your values even when you dislike doing it. Studying for stable income, caring for family, or earning a qualification can be personally chosen. Enjoyment and ownership are different questions. Other people's approval does not automatically make a goal borrowed.","Ask what ordinary life change the goal serves and what time or energy it costs this week. Decide to keep, reshape, defer, or drop it. If you keep it, sample one useful behavior at a feasible opening. This is a choice to test, not a diagnostic test of your true motives."],example:{title:"Leila's study sample",text:"At 7 p.m., Leila weighs her qualification against family time. She dislikes the coursework but values the job options it could create. She keeps the goal and answers one practice question at the kitchen table. Her answer is incomplete. She records the attempt and chooses another opening, without pretending she enjoyed studying."}},move:{invitation:"Choose the goal, then name its actual behavior before using an example.",instructions:["Examples are editable; choose care, work, relationships, or your own behavior.","Save an available date, start signal, and place for that unit."],prompts:[{id:"motivation-1-0",label:"What are you choosing to give up for this goal?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Example: answer my qualification's first practice question","Confirm tomorrow's pickup time with Maya","Draft one sentence of my client update","Ask Sam our agreed check-in question"],minimum:["Answer that practice question","Send Maya the agreed pickup time","Write the first useful update sentence","Ask Sam how today's appointment went"],cue:["After I clear my dinner plate","When Maya's text about pickup arrives","After my 2 p.m. work break","When our agreed evening check-in starts"],place:["At my kitchen table","In our existing text thread","At my work computer","In our existing call"],minutes:[2,1,5],fallback:["Answer a shorter question from these notes","Call using our agreed contact method","Dictate that sentence in my accessible notes","Offer our agreed text check-in instead"],observation:["What I answered and what time it cost","Whether I sent the time; reply remains separate","What useful update sentence exists","Question asked, including no reply"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: answer my qualification's first practice question",minimum:"Answer that practice question",cue:"After I clear my dinner plate",place:"At my kitchen table",fallback:"Answer a shorter question from these notes",observation:"What I answered and what time it cost",minutes:2},{action:"Confirm tomorrow's pickup time with Maya",minimum:"Send Maya the agreed pickup time",cue:"When Maya's text about pickup arrives",place:"In our existing text thread",fallback:"Call using our agreed contact method",observation:"Whether I sent the time; reply remains separate",minutes:1},{action:"Draft one sentence of my client update",minimum:"Write the first useful update sentence",cue:"After my 2 p.m. work break",place:"At my work computer",fallback:"Dictate that sentence in my accessible notes",observation:"What useful update sentence exists",minutes:5},{action:"Ask Sam our agreed check-in question",minimum:"Ask Sam how today's appointment went",cue:"When our agreed evening check-in starts",place:"In our existing call",fallback:"Offer our agreed text check-in instead",observation:"Question asked, including no reply",minutes:2}]},suggested:{action:"Example: answer my qualification's first practice question",minimum:"Answer that practice question",minutes:2,cueHint:"After I clear my dinner plate",placeHint:"At my kitchen table",obstacleHint:"Example: today's question competes with family time",fallbackHint:"Answer a shorter question from these notes",observationHint:"What I answered and what time it cost"},stopRule:"Do not push through illness, danger, or persistent difficulty functioning. Support is available now.",accessibleAlternative:"Use audio, dictation, assistive tools, agreed help, or an explicit pause."},result:{question:"Did you try the behavior you chose?",observationPrompt:"What did you actually do, and what did it cost?"},judgment:{primary:{id:"motivation-1-decision",scenario:"Leila dislikes studying for a qualification. She wants more stable job options for her family, and her colleagues also value the credential.",question:"What best tests whether to keep it?",options:[{id:"motivation-1-endorse",text:"Check whether she endorses the benefit and time cost, then answer one practice question.",feedback:"This separates dislike from ownership and tests a feasible behavior. Recognition can coexist with a chosen reason. She still gets to reshape or defer the goal if its cost does not fit."},{id:"motivation-1-interest",text:"Try a more enjoyable goal for a week before deciding whether this qualification still belongs to her.",feedback:"Exploring another interest can be useful, but enjoyment alone cannot decide whether this qualification is owned. First examine its chosen benefit and cost; a valued task may remain unpleasant."},{id:"motivation-1-advice",text:"Ask credentialed colleagues which qualification they would choose, then adopt the one they recommend.",feedback:"Colleagues can clarify options and requirements. Their recommendation cannot decide Leila's trade-off for her. She needs her own reason and feasible time cost before adopting their goal."}],bestOptionId:"motivation-1-endorse"}},carry:{takeaway:"A chosen goal can be difficult. Judge its value and cost, then test its behavior.",followUp:{questionId:"motivation-1-return",question:"Did the sample serve your chosen reason, and is its cost still worth accepting?",observationPrompt:"What did you actually do, and what did it cost?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"Ownership does not require enjoyment",paragraphs:["Ryan and Deci's self-determination theory distinguishes intrinsic enjoyment from personally endorsed reasons for doing something. An extrinsic goal can become valued: a qualification, income, care, or a shared responsibility may matter even when the behavior is dull. Autonomy means a sense of choice, not having no obligations or influences. Their 2000 paper is a theory and narrative review, not a trial of this lesson. [M01]","This lesson's keep, reshape, defer, or drop decision is an ODA reflection exercise. It does not reveal pure motives or certify that a goal is authentic. Cerasoli and colleagues' large meta-analysis found intrinsic motivation and incentives can both relate to performance, with variation across quality and quantity outcomes. It does not show rewards are universally good or bad. [M04] You can acknowledge mixed motives and still decide whether the behavior serves the life you want."]},{heading:"A values prompt is not a whole program",paragraphs:["Ntoumanis and colleagues pooled 73 self-determination-informed health intervention studies. They found modest average benefits for autonomous motivation and later health behavior. The programs included multiple supports; findings varied substantially. Immediate physical health improvement was not statistically significant. These results do not establish the same benefit for every career, study, or personal goal. [M02]","A single reason prompt cannot reproduce those programs. Here, your reason guides a practical experiment: one goal, one actual behavior, one honest record, and one next opportunity. Use the first sample to notice fit, access, and cost without demanding enthusiasm. Keep details private if you prefer. Later lessons keep this same direction while testing a meaningful minimum, a usable cue, and a response to a real obstacle. An explicit pause or request for support is a valid choice when the goal or circumstances need attention."]}],sourceIds:["M01","M04","M02"]}},{schemaVersion:2,revision:2,id:"motivation-2",courseId:"motivation",locale:"en",title:"Opened the book again without reading?",goal:"Try a small version of your existing behavior that still produces something useful.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Opened the book without reading? Make the useful part small enough to do.",reason:{id:"motivation-2-useful-unit-cost",label:"What preparation could you stop to make room for the useful part?",kind:"text",maxLength:160,optional:!0,suggestions:["Stop reopening; read one sentence","Stop rearranging; write one sentence","Keep the useful act; shorten its size"]},why:{id:"motivation-2-why",label:"What useful minimum would serve your chosen reason?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Keep the goal you chose. Shrink its behavior until it fits today, while keeping the useful part inside. Put the book within reach, then read a sentence. Open the application, then write one useful sentence. The setup is preparation; the sentence is the behavior you want to test.","Habit research describes repeated responses in recurring contexts. It does not show that every tiny start grows, or that a checkmark has the same effect as celebration. Your minimum can stay small. Try it once, record what actually happened, and later ask whether that amount still serves your reason."],example:{title:"Leila's smaller question",text:"On Tuesday after dinner, Leila has two minutes for the same qualification. She puts her notes within reach, then answers one short practice question. She stops there because family time matters too. Her answer needs correction. She records the answer as work and the notes setup as preparation, without expanding the session."}},move:{invitation:"Keep your saved behavior; shorten its useful unit before saving.",instructions:["Retain your action and usable setting; edit only the useful minimum.","Put needed materials within reach, then perform that minimum."],prompts:[],suggestions:{action:["Example: answer my next qualification question","Write my saved application paragraph","Complete my agreed kitchen cleanup"],minimum:["Answer the first part of that question","Write one usable sentence of that paragraph","Wash the two mugs we agreed on"],cue:["After I clear my dinner plate","After my 2 p.m. work break","After our shared meal ends"],place:["At my kitchen table","At my work computer","At my accessible kitchen sink"],minutes:[2,1],fallback:["Dictate the first part from accessible notes","Dictate one usable sentence in my notes","Choose another agreed accessible cleanup task"],observation:["Actual answer versus materials only prepared","Sentence written versus document only opened","Agreed task done versus supplies only arranged"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: answer my next qualification question",minimum:"Answer the first part of that question",cue:"After I clear my dinner plate",place:"At my kitchen table",fallback:"Dictate the first part from accessible notes",observation:"Actual answer versus materials only prepared",minutes:2},{action:"Write my saved application paragraph",minimum:"Write one usable sentence of that paragraph",cue:"After my 2 p.m. work break",place:"At my work computer",fallback:"Dictate one usable sentence in my notes",observation:"Sentence written versus document only opened",minutes:1},{action:"Complete my agreed kitchen cleanup",minimum:"Wash the two mugs we agreed on",cue:"After our shared meal ends",place:"At my accessible kitchen sink",fallback:"Choose another agreed accessible cleanup task",observation:"Agreed task done versus supplies only arranged",minutes:2}]},suggested:{action:"Example: answer my next qualification question",minimum:"Answer the first part of that question",minutes:2,cueHint:"After I clear my dinner plate",placeHint:"At my kitchen table",obstacleHint:"Example: I prepare the materials without answering",fallbackHint:"Dictate the first part from accessible notes",observationHint:"Actual answer versus materials only prepared"},stopRule:"Choose a safe unit. Stop for pain, illness, urgent needs, or an inaccessible setup.",accessibleAlternative:"Listen, dictate, use assistive tools, or choose labeled preparation and a later real opportunity."},result:{question:"Did you do the useful part of your minimum?",observationPrompt:"What was actual behavior, and what was preparation?"},judgment:{primary:{id:"motivation-2-decision",scenario:"You want to write an application. For three sessions, you opened the file but wrote nothing. You have two minutes and know the required section.",question:"Which minimum now tests useful progress?",options:[{id:"motivation-2-bigger",text:"Reserve a longer session later so a complete answer will feel worth starting.",feedback:"A longer session may help completion, but it leaves the current preparation-only pattern untested. Use a rough sentence now and decide later whether a larger slot is needed."},{id:"motivation-2-outline",text:"Use the two minutes to outline three points, then write the required section in a longer slot.",feedback:"An outline can clarify content. You already know this section, and the repeated barrier is starting its prose. A rough sentence tests that barrier now; record any outlining as preparation."},{id:"motivation-2-sentence",text:"Write one rough sentence for the required section, then stop at the available limit.",feedback:"This contains the behavior and leaves an editable piece. It does not guarantee the application's success or require a longer session. Record the sentence separately from opening the file."}],bestOptionId:"motivation-2-sentence"}},carry:{takeaway:"Make the start feasible without shrinking the useful behavior out of it.",followUp:{questionId:"motivation-2-return",question:"Did your small version produce useful behavior, or only make the setup ready?",observationPrompt:"What was actual behavior, and what was preparation?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"Small is a design choice, not a guarantee",paragraphs:["Wood and Rünger review habits as learned responses connected with recurring contexts. Repetition can support greater automaticity, while deliberate goals can still matter. Their review does not establish that one sentence is an optimal dose or that every small behavior inevitably expands. This lesson uses a small unit to test access and usefulness in your actual week. [M07]","Use the unit to separate preparation from the behavior you want to practice. A question answered can be checked, a sentence read can convey information, and a sentence written can be edited. Having materials ready is useful setup, but it does not contain those behaviors. If several tiny attempts never serve the reason you chose, review the behavior or goal. You may need a different unit, more support, or a larger feasible window. Do not turn a convenient checkmark into invented progress. [M07]"]},{heading:"The practitioner recipe has limits",paragraphs:["BJ Fogg's Tiny Habits instruction pairs an existing routine with a tiny behavior and recommends revising a pairing that does not work. It is a practitioner technique. The inspected page does not independently establish that its whole recipe outperforms ordinary cue planning or that every action must take less than a minute. [M15]","Fogg also recommends an immediate, self-chosen positive gesture. The proposed claims about faster neural wiring, celebration being necessary, or a checkmark doing the same reinforcing job were not established by controlled evidence in the dossier. [M16] You may notice satisfaction if it occurs, but do not manufacture it. A truthful record says what happened. It is separate from how you felt afterward. You can stop at the useful minimum, retain it tomorrow, and adapt your tools or access method without treating a smaller amount as lesser character."]}],sourceIds:["M07","M15","M16"]}},{schemaVersion:2,revision:2,id:"motivation-3",courseId:"motivation",locale:"en",title:"Reminder rang. You still couldn't start.",goal:"Test your existing minimum at a cue where time, materials, and access are available.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Reminder ringing while you are on the bus? Choose a cue with a usable setting.",reason:{id:"motivation-3-available-setting-cost",label:"Which available setting will you use, and what will you move to protect it?",kind:"text",maxLength:160,optional:!0,suggestions:["Use the fixed break I can protect","Move one flexible chore","Keep care covered while I practice"]},why:{id:"motivation-3-why",label:"Which real opening protects time for your chosen goal?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Your start signal has three jobs: it happens, you notice it, and the behavior is possible then. After the school run cannot support desk work if you go straight to your job. Keep your useful minimum; choose a setting that permits it.","Specific if-then plans can help bridge intention and action. Repeating a behavior in a recurring context can support a habit, but no finish date fits everyone. Today, test the cue rather than trying to become automatic. Record which of the three jobs worked and which needs an adjustment."],example:{title:"Leila's usable opening",text:"Leila planned her question after the school run, but went straight to work without her notes. On Wednesday she moves the same question to after dinner at the kitchen table. The cue happens and she notices it. She answers before clearing the table. One answer is useful; the earlier unavailable slot stays in her record."}},move:{invitation:"Keep your saved unit; choose an available event and place.",instructions:["Check whether the start signal happens, gets noticed, and permits your saved behavior.","Choose the date and confirm materials or access will be there."],prompts:[],suggestions:{action:["Example: answer my saved qualification question","Write my saved application sentence","Complete my agreed kitchen cleanup"],minimum:["Answer that same practice question","Write that same useful sentence","Wash the same two agreed mugs"],cue:["After I clear my dinner plate","When my fixed 12:30 break starts","After our shared meal ends"],place:["At my kitchen table","At my accessible break desk","At my accessible kitchen sink"],minutes:[2,1],fallback:["Use my accessible notes at tomorrow's meal","Dictate the sentence using my saved notes","Use the next agreed covered cleanup slot"],observation:["Signal happened, noticed, and behavior possible","Whether this setting allowed the same unit","Signal happened and agreed task was possible"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: answer my saved qualification question",minimum:"Answer that same practice question",cue:"After I clear my dinner plate",place:"At my kitchen table",fallback:"Use my accessible notes at tomorrow's meal",observation:"Signal happened, noticed, and behavior possible",minutes:2},{action:"Write my saved application sentence",minimum:"Write that same useful sentence",cue:"When my fixed 12:30 break starts",place:"At my accessible break desk",fallback:"Dictate the sentence using my saved notes",observation:"Whether this setting allowed the same unit",minutes:1},{action:"Complete my agreed kitchen cleanup",minimum:"Wash the same two agreed mugs",cue:"After our shared meal ends",place:"At my accessible kitchen sink",fallback:"Use the next agreed covered cleanup slot",observation:"Signal happened and agreed task was possible",minutes:2}]},suggested:{action:"Example: answer my saved qualification question",minimum:"Answer that same practice question",minutes:2,cueHint:"After I clear my dinner plate",placeHint:"At my kitchen table",obstacleHint:"Example: my old signal occurred without my notes",fallbackHint:"Use my accessible notes at tomorrow's meal",observationHint:"Signal happened, noticed, and behavior possible"},stopRule:"Do not practice while driving or where it interferes with care or safety.",accessibleAlternative:"Use a visible or accessible reminder, audio materials, agreed assistance, or a later suitable cue."},result:{question:"Did your cue allow the minimum to happen?",observationPrompt:"Did the cue happen, get noticed, and allow the behavior?"},judgment:{primary:{id:"motivation-3-usable-setting-decision",scenario:"Leila wants to answer her saved question today. Her school-run cue failed because work starts immediately. Dinner offers five confirmed minutes with notes. Her fixed lunch break allows a phone copy. Tomorrow's train also allows study, but no departure is confirmed.",question:"Which change most directly tests the same unit today?",options:[{id:"motivation-3-dinner",text:"Use the confirmed dinner slot with her existing notes and answer the same saved question.",feedback:"This changes the unavailable opening while retaining the unit and materials. The slot is confirmed today. Record whether the signal happens, is noticed, and actually permits the answer."},{id:"motivation-3-phone-copy",text:"Use lunch to make a phone copy, then answer the question during a later available break.",feedback:"Portable notes could support future work breaks. This choice uses today’s known opening for setup and leaves answering undated. Dinner tests the saved behavior today with materials already available."},{id:"motivation-3-train",text:"Carry the notes for tomorrow’s train and answer the same question once its departure is confirmed.",feedback:"The train could provide a workable setting after confirmation. It postpones a test despite an available slot today. If dinner stops fitting, confirm the train date before committing to it."}],bestOptionId:"motivation-3-dinner"}},carry:{takeaway:"A usable cue happens, gets noticed, and allows the behavior in that setting.",followUp:{questionId:"motivation-3-return",question:"Which cue condition failed: happening, noticing, or being able to act?",observationPrompt:"Did the cue happen, get noticed, and allow the behavior?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"A cue is a condition to test",paragraphs:["Gollwitzer and Sheeran's 2006 review combined 94 independent tests of plans connecting a situation with a chosen action. Goal attainment improved on average. The historical standardized effect of 0.65 is not a 65 percent improvement, and it does not forecast the effect of your app reminder. These historical averages concern varied goals and settings rather than this exact study cue. [M08]","Wood and Rünger describe context-linked repetition as part of habit learning. A cue alone does not guarantee behavior, and every routine is not necessarily automatic. [M07] ODA's happens, noticed, possible check is a teaching aid. It helps separate a missed reminder from unavailable materials or a competing duty. If the cue did not happen, record no occasion when appropriate. If it happened but you did not act, record that fact without turning it into a verdict about your commitment."]},{heading:"Sixty-six days was a model estimate",paragraphs:["Lally's 2010 study observed chosen daily behaviors for 84 days. Among 39 participants with well-fitting automaticity curves, the median model-estimated time to 95 percent of the plateau was 66 days, with estimates from 18 to 254. The longest estimate extended beyond observation. These were not observed fastest, average, and slowest habit-completion dates. [M05]","Your qualification practice is not a copy of the study's eating, drinking, or activity behaviors. Do not use its estimate as a deadline or proof that practice should become effortless. Keep the same experiment and look at available opportunities, useful behavior, and the setup that supported it. One cue can fit weekdays while a different arrangement is needed during shifts or care. Test a deliberate change and retain the earlier record so your review compares actual conditions."]}],sourceIds:["M08","M07","M05"]}},{schemaVersion:2,revision:2,id:"motivation-4",courseId:"motivation",locale:"en",title:"Plan for the moment it breaks",goal:"Test one feasible response to an observed obstacle while protecting real needs and responsibilities.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Study slot colliding with bedtime care? A stronger pep talk cannot cover childcare.",reason:{id:"motivation-4-accepted-change-cost",label:"Which concrete change will you accept to address the barrier your record shows?",kind:"text",maxLength:160,optional:!0,suggestions:["Move the slot; keep the useful unit","Request specific support before assuming coverage","Change access rather than demand more effort"]},why:{id:"motivation-4-why",label:"What needs protecting while this goal moves forward?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Retain your goal and useful unit. Use a real attempt to identify one barrier: switching away, missing materials, competing care, or a health need. Pairing an outcome, obstacle, and response shows modest average research benefits. It cannot make missing time or help appear.","Match the response to the condition. A distracting tab may need a changed setup. Care needs covered time or agreed help. Illness may call for rest. Plan the first useful behavior your response allows, then test it at the next suitable opening. Rehearsal is preparation, not evidence the fallback worked."],example:{title:"Leila's covered time",text:"Thursday's study cue arrives during Leila's child's bedtime. Her partner agrees to cover five minutes after bedtime, so she moves the same question there. She answers at the table while care remains covered. She records the arrangement and the answer. The question needs work, and tomorrow's coverage is not assumed."}},move:{invitation:"Match one changed condition to your recorded barrier; retain your useful act.",instructions:["Coverage agreed: try your retained unit; change only the barrier your record identifies.","No agreement: choose Adapt, Support; request a specific task, person, and time.","If declined, use a genuinely available slot or pause; support remains separate from practice."],prompts:[{id:"motivation-4-support-request",label:"If you need support, what task, person, and time will your request name?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Example: ask Maya by text for five-minute care cover."}],suggestions:{action:["Example: write my saved application sentence","Answer my saved question during agreed cover","Read my saved passage using audio"],minimum:["Write that same useful application sentence","Answer that same practice question","Listen to that same useful passage"],cue:["After my 2 p.m. work break","When the agreed five-minute care cover starts","When my confirmed 12:30 break starts"],place:["At my work computer","At my kitchen table","At my quiet accessible break space"],minutes:[2,5],fallback:["Silence optional alerts; keep urgent contact available","If cover falls through, pause the practice","Request an accessible version if audio fails"],observation:["Whether alerts appeared and my response allowed writing","Coverage available and question answered are separate","Access available and passage heard are separate"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: write my saved application sentence",minimum:"Write that same useful application sentence",cue:"After my 2 p.m. work break",place:"At my work computer",fallback:"Silence optional alerts; keep urgent contact available",observation:"Whether alerts appeared and my response allowed writing",minutes:2},{action:"Answer my saved question during agreed cover",minimum:"Answer that same practice question",cue:"When the agreed five-minute care cover starts",place:"At my kitchen table",fallback:"If cover falls through, pause the practice",observation:"Coverage available and question answered are separate",minutes:2},{action:"Read my saved passage using audio",minimum:"Listen to that same useful passage",cue:"When my confirmed 12:30 break starts",place:"At my quiet accessible break space",fallback:"Request an accessible version if audio fails",observation:"Access available and passage heard are separate",minutes:5}]},suggested:{action:"Example: write my saved application sentence",minimum:"Write that same useful application sentence",minutes:2,cueHint:"After my 2 p.m. work break",placeHint:"At my work computer",obstacleHint:"Example: optional phone alerts interrupted my last sentence",fallbackHint:"Silence optional alerts; keep urgent contact available",observationHint:"Whether alerts appeared and my response allowed writing"},stopRule:"Keep care and urgent needs covered. Choose support or rest for illness or unsafe conditions.",accessibleAlternative:"Request agreed assistance, change access or timing, or choose a support or rest action."},result:{question:"Did your response allow your chosen minimum?",observationPrompt:"Did the obstacle appear, and what response did you use?"},judgment:{primary:{id:"motivation-4-covered-slot-decision",scenario:"Guitar practice overlaps bedtime care. Tonight’s five-minute cover is confirmed, and the guitar is ready. A neighbor might offer a longer Saturday slot but has not agreed. The parent wants to try one short phrase tonight while protecting care.",question:"Which response best fits that next attempt?",options:[{id:"motivation-4-confirmed-cover",text:"Play the short phrase during tonight’s confirmed five-minute cover, then stop when that cover ends.",feedback:"The agreement supplies the missing condition without enlarging the act. Try the retained phrase and record practice separately from coverage. Tonight’s arrangement does not imply future help is booked."},{id:"motivation-4-saturday-request",text:"Ask the neighbor about Saturday’s longer covered slot and wait for confirmation before scheduling that practice.",feedback:"This is a safe support request for a later opportunity. It does not test tonight’s already feasible short phrase. Choose it if tonight stops fitting, and leave Saturday unconfirmed until agreed."},{id:"motivation-4-prepare-first",text:"Use tonight’s covered five minutes to check tuning and mark the phrase for another practice slot.",feedback:"Tuning and marking can be useful preparation when needed. The instrument and phrase are ready here. Preparing again leaves the actual practice untested; use the confirmed cover for the phrase."}],bestOptionId:"motivation-4-confirmed-cover"}},carry:{takeaway:"A response works only if it fits the obstacle and leaves real needs protected.",followUp:{questionId:"motivation-4-barrier-response-return",question:"Did your saved act happen, and did the changed condition address the recorded barrier?",observationPrompt:"What was practice, what was support, and which constraint remained?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"Research supports planning, with dose limits",paragraphs:["Wang and colleagues' 2021 review pooled 21 articles and 24 effects of mental contrasting with implementation intentions. Its average goal-attainment effect was small to medium. Results varied across goals and showed publication-bias signals. Combining an outcome, obstacle, and response does not guarantee wishes, demonstrate that thoughts change outside events, or establish every WOOP format as equivalent. [M10]","Duckworth and colleagues tested an academic protocol with 77 fifth graders at one school. Students worked in small groups across three one-hour sessions, with repeated exercises and reminder cards. Some academic outcomes improved, but later between-group differences were nonsignificant. [M03] ODA's short adult exercise changes population, support, and duration. It is an adaptation for choosing a testable response, not the full intervention. Rehearse if useful, then distinguish preparation from the actual opportunity when the obstacle appears and the response is needed."]},{heading:"Match the barrier without blaming the person",paragraphs:["The planning procedure examines a desired outcome, an obstacle, and a chosen counteraction. It does not establish that every obstacle is an inner attitude. Care, money, disability access, shift work, illness, and another person's harmful conduct can constrain what is feasible. A practical response may be agreed support, a changed schedule, an accommodation, rest, or a boundary. The adult adaptation should name those constraints honestly. [M03, M10]","Use your actual record to choose one condition to change. If the cue happened and materials were unavailable, a bigger commitment misses the problem. If care needed you, leave that responsibility covered. If a distracting habit appeared, test a response that still allows urgent contact. An obstacle that never occurred leaves its fallback untested. Record the useful unit separately from arranging help or moving materials. Later, consolidate the setup that worked rather than collecting more rituals or demanding a stronger feeling of motivation."]}],sourceIds:["M10","M03"]}},{schemaVersion:2,revision:2,id:"motivation-5",courseId:"motivation",locale:"en",title:"A missed day needs a workable return",goal:"Review the same experiment, retain one useful condition, and schedule a feasible next attempt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Missed sessions? Did your goal change, or did your available time?",reason:{id:"motivation-5-reason",label:"Does this goal still deserve a place next week?",kind:"text",maxLength:160,optional:!0,suggestions:["Return to a goal I still choose","Change a cue that no longer fits","Protect rest and seek needed support"]},why:{id:"motivation-5-why",label:"Does this goal still deserve a place next week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Review your chosen reason, useful minimum, cue, and actual records. Progress monitoring can support goal attainment on average. It cannot turn an untried plan into behavior or make blank history mean failure. Keep preparation, actual work, and pause distinct when you decide what helped.","One missed opportunity did not materially disrupt habit formation in one study. That does not establish that long interruptions are harmless. Repeat a setup that fit, change an unavailable opening, or reconsider the goal. Date the next useful unit. No doubling up or earned permission to rest is required."],example:{title:"Leila's next opening",text:"On Sunday, Leila reviews the same qualification plan. Dinner slots worked twice; a changed shift blocked two others. She still chooses the goal, so she moves one question to Monday's available lunch break with accessible notes. She writes down the next opening. The missed sessions stay missed, and Monday's action remains a plan."}},move:{invitation:"Review your record; date the same useful unit at an available opening.",instructions:["Change only the condition your attempts identify; confirm its date and setting.","Only this occurrence and its next-day return are booked; weekly review remains your choice."],prompts:[],suggestions:{action:["Example: answer my saved qualification question","Take my saved short walk","Complete my agreed kitchen cleanup"],minimum:["Answer that same practice question","Walk the same safe five-minute route","Wash the same two agreed mugs"],cue:["When my confirmed 12:30 lunch break starts","When my fixed noon break starts","After our shared meal ends"],place:["At my accessible break desk","On my accessible workplace loop","At my accessible kitchen sink"],minutes:[2,5],fallback:["If lunch is canceled, date another feasible slot","If route is unsafe, choose seated movement","If unavailable, agree another useful cleanup task"],observation:["Whether revised opening allowed the same question","Actual movement and available time","Task done and whether the setting fit"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],bundles:[{action:"Example: answer my saved qualification question",minimum:"Answer that same practice question",cue:"When my confirmed 12:30 lunch break starts",place:"At my accessible break desk",fallback:"If lunch is canceled, date another feasible slot",observation:"Whether revised opening allowed the same question",minutes:2},{action:"Take my saved short walk",minimum:"Walk the same safe five-minute route",cue:"When my fixed noon break starts",place:"On my accessible workplace loop",fallback:"If route is unsafe, choose seated movement",observation:"Actual movement and available time",minutes:5},{action:"Complete my agreed kitchen cleanup",minimum:"Wash the same two agreed mugs",cue:"After our shared meal ends",place:"At my accessible kitchen sink",fallback:"If unavailable, agree another useful cleanup task",observation:"Task done and whether the setting fit",minutes:2}]},suggested:{action:"Example: answer my saved qualification question",minimum:"Answer that same practice question",minutes:2,cueHint:"When my confirmed 12:30 lunch break starts",placeHint:"At my accessible break desk",obstacleHint:"Example: my recorded shift change removed evening study time",fallbackHint:"If lunch is canceled, date another feasible slot",observationHint:"Whether revised opening allowed the same question"},stopRule:"Persistent loss of interest or difficulty functioning deserves support now. Use urgent help for immediate danger.",accessibleAlternative:"Use accessible materials, agreed assistance, a support request, rest, or an explicit pause."},result:{question:"Did you carry out your chosen return?",observationPrompt:"What actual behavior, support, or pause did you record?"},judgment:{primary:{id:"motivation-5-recorded-barrier-decision",scenario:"Kofi’s new shift begins before dinner ends, removing his evening walk window. He still chooses walking. A safe five-minute lunch route is available daily. A safe pre-shift route requires waking early; a longer Sunday route is available. He wants to test a weekday return without reducing sleep.",question:"Which plan best fits the recorded barrier and cost?",options:[{id:"motivation-5-early-walk",text:"Move the walk before his shift and set an earlier alarm to protect that new opening.",feedback:"A pre-shift route solves the evening conflict, but the earlier alarm conflicts with his sleep boundary. The available lunch slot tests a weekday return without that additional cost."},{id:"motivation-5-sunday-walk",text:"Switch to a longer Sunday walk and reconsider whether a weekly cadence better fits his schedule.",feedback:"A weekly walk is a feasible goal revision, not a failure. Kofi currently wants a weekday test, and lunch is available. Try that condition before deciding whether to change his cadence."},{id:"motivation-5-lunch-return",text:"Date the next lunch opening, take the safe five-minute walk, and record whether the new timing fits.",feedback:"This retains walking and its useful unit while addressing the unavailable evening slot. Only the actual walk counts as practice. Tomorrow’s review can guide repeating, changing, or stopping this arrangement."}],bestOptionId:"motivation-5-lunch-return"}},carry:{takeaway:"Keep the reason and useful behavior; change the condition your record says has failed.",followUp:{questionId:"motivation-5-return",question:"Did your revised opening fit, and is the goal still worth its cost next week?",observationPrompt:"What actual behavior, support, or pause did you record?",adjustmentPrompt:"What one change would make your next attempt fit?"}},goDeeper:{sections:[{heading:"Consolidate evidence without inventing a streak",paragraphs:["Harkin and colleagues' review of 138 randomized studies found an average goal-attainment benefit from progress monitoring. Goals and methods varied. Recording and reporting moderators were associated with larger effects, but those results do not establish that public sharing or a weekly cadence is necessary. ODA's next-day return is an adaptation, not a validated dose. A weekly review is optional and is not automatically booked by this plan. [M13]","Lally's observational study found that one missed opportunity did not materially disrupt its modeled habit-formation process. That narrow result does not prove long interruptions leave a habit unchanged. [M05] Use your own attempts to choose what comes next. Keep a useful unit, change a cue or response that did not fit, and leave historical misses visible. A future plan is still planned. If the goal no longer deserves its time cost, reshape, defer, or stop it deliberately. Learning completion is separate from doing and reviewing the behavior."]},{heading:"Enjoyment is optional; support can come now",paragraphs:["Your final lesson consolidates the experiment rather than adding a new motivational ritual. Monitoring research supports comparing actual progress with a chosen goal on average, but it does not identify which technique is best for every person. Your record can show whether a cue was unavailable, whether materials were missing, or whether the goal's time cost stopped fitting. Use that observed condition to choose one next change. Do not count preparation or a promise as the behavior. [M13]","Do not make basic rest or all enjoyable activity conditional on productivity. If you later choose compatible free audio, preserve traffic and safety awareness. Persistent loss of interest, distress, exhaustion, or trouble completing usual activities may need professional assessment. NIMH guidance supports seeking help and immediate assistance for urgent danger; it does not diagnose the cause from low motivation or require waiting before asking for help. [M20] You can keep a small useful practice, request support, or pause while that concern is addressed."]}],sourceIds:["M13","M05","M20"]}}],T={id:"motivation",title:"Waiting for motivation? Give your goal a real opening.",subtitle:"Five lessons to choose a goal worth its cost, test a useful minimum, and make the setup fit your week.",description:"Choose what the effort is for, do a useful small version, and adjust the cue or support using what actually happened.",scope:"Training for everyday goals. Constant lack of drive, exhaustion or losing the ability to function may not be only a motivation problem; it is a good idea to get support, and a health professional can help you look at the cause.",outcome:"A chosen action and a dated next attempt shaped by your records.",photo:{id:"1790004245013-b347139d5591",alt:"A man running along a sunlit forest path"},lessons:[{id:"motivation-1",schemaVersion:2,title:"Hate the task? Check the goal.",minutes:6,goal:"Choose whether a goal deserves its cost, then sample one behavior that serves it.",reading:["A task can reflect your values even when you dislike doing it. Studying for stable income, caring for family, or earning a qualification can be personally chosen. Enjoyment and ownership are different questions. Other people's approval does not automatically make a goal borrowed.","Ask what ordinary life change the goal serves and what time or energy it costs this week. Decide to keep, reshape, defer, or drop it. If you keep it, sample one useful behavior at a feasible opening. This is a choice to test, not a diagnostic test of your true motives."],practice:["Decide: keep, reshape, defer, or drop.","If continuing, try one useful unit.","Try the minimum: Answer one practice question."],reflection:"What life change is worth this goal's weekly cost?",question:"Leila dislikes studying for a qualification. She wants more stable job options for her family, and her colleagues also value the credential. What best tests whether to keep it?",options:["Try a more enjoyable goal for a week before deciding whether this qualification still belongs to her.","Check whether she endorses the benefit and time cost, then answer one practice question.","Ask credentialed colleagues which qualification they would choose, then adopt the one they recommend."],correct:1,feedback:"This separates dislike from ownership and tests a feasible behavior. Recognition can coexist with a chosen reason. She still gets to reshape or defer the goal if its cost does not fit.",takeaway:"A chosen goal can be difficult. Judge its value and cost, then test its behavior.",sources:["M01","M04","M02"],deeper:[{heading:"Ownership does not require enjoyment",paragraphs:["Ryan and Deci's self-determination theory distinguishes intrinsic enjoyment from personally endorsed reasons for doing something. An extrinsic goal can become valued: a qualification, income, care, or a shared responsibility may matter even when the behavior is dull. Autonomy means a sense of choice, not having no obligations or influences. Their 2000 paper is a theory and narrative review, not a trial of this lesson. [M01]","This lesson's keep, reshape, defer, or drop decision is an ODA reflection exercise. It does not reveal pure motives or certify that a goal is authentic. Cerasoli and colleagues' large meta-analysis found intrinsic motivation and incentives can both relate to performance, with variation across quality and quantity outcomes. It does not show rewards are universally good or bad. [M04] You can acknowledge mixed motives and still decide whether the behavior serves the life you want."]},{heading:"A values prompt is not a whole program",paragraphs:["Ntoumanis and colleagues pooled 73 self-determination-informed health intervention studies. They found modest average benefits for autonomous motivation and later health behavior. The programs included multiple supports; findings varied substantially. Immediate physical health improvement was not statistically significant. These results do not establish the same benefit for every career, study, or personal goal. [M02]","A single reason prompt cannot reproduce those programs. Here, your reason guides a practical experiment: one goal, one actual behavior, one honest record, and one next opportunity. Use the first sample to notice fit, access, and cost without demanding enthusiasm. Keep details private if you prefer. Later lessons keep this same direction while testing a meaningful minimum, a usable cue, and a response to a real obstacle. An explicit pause or request for support is a valid choice when the goal or circumstances need attention."]}],example:{title:"Leila's study sample",text:"At 7 p.m., Leila weighs her qualification against family time. She dislikes the coursework but values the job options it could create. She keeps the goal and answers one practice question at the kitchen table. Her answer is incomplete. She records the attempt and chooses another opening, without pretending she enjoyed studying."},photo:{id:"1517971129774-8a2b38fa128e",alt:"A woman writing in a notebook by a window"}},{id:"motivation-2",schemaVersion:2,title:"Make the minimum contain the work",minutes:6,goal:"Try a small version of your existing behavior that still produces something useful.",reading:["Keep the goal you chose. Shrink its behavior until it fits today, while keeping the useful part inside. Put the book within reach, then read a sentence. Open the application, then write one useful sentence. The setup is preparation; the sentence is the behavior you want to test.","Habit research describes repeated responses in recurring contexts. It does not show that every tiny start grows, or that a checkmark has the same effect as celebration. Your minimum can stay small. Try it once, record what actually happened, and later ask whether that amount still serves your reason."],practice:["Put one needed item within reach.","Do the actual minimum; stopping afterward is allowed.","Try the minimum: Write one question answer."],reflection:"What useful minimum would serve your chosen reason?",question:"You want to write an application. For three sessions, you opened the file but wrote nothing. You have two minutes and know the required section. Which minimum now tests useful progress?",options:["Reserve a longer session later so a complete answer will feel worth starting.","Open the file earlier and leave it visible, then count the prepared setup for today.","Write one rough sentence for the required section, then stop at the available limit."],correct:2,feedback:"This contains the behavior and leaves an editable piece. It does not guarantee the application's success or require a longer session. Record the sentence separately from opening the file.",takeaway:"Make the start feasible without shrinking the useful behavior out of it.",sources:["M07","M15","M16"],deeper:[{heading:"Small is a design choice, not a guarantee",paragraphs:["Wood and Rünger review habits as learned responses connected with recurring contexts. Repetition can support greater automaticity, while deliberate goals can still matter. Their review does not establish that one sentence is an optimal dose or that every small behavior inevitably expands. This lesson uses a small unit to test access and usefulness in your actual week. [M07]","Use the unit to separate preparation from the behavior you want to practice. A question answered can be checked, a sentence read can convey information, and a sentence written can be edited. Having materials ready is useful setup, but it does not contain those behaviors. If several tiny attempts never serve the reason you chose, review the behavior or goal. You may need a different unit, more support, or a larger feasible window. Do not turn a convenient checkmark into invented progress. [M07]"]},{heading:"The practitioner recipe has limits",paragraphs:["BJ Fogg's Tiny Habits instruction pairs an existing routine with a tiny behavior and recommends revising a pairing that does not work. It is a practitioner technique. The inspected page does not independently establish that its whole recipe outperforms ordinary cue planning or that every action must take less than a minute. [M15]","Fogg also recommends an immediate, self-chosen positive gesture. The proposed claims about faster neural wiring, celebration being necessary, or a checkmark doing the same reinforcing job were not established by controlled evidence in the dossier. [M16] You may notice satisfaction if it occurs, but do not manufacture it. A truthful record says what happened. It is separate from how you felt afterward. You can stop at the useful minimum, retain it tomorrow, and adapt your tools or access method without treating a smaller amount as lesser character."]}],example:{title:"Leila's smaller question",text:"On Tuesday after dinner, Leila has two minutes for the same qualification. She puts her notes within reach, then answers one short practice question. She stops there because family time matters too. Her answer needs correction. She records the answer as work and the notes setup as preparation, without expanding the session."},photo:{id:"1581578731509-8ae9c5a3e7d3",alt:"A pair of shoes waiting by the door"}},{id:"motivation-3",schemaVersion:2,title:"Your cue needs a real opening",minutes:6,goal:"Test your existing minimum at a cue where time, materials, and access are available.",reading:["A cue has three jobs in your experiment: it happens, you notice it, and the behavior is possible then. “After the school run” may be recognizable but useless for desk work if you go straight to your job. Keep your meaningful minimum and choose a setting that actually allows it.","Specific if-then plans can help bridge intention and action. Repeating a behavior in a recurring context can support a habit, but no finish date fits everyone. Today, test the cue rather than trying to become automatic. Record which of the three jobs worked and which needs an adjustment."],practice:["Check: happens, noticed, behavior possible.","Keep the unit; change an unavailable opening.","Try the minimum: Answer one practice question."],reflection:"Which real opening protects time for your chosen goal?",question:"Leila's school-run cue leads straight into her job. Her study materials stay home. A short after-dinner slot at her table is available. Which change addresses the failed condition?",options:["Add a second school-run reminder so she will notice the plan before work begins.","Reduce the school-run target to half a question while keeping the materials at home.","Move the same question to after dinner, with her notes available at the table."],correct:2,feedback:"This changes the unavailable setting while preserving a meaningful unit. Test whether the new cue happens, gets noticed, and permits the behavior before calling the routine reliable.",takeaway:"A usable cue happens, gets noticed, and allows the behavior in that setting.",sources:["M08","M07","M05"],deeper:[{heading:"A cue is a condition to test",paragraphs:["Gollwitzer and Sheeran's 2006 review combined 94 independent tests of plans connecting a situation with a chosen action. Goal attainment improved on average. The historical standardized effect of 0.65 is not a 65 percent improvement, and it does not forecast the effect of your app reminder. These historical averages concern varied goals and settings rather than this exact study cue. [M08]","Wood and Rünger describe context-linked repetition as part of habit learning. A cue alone does not guarantee behavior, and every routine is not necessarily automatic. [M07] ODA's happens, noticed, possible check is a teaching aid. It helps separate a missed reminder from unavailable materials or a competing duty. If the cue did not happen, record no occasion when appropriate. If it happened but you did not act, record that fact without turning it into a verdict about your commitment."]},{heading:"Sixty-six days was a model estimate",paragraphs:["Lally's 2010 study observed chosen daily behaviors for 84 days. Among 39 participants with well-fitting automaticity curves, the median model-estimated time to 95 percent of the plateau was 66 days, with estimates from 18 to 254. The longest estimate extended beyond observation. These were not observed fastest, average, and slowest habit-completion dates. [M05]","Your qualification practice is not a copy of the study's eating, drinking, or activity behaviors. Do not use its estimate as a deadline or proof that practice should become effortless. Keep the same experiment and look at available opportunities, useful behavior, and the setup that supported it. One cue can fit weekdays while a different arrangement is needed during shifts or care. Test a deliberate change and retain the earlier record so your review compares actual conditions."]}],example:{title:"Leila's usable opening",text:"Leila planned her question after the school run, but went straight to work without her notes. On Wednesday she moves the same question to after dinner at the kitchen table. The cue happens and she notices it. She answers before clearing the table. One answer is useful; the earlier unavailable slot stays in her record."},photo:{id:"1499933374294-4584851497cc",alt:"A black alarm clock on a table"}},{id:"motivation-4",schemaVersion:2,title:"Plan for the moment it breaks",minutes:6,goal:"Test one feasible response to an observed obstacle while protecting real needs and responsibilities.",reading:["Keep your goal, minimum, and cue. Use a real attempt to identify the obstacle: a switching habit, missing materials, a competing responsibility, or a health need. Pairing an outcome with an obstacle and a planned response shows modest average benefits in research. It cannot make an unavailable resource appear.","Match the response to the condition. A distracting tab may need a changed setup. Care needs covered time or agreed help. Illness may call for rest. Plan the first useful behavior your response allows, then test it at the next suitable opening. Rehearsal is preparation, not evidence the fallback worked."],practice:["Keep your goal and useful minimum.","Protect real needs; test the feasible response.","Try the minimum: Answer one practice question."],reflection:"What needs protecting while this goal moves forward?",question:"Guitar practice repeatedly overlaps with a child's bedtime. The parent still values practice. An agreed five-minute slot after bedtime is available. Which backup matches the actual obstacle?",options:["Leave the guitar beside the couch so the parent notices the goal during bedtime.","Use the agreed after-bedtime slot for one short practice while keeping childcare covered.","Use the covered five minutes to check tuning and mark the phrase for another practice slot."],correct:1,feedback:"This protects the real responsibility and gives the behavior usable time. The agreement and practice remain separate facts. Record what happened rather than assuming tomorrow will have the same coverage.",takeaway:"A response works only if it fits the obstacle and leaves real needs protected.",sources:["M10","M03"],deeper:[{heading:"Research supports planning, with dose limits",paragraphs:["Wang and colleagues' 2021 review pooled 21 articles and 24 effects of mental contrasting with implementation intentions. Its average goal-attainment effect was small to medium. Results varied across goals and showed publication-bias signals. Combining an outcome, obstacle, and response does not guarantee wishes, demonstrate that thoughts change outside events, or establish every WOOP format as equivalent. [M10]","Duckworth and colleagues tested an academic protocol with 77 fifth graders at one school. Students worked in small groups across three one-hour sessions, with repeated exercises and reminder cards. Some academic outcomes improved, but later between-group differences were nonsignificant. [M03] ODA's short adult exercise changes population, support, and duration. It is an adaptation for choosing a testable response, not the full intervention. Rehearse if useful, then distinguish preparation from the actual opportunity when the obstacle appears and the response is needed."]},{heading:"Match the barrier without blaming the person",paragraphs:["The planning procedure examines a desired outcome, an obstacle, and a chosen counteraction. It does not establish that every obstacle is an inner attitude. Care, money, disability access, shift work, illness, and another person's harmful conduct can constrain what is feasible. A practical response may be agreed support, a changed schedule, an accommodation, rest, or a boundary. The adult adaptation should name those constraints honestly. [M03, M10]","Use your actual record to choose one condition to change. If the cue happened and materials were unavailable, a bigger commitment misses the problem. If care needed you, leave that responsibility covered. If a distracting habit appeared, test a response that still allows urgent contact. An obstacle that never occurred leaves its fallback untested. Record the useful unit separately from arranging help or moving materials. Later, consolidate the setup that worked rather than collecting more rituals or demanding a stronger feeling of motivation."]}],example:{title:"Leila's covered time",text:"Thursday's study cue arrives during Leila's child's bedtime. Her partner agrees to cover five minutes after bedtime, so she moves the same question there. She answers at the table while care remains covered. She records the arrangement and the answer. The question needs work, and tomorrow's coverage is not assumed."},photo:{id:"1575478004055-999ebe26dab7",alt:"A woman walking in the rain with an umbrella"}},{id:"motivation-5",schemaVersion:2,title:"A missed day needs a workable return",minutes:6,goal:"Review the same experiment, retain one useful condition, and schedule a feasible next attempt.",reading:["Review your chosen reason, useful minimum, cue, and actual records. Progress monitoring can support goal attainment on average. It cannot turn an untried plan into behavior or make blank history mean failure. Keep preparation, actual work, and pause distinct when you decide what helped.","One missed opportunity did not materially disrupt habit formation in one study. That does not establish that long interruptions are harmless. Use your own conditions: repeat a setup that fit, change an unavailable cue, or reconsider the goal. Schedule the next useful unit. No doubling up, new ritual, or earned permission to rest is required."],practice:["Keep one condition that helped.","Change one barrier; schedule the same useful unit.","Try the minimum: Answer one practice question."],reflection:"Does this goal still deserve a place next week?",question:"Kofi missed four walks after his evening shift changed. Walking still matters to him. A short safe lunchtime route is available. Which return addresses the recorded barrier?",options:["Choose the available lunch cue, take the short safe walk, and record the return.","Keep the old dinner cue and reduce the walk to one loop around the block.","Prepare favorite audio for the old evening slot so the return feels more inviting."],correct:0,feedback:"This keeps the chosen goal while changing the condition that failed. The actual walk, not the planned return, is the behavior to record. Compare whether the lunch cue continues to fit.",takeaway:"Keep the reason and useful behavior; change the condition your record says has failed.",sources:["M13","M05","M20"],deeper:[{heading:"Consolidate evidence without inventing a streak",paragraphs:["Harkin and colleagues' review of 138 randomized studies found an average goal-attainment benefit from progress monitoring. Goals and methods varied. Recording and reporting moderators were associated with larger effects, but those results do not establish that public sharing or a weekly cadence is necessary. ODA's next-day return and brief weekly review are adaptations, not validated doses. [M13]","Lally's observational study found that one missed opportunity did not materially disrupt its modeled habit-formation process. That narrow result does not prove long interruptions leave a habit unchanged. [M05] Use your own attempts to choose what comes next. Keep a useful unit, change a cue or response that did not fit, and leave historical misses visible. A future plan is still planned. If the goal no longer deserves its time cost, reshape, defer, or stop it deliberately. Learning completion is separate from doing and reviewing the behavior."]},{heading:"Enjoyment is optional; support can come now",paragraphs:["Your final lesson consolidates the experiment rather than adding a new motivational ritual. Monitoring research supports comparing actual progress with a chosen goal on average, but it does not identify which technique is best for every person. Your record can show whether a cue was unavailable, whether materials were missing, or whether the goal's time cost stopped fitting. Use that observed condition to choose one next change. Do not count preparation or a promise as the behavior. [M13]","Do not make basic rest or all enjoyable activity conditional on productivity. If you later choose compatible free audio, preserve traffic and safety awareness. Persistent loss of interest, distress, exhaustion, or trouble completing usual activities may need professional assessment. NIMH guidance supports seeking help and immediate assistance for urgent danger; it does not diagnose the cause from low motivation or require waiting before asking for help. [M20] You can keep a small useful practice, request support, or pause while that concern is addressed."]}],example:{title:"Leila's next opening",text:"On Sunday, Leila reviews the same qualification plan. Dinner slots worked twice; a changed shift blocked two others. She still chooses the goal, so she moves one question to Monday's available lunch break with accessible notes. She writes down the next opening. The missed sessions stay missed, and Monday's action remains a plan."},photo:{id:"1577950248429-7530424d9682",alt:"A monthly calendar pinned to a board"}}].map((e,t)=>{const a=c[t];return{...e,schemaVersion:2,title:a.title,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,takeaway:a.carry.takeaway,v2:a}})},U=Object.freeze(Object.defineProperty({__proto__:null,COURSE:T,LESSONS_V2:c,SOURCES:x},Symbol.toStringTag,{value:"Module"})),h=[{id:"manifest-T01",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 independent effects from 21 articles, 15,907 participants: mental contrasting plus if-then planning supported goal attainment on average, g = .336 [.229, .443]. Bias adjustment estimated .242 [.143, .342].",limitation:"Effects varied and publication bias was indicated. No guarantee of success, proof that discomfort is necessary, or test of this library and its ritual adaptations."},{id:"manifest-T02",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"A foundational meta-analysis of 94 independent tests, 8,461 participants found an average goal-attainment benefit from specific if-then plans, d = .65 [.60, .70].",limitation:"Older heterogeneous evidence, not uniformly preregistered. A plan cannot remove external barriers, eliminate effort, or guarantee another person's decision."},{id:"manifest-T03",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 randomized experiments, 19,951 participants overall: encouraging progress monitoring improved goal attainment on average, d = .40 [.32, .48]. Recording progress was associated with larger effects across studies.",limitation:"Interventions and goals varied. Study-level moderators do not prove every recording feature works. Tomorrow's review is an ODA adaptation, not an established optimal schedule."},{id:"manifest-T04",title:"Cole et al. · 2021 · Mental simulation and behavior change",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 studies, 123 effects, 5,685 participants: mental simulation supported later behavior on average, g = .49 [.37, .62]. The omnibus comparison did not establish differences between simulation subtypes.",limitation:"Mostly student samples, varied tasks and simulations. Several subgroups had few effects. No reliable subtype ranking, external-event attraction, or special bedtime advantage was established."},{id:"manifest-T05",title:"Kappes & Oettingen · 2011 · Idealized positive fantasies",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Four experiments found that some idealized positive-future fantasies reduced immediate energy, with some subsequent accomplishment differences. This distinguishes pleasurable fantasy from preparation for effort.",limitation:"Short experiments, primarily student samples. Not all optimism or imagination is harmful. The proposed brain signal that a goal is already completed was not measured."},{id:"manifest-T06",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements",url:"https://journals.sagepub.com/doi/abs/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Two experiments found that repeating a strongly positive self-statement could worsen mood among participants with low self-esteem; benefits for high-self-esteem participants were limited.",limitation:"Specific statements, samples and short-term outcomes. This does not show that all encouraging language harms people or test every affirmation practice. A believable action line is an ODA adaptation."},{id:"manifest-T07",title:"Epton et al. · 2015 · Self-affirmation and health behavior",url:"https://pubmed.ncbi.nlm.nih.gov/25133846/",type:"research",finding:"144 experimental tests examined affirmation of important values, attributes or relationships alongside health information. Effects were small for acceptance and intentions; 46 behavioral tests, 2,715 participants, yielded d = .32 [.19, .44].",limitation:"Values-based self-affirmation differs from repeating a desired outcome as fact. Health-message findings do not establish that repeated slogans attract jobs, money or relationships."},{id:"manifest-T08",title:"Carrillo et al. · 2019 · Best possible self meta-analysis",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 studies, 2,909 participants: writing about a best possible future after working toward it improved wellbeing, optimism and positive affect on average compared with controls.",limitation:"Mostly young student samples; no study met every quality criterion. Mood and optimism outcomes do not prove attainment of external goals or efficacy of present-tense scripting."},{id:"manifest-T09",title:"Davis et al. · 2016 · Gratitude interventions meta-analysis",url:"https://scottbarrykaufman.com/wp-content/uploads/2021/05/davis2016.pdf",type:"research",finding:"Randomized gratitude studies showed small average wellbeing benefits against some controls. Gratitude did not outperform psychologically active alternatives for wellbeing; anxiety findings were inconclusive.",limitation:"Effects depend on comparison activities and study quality. This does not establish a universal journaling dose, external-event attraction or the added effect of gratitude written as though a future event happened."},{id:"manifest-T10",title:"Cregg & Cheavens · 2021, online 2020 · Gratitude and symptom change",url:"https://link.springer.com/article/10.1007/s10902-020-00236-6",type:"research",finding:"27 studies, 3,675 participants: gratitude interventions had small average effects on pooled depression/anxiety symptoms, with larger effects against waitlist than active controls. The separate anxiety analysis had five studies and was inconclusive.",limitation:"Modest symptom findings do not establish gratitude as sufficient treatment. The authors recommend stronger-evidence interventions for people seeking relief from depression or anxiety."},{id:"manifest-T11",title:"Locke & Latham · 2002 · Goal setting and task motivation",url:"https://med.stanford.edu/content/dam/sm/s-spire/documents/PD.locke-and-latham-retrospective_Paper.pdf",type:"research",finding:"A review of decades of goal-setting research describes how specific, challenging goals can support performance, with commitment, feedback, ability and task complexity affecting results.",limitation:"Narrative theory review, not a test of manifestation rituals. Goals require feasible strategies and resources; novel or complex tasks may need learning goals rather than pressure for immediate performance."},{id:"manifest-T12",title:"Frattaroli · 2006 · Expressive disclosure meta-analysis",url:"https://bpb-us-e2.wpmucdn.com/faculty.sites.uci.edu/dist/c/602/files/2019/08/Frattaroli-psych-bulletin-2006.pdf",type:"research",finding:"146 randomized studies of disclosure about experiences or feelings found a small average benefit across outcomes, mean r = .075 [.052, .098]. Effects varied by outcome and procedure.",limitation:"Writing about real experiences differs from scripting a wished-for event as fact. This review does not validate every journal, promise trauma recovery, or show that written stories cause external outcomes."},{id:"manifest-T13",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Manifestation beliefs",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Three US online survey samples, 1,023 participants: manifestation belief correlated with confidence and some reported financial risks and bankruptcy, but not reported income or education.",limitation:"Associations and self-reported outcomes do not establish causation, population prevalence, or effectiveness of each technique. Confidence is not objective evidence of success."},{id:"manifest-T14",title:"Denrell · 2003 · Undersampling failure and success stories",url:"https://pubsonline.informs.org/doi/10.1287/orsc.14.2.227.15164",type:"research",finding:"An analysis of learning from surviving organizations shows how undersampling failure can make an unrelated practice appear associated with success.",limitation:"Organizational models, not a study of the owner's viral post. Applying the sampling principle to manifestation testimonials is an inference; it does not show that a particular storyteller is dishonest."},{id:"manifest-T15",title:"Awh, Belopolsky & Theeuwes · 2012 · Attentional control",url:"https://research.vu.nl/en/publications/top-down-versus-bottom-up-attentional-control-a-failed-theoretica/",type:"research",finding:"This attention review describes selection shaped by current goals, physical salience and past selection history. A goal can influence what receives attention, alongside other influences.",limitation:"Visual-attention theory does not test vision boards, affirmations, a single RAS wish filter or the creation of external opportunities. Noticing an opening and causing it to exist are different claims."},{id:"manifest-T16",title:"Dai et al. · 2023 · Behavioral priming meta-analysis",url:"https://socialactionlab.org/wp-content/uploads/2024/01/Dai_Priming-Behavior-A-Meta-Analysis-of-the-Effects-of-Behavioral-and-Nonbehavioral-Primes-on-Overt-Behavioral-Outcomes_2023.pdf",type:"research",finding:"351 studies, 862 effects: the review found an average behavioral priming effect. The smaller preregistered subset had smaller, statistically inconclusive effects, highlighting uncertainty about reliability and conditions.",limitation:"Incidental experimental primes differ from deliberate manifestation rituals. The small preregistered subset does not disprove all priming; the aggregate does not validate repeated phrases, exact time thresholds or cosmic attraction."},{id:"manifest-T17",title:"Pham & Taylor · 1999 · Process versus outcome simulation",url:"https://journals.sagepub.com/doi/abs/10.1177/0146167299025002010",type:"research",finding:"An early exam study favored simulating study processes over imagining only a good grade, with planning and anxiety helping explain grade differences. The process main effect on grades was marginal; a post-hoc process-only versus outcome-only comparison was significant.",limitation:"The process-versus-control exam result was not significant in the later Cole synthesis, which established no universal subtype winner. A narrow early study does not show reliable grade gains against control or external-event attraction."},{id:"manifest-T18",title:"Taylor et al. · 1998 · Mental simulation and self-regulation",url:"https://pubmed.ncbi.nlm.nih.gov/9572006/",type:"research",finding:"This account of a research program distinguishes imagining the process and coping with difficulties from imagining only successful completion, emphasizing planning and problem solving.",limitation:"A research-program review, not a comprehensive meta-analysis or proof that process imagery always wins. Use with the later Cole synthesis and an actual attempt."},{id:"manifest-T19",title:"Larson-Prior, Ju & Galvin · 2014 · Sleep, wakefulness and arousal circuits",url:"https://www.frontiersin.org/journals/neurology/articles/10.3389/fneur.2014.00165/full",type:"research",finding:"A neuroscience review describes the reticular activating system within interacting circuits involved in wakefulness and cortical arousal.",limitation:"Arousal neuroscience does not establish that writing a wish programs a brain filter to deliver opportunities, or that a drowsy state makes thoughts alter external events. No manifestation ritual was tested."}];function A(e){const t=`manifest-${e.number}`;return{schemaVersion:2,revision:1,id:t,courseId:"manifest",locale:"en",title:e.title,goal:e.goal,minutes:{learning:5,suggestedAction:5,review:2},direction:{hook:e.hook,reason:{id:`${t}-reason`,label:e.reason,kind:"text",maxLength:160,optional:!0,suggestions:["My goal; fewer repetitions","Action before more preparation","Support before another attempt"]},why:{id:`${t}-purpose`,label:"Why does this move matter in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:e.paragraphs,example:e.example},move:{invitation:"Keep your goal. Choose one useful action.",instructions:e.instructions,prompts:[],suggestions:{action:e.action,minimum:e.minimum,cue:e.cue,place:e.place,fallback:e.fallback,observation:e.observation,minutes:[5,2,10],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:e.action[0],minimum:e.minimum[0],minutes:5,cueHint:e.cue[0],placeHint:e.place[0],obstacleHint:e.obstacle,fallbackHint:e.fallback[0],observationHint:e.observation[0]},accessibleAlternative:"Type, dictate, or describe the ritual; no supplies or vivid images are required.",stopRule:e.stopRule},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, separately from the ritual?"},judgment:{primary:{id:`${t}-decision`,scenario:e.scenario,question:e.question,options:e.options.map(a=>({id:`${t}-${a.key}`,text:a.text,feedback:a.feedback})),bestOptionId:`${t}-${e.best}`}},carry:{takeaway:e.takeaway,followUp:{questionId:`${t}-return`,question:e.review,observationPrompt:"What happened at your saved opportunity, including any outside response?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:e.deeper,sourceIds:e.sources}}}function I(e){const t=e.judgment.primary;return{id:e.id,schemaVersion:2,v2:e,title:e.title,goal:e.goal,minutes:e.minutes.learning,photo:k(e.id,e.locale),reading:e.idea.paragraphs,example:e.idea.example,practice:e.move.instructions,reflection:e.carry.followUp.question,question:t.question,options:t.options.map(a=>a.text),correct:t.options.findIndex(a=>a.id===t.bestOptionId),feedback:t.options.find(a=>a.id===t.bestOptionId).feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,deeper:e.goDeeper.sections}}const q=[{number:13,technique:"Pillow method",title:"Pillow method: give the note a waking job",goal:"Keep the bedtime note and connect it to a waking action.",hook:"A wish under your pillow can stay. Give the note something useful to remind you of tomorrow.",reason:"Would daytime planning leave more room for sleep?",paragraphs:["The pillow method means placing a written wish under your pillow. A common recipe is to write it as already true, fold the paper, place it underneath, then repeat or imagine the outcome before sleep. That paper delivering an external result is not supported by the evidence reviewed. [manifest-P08, manifest-T19]","ODA version: keep the note, add a specific goal and likely obstacle, then write an if-then plan for one action. Specific cue-and-response plans have research support; special bedtime attraction does not. Do one useful act today, review tomorrow, and leave further planning for daytime if it keeps you awake. [manifest-T02, manifest-T19]"],example:{title:"The morning message",text:"At her kitchen table, Maya writes a job wish and sends one tailored application. Her pillow note adds: if breakfast dishes are cleared, check a new suitable vacancy. Next morning she checks it and starts another application. It needs more detail. Her record keeps the submission and unfinished draft separate; no employer has replied."},instructions:["Keep the note; add your goal and obstacle before settling for sleep.","Write an if-then cue and do one useful action today.","Tomorrow, review the attempted action separately from the pillow ritual."],action:["Send one tailored application","Ask one contact about an opening"],minimum:["Submit one suitable application","Send one specific question"],cue:["After clearing breakfast dishes","After today's lunch break"],place:["At the kitchen table","At my usual workspace"],obstacle:"Bedtime planning keeps me awake",fallback:["Plan during tomorrow's lunch break","Use a daytime note instead"],observation:["Application submitted; reply still unknown","Question sent; response recorded separately"],stopRule:"Stop if the ritual delays sleep. Move planning to daytime; no bedtime repetition is required.",scenario:"Maya's note names a morning question about a suitable vacancy. Rewriting it at bedtime keeps her awake, although tomorrow's cue is already clear.",question:"What should she do tonight?",options:[{key:"a",text:"Rewrite the note once more, then decide tomorrow whether the vacancy question still feels right.",feedback:"Another rewrite costs sleep without adding a needed detail. Her cue is clear already. Keep the planned question and move any further editing to daytime."},{key:"b",text:"Leave the note alone, let herself sleep, and ask about the vacancy at her waking cue.",feedback:"This protects sleep and preserves the useful commitment. Tomorrow she can record whether she sent the question, while keeping an employer's reply separate from her action."},{key:"c",text:"Replace the morning follow-up with a longer daytime visualization of the employer's reply.",feedback:"Daytime is a better place for extended planning, but this replaces an available useful act. Imagining a reply does not send the message or establish what the employer will decide."}],best:"b",takeaway:"Keep the pillow note brief and give its action a waking cue.",review:"What action did you attempt after the note, and did bedtime planning interfere with sleep?",deeper:[{heading:"The familiar pillow recipe",paragraphs:["1. Choose a desired outcome and write one present-tense line, such as an imagined offer already received. This follows a practitioner recipe; the line records a wish rather than verified news. You can keep the wording private. [manifest-P08]","2. Fold the paper and place it under your pillow. The guide includes additional writing and folding details, but these describe that author's variant. They are not established requirements for an external result. Use an ordinary note you already have. [manifest-P08]","3. Read or mentally repeat the line while settling into bed. Imagine the outcome as fulfilled if you enjoy that part. Then let yourself sleep; do not make vivid imagery, repetition or a particular feeling a condition for stopping. [manifest-P08]","4. Revisit the note on another evening if wanted. The guide documents a recognizable ritual, not controlled efficacy evidence. A review of arousal circuits does not establish that bedtime wishes bypass critical thought or make outside events happen. [manifest-P08, manifest-T19]"]},{heading:"A note with a waking job",paragraphs:["Add a small practical instruction before you get into bed. Write the specific goal, the obstacle you expect, and the action you can actually take. For a job search: 'If breakfast is cleared, I will submit one suitable application. If the form is confusing, I will ask the recruiter one specific question.' Keep uncertain outcomes, such as an offer, separate from the action. [manifest-T02]","Gollwitzer and Sheeran's meta-analysis found an average goal-attainment benefit from specific if-then plans across varied settings. It did not test paper under pillows or establish that planning removes effort. The arousal review describes interacting wakefulness circuits, not a subconscious route for delivering wishes. These are different claims. [manifest-T02, manifest-T19]","ODA adds today's attempt and tomorrow's review as practical choices, not a tested bedtime package. Record what you sent, asked or completed; record any response separately. If editing the note keeps you awake, leave it and choose a daytime opportunity. Your next useful act does not require finishing the ritual. [manifest-T02, manifest-P08]"]}],sources:["manifest-P08","manifest-T02","manifest-T19"]},{number:14,technique:"Whisper method",title:"Whisper method: rehearse a request you can make",goal:"Turn an imagined exchange into one respectful request under your control.",hook:"Waiting for someone to text back? The whisper ritual can help you choose your own next step.",reason:"Is there an appropriate request I can make?",paragraphs:["The whisper method is an imagined request to another person. In a common recipe, relax, picture approaching them, whisper what you want three times, then leave the scene. Remotely making that person respond is not supported by the evidence reviewed. Their consent and boundaries still matter. [manifest-P09]","ODA version: keep the private whisper, choose a specific goal and name the obstacle. Rehearse a respectful request, including room for refusal. Write an if-then plan for one appropriate action today, then review your action tomorrow. Cue-and-response planning has support; feeling certain about someone else's response is not evidence that they will agree. [manifest-T02, manifest-T13]"],example:{title:"Asking without pushing",text:"At lunch, Ben imagines whispering a request for a project meeting. He changes it to a sentence he can send: 'Could we talk for ten minutes Thursday?' His colleague replies that Thursday is full. Ben records the message and refusal, then asks whether next week suits. His ritual did not obligate her to agree."},instructions:["Whisper a respectful request privately; leave room for the person to decline.","Name your goal, obstacle and if-then plan; make one appropriate request today.","Tomorrow, review what you asked and how you respected the response."],action:["Ask for a brief project meeting","Send one appropriate availability question"],minimum:["Send one clear meeting request","Ask one relevant question"],cue:["After today's lunch break","When the agreed check-in begins"],place:["At my work desk","In our usual meeting space"],obstacle:"I keep editing a simple request",fallback:["Use one plain request sentence","Ask at the agreed check-in"],observation:["Request made; answer recorded separately","Boundary respected; next step chosen"],stopRule:"Do not contact someone who has declined contact. Private imagery cannot override another person's boundaries.",scenario:"Ben wants a meeting. His colleague has said this week is full but invited him to ask about next week. His whisper practice feels reassuring.",question:"Which next move fits the information he has?",options:[{key:"a",text:"Ask once about next week's availability, then accept the answer without repeated messages.",feedback:"She offered that opening, so one clear question respects it. He can record the request and response separately. His reassurance gives him no claim over her time."},{key:"b",text:"Wait for her to suggest a time because the imagined exchange now feels complete.",feedback:"Waiting may be his choice, but the imagined exchange did not ask about next week. Her invitation gives him a suitable opening for one real request if the meeting still matters."},{key:"c",text:"Send a warmer explanation of why this week's meeting would mean so much to him.",feedback:"A warmer message still asks her to reconsider the week she ruled out. Use the opening she actually offered, rather than making stronger feelings a reason to press her."}],best:"a",takeaway:"Rehearse your request; another person's answer remains theirs.",review:"What request did you actually make, and how did you respond to their answer or boundary?",deeper:[{heading:"The popular imagined exchange",paragraphs:["1. Pick the person and desired response. In the practitioner account, the exercise happens in imagination. Choosing a response describes what you want; it does not show what that person wants or establish permission to contact them. [manifest-P09]","2. Relax and picture that person in a setting. Imagine approaching them and whispering the request in their ear three times. The count is part of this recipe, not a scientifically established dose for influencing someone. Eyes-open or verbal description can be your adaptation. [manifest-P09]","3. Leave the imagined scene. Some variants add a pictured forehead kiss, which is another scene detail rather than evidence of remote influence. In ODA, keep any exercise private and choose a request you could make respectfully. Do not treat imagined intimacy as consent. [manifest-P09]","4. Decide whether an actual request is appropriate. The practitioner story documents the ritual but cannot demonstrate telepathy or control. A person may decline, stay silent or change their mind; repeated whispers do not create an obligation to respond. [manifest-P09]"]},{heading:"Plan your side of the conversation",paragraphs:["Keep the goal specific: asking for an available meeting is different from making someone admire you. Name an obstacle you can respond to, such as delaying a short message through repeated editing. Then choose a cue: 'If my lunch break ends, I will send one clear availability question.' If contact is unwelcome, your action can be respecting that boundary. [manifest-T02, manifest-P09]","Implementation-intention research supports connecting a detectable situation with a chosen response. It does not establish control over the recipient. In three online survey samples, Dixon and colleagues found manifestation belief associated with confidence and some reported financial risks. Those associations do not establish causation, and that study did not test whispering. Feeling certain is not a measurement of someone else's agreement. [manifest-T02, manifest-T13]","ODA's private rehearsal and next-day return are adaptations. Make one appropriate request today or save an agreed opportunity. Tomorrow, write what you actually asked, any answer received, and whether you respected it. Silence stays unknown. Choose another appropriate step or stop; do not count the imagined exchange as the real conversation. [manifest-T02, manifest-P09]"]}],sources:["manifest-P09","manifest-T02","manifest-T13"]},{number:18,technique:"17-second focus",title:"17-second focus: let the timer cue an action",goal:"Use a preferred pause to cue action, without a scientific timing claim.",hook:"Your mind wandered before seventeen seconds. That does not cancel your chance to take the next step.",reason:"Does the timer help me start or delay?",paragraphs:["The 17-second method means holding a desired thought without contradiction for seventeen seconds. Some versions repeat four intervals, totaling sixty-eight seconds. The special timing and attraction threshold are not supported by the evidence reviewed. Priming research does not validate those counts or deliberate wish rituals. [manifest-P13, manifest-T16]","ODA version: keep seventeen seconds as a preferred pause, then name a specific goal and obstacle. Write an if-then plan for one action today and review the attempt tomorrow. Specific planning has research support. A wandering thought is no reason to restart before acting; the timer is your cue, not a requirement for getting results. [manifest-T02, manifest-P13]"],example:{title:"The interrupted pause",text:"Before lunch, Aisha sets a seventeen-second timer for her portfolio goal. A delivery interrupts her thought. She leaves the timer alone and follows her plan: after lunch, send one work sample to a suitable client. The client asks for a different style. Aisha records the message and the feedback rather than restarting her focus exercise."},instructions:["Choose your goal; use seventeen seconds as an optional pause.","Name an obstacle and if-then plan; take one useful action today.","Review the attempted action tomorrow, including any feedback you received."],action:["Send a relevant work sample","Request feedback on one draft"],minimum:["Send one suitable sample","Ask one specific feedback question"],cue:["After today's lunch","When the optional timer ends"],place:["At my usual workspace","At the library desk"],obstacle:"I restart whenever my attention wanders",fallback:["Skip the timer and send","Use a written action cue"],observation:["Sample sent; reply recorded separately","Question asked; feedback still unknown"],stopRule:"Skip the timer if restarting delays action or feels distressing. Unwanted thoughts require no ritual correction.",scenario:"Aisha's prepared sample fits a client's request. A notification interrupted her focus timer. She has five minutes to send the sample before a meeting.",question:"What makes best use of this opening?",options:[{key:"a",text:"Repeat the focus once without notifications, then send if enough time remains before the meeting.",feedback:"Removing notifications can help a preferred pause, but the available task is already clear. Making another uninterrupted interval a condition risks losing the useful opening she has now."},{key:"b",text:"Save both the focus exercise and sample message for a longer uninterrupted session tomorrow.",feedback:"A later appointment can fit a task that needs more time. Here the sample is prepared and five minutes are available; an interrupted ritual does not require postponing the message."},{key:"c",text:"Send the prepared sample now and record the message separately from the interrupted focus pause.",feedback:"This uses the available opening and keeps an honest record. The sample was sent; the pause was interrupted. Neither fact tells her what the client will decide."}],best:"c",takeaway:"Let the timer cue your action rather than set a condition for it.",review:"What useful action did you attempt, and did the timer help you start or delay?",deeper:[{heading:"What the seventeen-second recipe asks",paragraphs:["1. Choose a desired experience or positive thought. The teaching attributed to Abraham through Esther and Jerry Hicks asks for attention to that thought without an opposing thought. This describes the ritual rather than a research-tested procedure. [manifest-P13]","2. Hold the thought for seventeen seconds. Some versions extend through four consecutive intervals, giving sixty-eight seconds. You can use a timer if you want the recognizable format, but the inspected evidence does not establish a special attraction threshold at either duration. [manifest-P13, manifest-T16]","3. Notice whether attention wandered, without turning that into a verdict on your future. ODA removes restarting as a condition for action. The teacher's claims about thoughts changing reality or equaling many hours of work are not findings from the research reviewed. [manifest-P13]","4. End the pause and choose your next act. Experimental priming concerns cues studied in particular conditions; it is not the same as this deliberate timed wish. A preferred interval can remain part of your ritual without acquiring scientific authority. [manifest-T16, manifest-P13]"]},{heading:"Use the end as a start cue",paragraphs:["Pick one action before the timer begins. For a portfolio goal, that might be sending one suitable work sample today. Name the obstacle: restarting until focus feels perfect. Then write, 'If the timer ends, I will send the prepared sample, even if my attention wandered.' If a timer adds pressure, use another visible cue instead. [manifest-T02]","Gollwitzer and Sheeran's meta-analysis supports specific if-then planning on average across varied tasks. Dai and colleagues' priming review found an average effect overall, but smaller, statistically inconclusive effects in its limited preregistered subset. That uncertainty does not disprove all priming. Neither review validates seventeen seconds, sixty-eight seconds or a rule that unwanted thoughts block outcomes. [manifest-T02, manifest-T16]","The ODA pause-and-action sequence is an adaptation, not either research protocol. Tomorrow, record the action attempted and any outside feedback separately from the quality of your focus. Did the pause provide a workable cue, or did repeated attempts consume the opening? Keep, shorten or drop the timer according to that practical record. [manifest-T02, manifest-P13]"]}],sources:["manifest-P13","manifest-T02","manifest-T16"]},{number:19,technique:"Box method",title:"Box method: give one wish an action date",goal:"Keep the wish box and take one feasible step toward a specific goal.",hook:"Your box holds things you want. Which card gets an action today?",reason:"Which wish fits my time and resources today?",paragraphs:["The box method stores written wishes, pictures or meaningful objects in a container. A common recipe is to choose a box, add intentions and desired feelings, then revisit them while imagining fulfillment. A container delivering those wishes is not supported by the evidence reviewed. An existing box is enough. [manifest-P14]","ODA version: keep the cards. Add a specific goal, obstacle, if-then plan and one action today to a chosen card; review its actual attempt tomorrow. Contrasting a goal with obstacles and a response plan has research support, as does progress monitoring on average. This box adaptation is not a tested package. [manifest-T01, manifest-T03]"],example:{title:"One card leaves the box",text:"At the kitchen table, Luca puts a card for a weekend course into an old shoebox. He writes the obstacle, limited time, and calls the organizer to ask about attendance options. The course has no flexible option. Tomorrow he records the call and chooses a different course rather than adding more wishes to the box."},instructions:["Choose an existing container and one card with a specific goal.","Add an obstacle and if-then response; take one feasible action today.","Open that card tomorrow and record the actual attempted action."],action:["Ask about course attendance options","Request one relevant program detail"],minimum:["Send one specific course question","Make one useful inquiry"],cue:["After today's breakfast","When the office phone line opens"],place:["At the kitchen table","In my quiet work corner"],obstacle:"The schedule may not fit",fallback:["Ask about another attendance option","Contact one suitable alternative"],observation:["Inquiry sent; schedule answer recorded","Alternative contacted; response still unknown"],stopRule:"Use supplies you already have. If an option exceeds your resources, change the action or pause.",scenario:"Luca's course card names a schedule conflict. The organizer can answer questions today. He also has several new pictures he wants to add to the box.",question:"Which next move best tests whether this course fits?",options:[{key:"a",text:"Ask the organizer about attendance options, then write the answer on the course card.",feedback:"This tests the named obstacle and creates an actual record. The answer may rule out this course, which still helps Luca choose a feasible next step."},{key:"b",text:"Add the new pictures first so the box reflects the full experience he wants.",feedback:"The pictures can stay part of his preferred ritual. They do not answer the schedule question, though. Today's opening is a chance to learn whether the course is feasible."},{key:"c",text:"Choose a different course immediately, since the schedule conflict makes this one uncertain.",feedback:"A different course may fit better, but the organizer can clarify this uncertainty now. One specific inquiry gives him useful information before he decides whether to change the goal."}],best:"a",takeaway:"Keep the wish card, add a feasible action, and record what actually happened.",review:"What action did you attempt for the card, and what did you learn about its obstacle?",deeper:[{heading:"Build the familiar wish box",paragraphs:["1. Choose a box or container. The practitioner guide uses the box as a place for intentions. ODA asks you to use something already available, such as an old shoebox or envelope. Buying a special object is not part of the assignment. [manifest-P14]","2. Write wishes on cards or choose pictures representing them. The guide also includes why you want each outcome and how receiving it would feel. Keep those personal details private if you prefer; a plain label can preserve the format. [manifest-P14]","3. Put the cards or pictures inside. Return to the contents and imagine receiving the wishes if you enjoy that ritual. These steps describe a first-person practitioner's method, not evidence that the container creates an external event. [manifest-P14]","4. Choose one card to connect with a real opportunity. The guide's energy-field explanation is a belief rather than an established research finding. You can keep the symbolic container while changing what you do with a card today. [manifest-P14]"]},{heading:"Put the obstacle on the back",paragraphs:["Keep the wish or image on the front. On the back, write the goal in specific terms, a likely obstacle and an if-then response. For a course: 'If the organizer's phone line opens, I will ask about attendance options. If the schedule cannot work, I will inquire about one suitable alternative.' Choose a feasible action today rather than counting card-making as the inquiry. [manifest-T01]","Mental contrasting with implementation intentions links a wished-for outcome, a real obstacle and a response plan. Its meta-analysis found modest average support for goal attainment, with varied results and possible publication bias. Harkin and colleagues found average benefits from encouraging progress monitoring. Neither review tested a manifestation box or proved that tomorrow is the best review schedule. [manifest-T01, manifest-T03]","ODA's next-day return gives this card a practical review point. Record what you actually asked and what you learned; distinguish a sent inquiry from a useful reply or enrollment. Change the goal when money, access or time makes it infeasible. The box can hold a revised card, a paused goal or an honest unsuccessful attempt. [manifest-T01, manifest-T03]"]}],sources:["manifest-P14","manifest-T01","manifest-T03"]},{number:20,technique:"SATS: state akin to sleep",title:"SATS: let the scene end in sleep",goal:"Keep gentle imagery and rehearse a practical step without delaying sleep.",hook:"Repeating the perfect bedtime scene? You can stop and still take a useful step tomorrow.",reason:"Does this scene leave enough room for sleep?",paragraphs:["SATS, or state akin to sleep, is imagining a short fulfillment scene while relaxed and drowsy. Practitioners choose a scene implying success, imagine participating, and repeat it as real. Some let themselves fall asleep. Verdict: mixed for related imagery, not supported for drowsy wish delivery. Mental simulation supports behavior on average, without establishing a special bedtime advantage. [manifest-P15, manifest-T04, manifest-T19]","ODA version: keep gentle imagery. Name your specific goal and obstacle, write an if-then plan, then rehearse the first practical step. Take one action today and review tomorrow. The scene need not feel perfect. Stop if repetition keeps you awake; sleep is not a test of belief. [manifest-P15, manifest-T19]"],example:{title:"A scene with a limit",text:"At her desk, Nina sends a question about a training program. Before bed she briefly imagines attending, then rehearses asking about fees at tomorrow's lunch break. Repeating the scene makes her alert, so she stops. Next day she asks; the program costs too much. She records that answer and looks for a free option."},instructions:["Before settling, name your goal, obstacle and if-then plan on a note.","Rehearse the first step briefly; take one useful action today.","Let sleep take priority; review your actual attempted action tomorrow."],action:["Ask about a program's fees","Request one useful access detail"],minimum:["Send one specific fee question","Ask one access question"],cue:["After today's lunch break","When the program office opens"],place:["At my usual workspace","At the kitchen table"],obstacle:"Imagery keeps me awake",fallback:["Use a daytime verbal rehearsal","Skip imagery and ask directly"],observation:["Question asked; reply recorded separately","Sleep interference noticed; imagery stopped"],stopRule:"Stop if imagery increases wakefulness or distress. Use daytime rehearsal or skip it; protect sleep.",scenario:"Nina has a clear daytime plan to ask about fees. Her repeated SATS scene is keeping her alert, and it still does not feel fully real.",question:"What should she choose now?",options:[{key:"a",text:"Make the scene simpler and keep repeating until it feels convincing enough to end.",feedback:"Simplifying may suit a daytime rehearsal, but conviction is not a required stopping condition. Repetition is keeping her alert, so continuing puts the ritual ahead of sleep."},{key:"b",text:"Stop the scene, let herself sleep, and ask about fees at the daytime cue.",feedback:"Her practical cue is already clear. Stopping protects sleep without abandoning the goal. Tomorrow she can record the question she asked and any fee information she received."},{key:"c",text:"Replace the fee question with a longer daytime SATS session that feels easier to control.",feedback:"Daytime may fit optional imagery better, but a longer scene still does not answer the fee question. Keep the real inquiry and treat any rehearsal as preparation."}],best:"b",takeaway:"A brief scene can end before it feels perfect; the real attempt gets its own record.",review:"What action did you actually attempt, and did the imagery leave room for sleep?",deeper:[{heading:"The scene in the SATS teaching",paragraphs:["1. Choose an outcome and a short scene implying that it has happened. Neville Goddard's lectures describe participating in a fulfillment scene rather than watching yourself from outside. This is the teacher's method, not a demonstrated route for changing external events. [manifest-P15]","2. Sit or lie comfortably, close your eyes if wanted, and relax toward drowsiness. The source treats this state as part of the practice. ODA permits an eyes-open or verbal adaptation and does not ask you to force drowsiness. [manifest-P15]","3. Repeat the brief scene while imagining it as real. Some versions allow sleep to arrive in that feeling; others remain gently attentive. You can stop before the scene feels convincing. Do not keep yourself awake to achieve an imagined standard. [manifest-P15]","4. Leave metaphysical claims separate from the recipe. An arousal review describes interacting sleep and wakefulness circuits, not evidence that a drowsy state makes wishes real. Goddard's no-action-needed teaching is not a conclusion from mental-simulation research. [manifest-P15, manifest-T19, manifest-T04]"]},{heading:"Rehearse a step while protecting sleep",paragraphs:["Choose a specific goal and name the obstacle before settling down. For a training program, the goal might be checking whether fees fit your resources. Briefly rehearse asking the actual question, including what you will do if the answer rules the program out. This is ODA's practical adaptation; it need not reproduce Goddard's prescribed feeling or scene. [manifest-P15, manifest-T04]","Cole and colleagues' synthesis found an average behavioral benefit from mental simulation across varied studies, mostly with students. It did not establish a reliable ranking between simulation subtypes or a special bedtime advantage. The arousal review likewise does not show that drowsiness bypasses thought or delivers outside outcomes. General imagery evidence cannot validate every SATS claim. [manifest-T04, manifest-T19]","Use a daytime cue for the real question and make one useful inquiry today when appropriate. Tomorrow, record the inquiry and reply separately from the imagery. If the scene increases wakefulness, stop and choose daytime rehearsal or no imagery. The next action can remain scheduled even when you leave the scene unfinished. This full sequence has not been tested as a SATS intervention. [manifest-P15, manifest-T04, manifest-T19]"]}],sources:["manifest-P15","manifest-T04","manifest-T19"]}],S=[{number:6,technique:"3-6-9 method",title:"3-6-9: put your applications on the page",goal:"Keep the notebook and complete one step toward a specific target.",hook:"Writing “I got the job” again? Give the company on your other page an application.",reason:"Will this notebook lead to work you want, or take time from applying?",paragraphs:["The 3-6-9 method repeats a present-tense affirmation three times in the morning, six at noon, nine at night. In the two-page variant, desired companies go left and “I got the job” goes right. Not supported: special counts attracting an offer. A success story cannot separate repetitions from applications or show the unsuccessful attempts.","ODA version: keep the pages and optional rhythm. Left: specific targets plus today’s apply, follow-up, or preparation step. Right: a credible identity line and an if-then response to one obstacle. Specific cue-response plans have research support. Do one target action today; tomorrow review the act and any reply separately."],example:{title:"Maya uses both pages",text:"Maya lists two logistics companies on the left page and “I prepare useful applications” on the right. After lunch, she checks one vacancy and sends a tailored résumé. Her plan says, “If the portal fails, save the draft and contact recruitment.” One portal fails. She records the contact request; neither company has offered anything."},instructions:["Left page: name a target and today’s apply, follow-up, or preparation step.","Right page: add an identity line and an obstacle-response if-then plan.","Do the target action; review your attempt and any reply tomorrow."],action:["Send a tailored application","Send a company follow-up"],minimum:["Submit one suitable application","Send one follow-up question"],cue:["After lunch ends","When I finish the morning writing"],place:["At my application desk","In the company application portal"],obstacle:"The application portal will not load",fallback:["Save the draft and contact recruitment","Use another available application opening"],observation:["Submission or request, plus any reply","The application step I actually completed"],stopRule:"Skip repetitions that crowd out action; pause unaffordable or unsuitable applications.",scenario:"Maya wrote all 18 repetitions and listed three companies. One suitable vacancy closes tonight. Its application needs a short experience paragraph.",question:"What should her next notebook session produce?",options:[{key:"repeat",text:"Keep the affirmation schedule and prepare a longer identity statement before returning to the application.",feedback:"A statement can remain part of her ritual, but a longer one does not fill the application gap. With the deadline near, use the notebook to cue the required paragraph."},{key:"submit",text:"Write the required paragraph, submit the application, and record the submission separately from any employer reply.",feedback:"This matches the specific target and deadline. The submission is her action; a reply remains outside her control. Keep the ritual if she likes it, then review what actually happened."},{key:"expand",text:"Expand the company list first so tomorrow she can pursue a wider selection of potential jobs.",feedback:"A wider search may help later, but tonight there is a suitable opening with a concrete deadline. Expanding the list would delay the available application. Finish its missing paragraph first."}],best:"submit",takeaway:"Let the notebook cue an application. Count actions and replies separately.",review:"What target action did you attempt, and did any company respond?",deeper:[{heading:"The familiar recipe, including two pages",paragraphs:["1. Choose a desired outcome and phrase it as already true. 2. Write that affirmation three times in the morning. 3. Repeat it six times around noon. 4. Write it nine times at night. These numbers describe the popular recipe, not a research-backed dose. Practitioner accounts vary in how long they repeat the schedule. [manifest-P01]","5. In the owner’s two-page example, the right page says “I got the job”; the left lists companies she applied to and wants. She reports an offer from a listed company. This is an owner-provided story, not independently verified trial data. Applying survivorship bias here is an inference: the visible success leaves out people who tried the ritual without an offer. The story may be sincere while leaving its cause unresolved. [manifest-T14]"]},{heading:"Keep the rhythm, change what it cues",paragraphs:["The planning evidence concerns a recognizable situation linked to an achievable response. It does not establish that three, six, or nine repetitions influence an employer. Keep the count if it is enjoyable, and put the task beside it: a company, a suitable opening, and today’s action. The left-page list and actual applications provide a practical route toward an offer; this anecdote cannot prove which factor caused hers. [manifest-T02, manifest-T14]","On the right, try “I prepare useful applications.” Add “If the portal fails, I will save the draft and contact recruitment.” Check the deadline, access, and available time. Submit or ask today, then record the exact act. Tomorrow look for the employer’s response without treating silence as a belief problem. Repetitions, preparation, submissions, and offers remain separate entries. This two-page package is ODA’s adaptation, not a tested intervention. [manifest-T02]"]}],sources:["manifest-P01","manifest-T02","manifest-T14"]},{number:7,technique:"Scripting",title:"Scripting: write the work into your future",goal:"Use a future scene to choose and attempt one goal action.",hook:"Your imagined day has the perfect ending. What did you do before breakfast to reach it?",reason:"What will this page help you do before you write another one?",paragraphs:["Scripting is a journal entry written as though a desired future is happening now. Choose a scene, describe its details and feelings, then reread it. Mixed: related best-possible-self writing improved wellbeing and optimism on average; it did not establish that present-tense entries deliver events. Expressive writing studies concern real experiences, not wishes becoming facts.","ODA version: keep the scene, but include the work that led there. Name your specific goal, a current obstacle, and an if-then response. Underline one action you can attempt today. Tomorrow compare the attempted action with your plan, rather than judging whether the whole scene arrived. The combined exercise is an adaptation."],example:{title:"Elena adds the missing work",text:"Elena scripts a calm morning in a new role. She adds the interview preparation that would precede it. After dinner, she records one answer about handling a difficult customer. She hears herself rushing and marks one sentence to shorten. The job is still hypothetical, but there is a real recording to improve tomorrow."},instructions:["Write the future scene, including work and resources it would require.","Underline today’s action; add “If this obstacle appears, then I will…”","Attempt the minimum and review what happened tomorrow."],action:["Record one interview answer","Draft one portfolio caption"],minimum:["Save one answer recording","Save one usable caption"],cue:["After dinner is cleared","When I close my journal"],place:["At my kitchen table","In my portfolio document"],obstacle:"I cannot find a perfect opening sentence",fallback:["Use a rough first sentence","Ask for one specific example"],observation:["The recording I saved","The draft and its remaining gap"],stopRule:"Skip distressing scenes; choose ordinary task notes if future writing feels unhelpful.",scenario:"Elena’s script describes a confident interview. Her interview is tomorrow, and she has no example ready for a common customer-service question.",question:"Which revision makes the page useful tonight?",options:[{key:"draft",text:"Add a real customer example, rehearse one answer, and save a rough recording for tomorrow’s check.",feedback:"This connects the scene to tomorrow’s task. A rough answer can reveal what needs work. It does not secure the job, but it produces preparation she can inspect and improve."},{key:"feelings",text:"Describe the feeling of confidence in more detail before deciding which customer example fits.",feedback:"Exploring feelings can make the scene meaningful. Here the missing element is an answer using real experience. More feeling detail leaves that gap intact; choose an example and rehearse it."},{key:"edit",text:"Polish the entire journal entry so the imagined interview follows a clear and consistent narrative.",feedback:"A coherent story is a writing goal. Elena’s immediate goal is preparing an answer. Editing the narrative uses her limited evening without producing the example she needs for the interview."}],best:"draft",takeaway:"Write a future worth pursuing, then give today one piece of its work.",review:"Which scripted step became an actual attempt, and what remains unfinished?",deeper:[{heading:"How people script",paragraphs:["1. Pick a desired situation, such as a working day in a role you want. 2. Write a journal entry as if that day is already happening. 3. Describe ordinary details: where you are, what you do, and how the scene feels. 4. Read it back and return to it if you want. Some versions add gratitude or a feeling of certainty. These are practitioner instructions, not a validated route to an offer. [manifest-P02]","Keep imagined events labeled as imagined. You can write an ordinary scene without inventing a promise that another person has made. For the ODA exercise, add the necessary work, available resources, and an obstacle you face now. Pick a single task from that page. A typed or spoken entry is an accessibility choice; we do not claim every format has identical research effects. The ritual is optional. [manifest-P02]"]},{heading:"Future writing and real-experience writing differ",paragraphs:["Best possible self research asks people to imagine a good future after working toward it. Carrillo and colleagues found average benefits for wellbeing, optimism, and positive affect, with study-quality limitations. This supports a bounded expectation about reflective writing. It does not establish that present-tense scripting causes the written events to occur. Expressive disclosure has a different target: real experiences or feelings. Its small average benefit does not validate future-event attraction either. [manifest-T08, manifest-T12]","ODA keeps the narrative and adds a practical exit from it. Choose a specific goal already in your course experiment. Name what might block today’s step, then write a response you can afford and perform. Save an opportunity and minimum, attempt it, and review tomorrow. Record an interview rehearsal as preparation, an application as a submission, and a reply only when one arrives. This workflow is a design adaptation, not either writing intervention as originally tested."]}],sources:["manifest-P02","manifest-T08","manifest-T12"]},{number:8,technique:"Vision board",title:"Vision board: give one picture a next step",goal:"Turn one board image into a cue for an achievable action.",hook:"That vision-board desk looks good. What will you do at your own desk today?",reason:"Which image reflects your own priority rather than someone else’s idea of success?",paragraphs:["A vision board gathers images and words representing a desired life. Choose pictures, arrange them, put the board somewhere visible, and revisit it. Mixed: current goals can shape attention, alongside salience and past experience. That does not establish board efficacy or show that pictures attract opportunities. The reticular activating system concerns arousal; calling it a programmable wish filter overstates the evidence.","ODA version: keep an image you care about. Label its specific goal and one action today. Name an obstacle and an if-then response; make seeing the image a start cue. Tomorrow check whether the cue led to your minimum. Noticing an opening and creating it are different claims."],example:{title:"Nora labels the desk",text:"Nora’s board includes a desk in a design studio. She labels it “Build one portfolio sample.” When she sees the picture after breakfast, she opens her unfinished project and writes a caption. The image is less exciting than the studio dream. She saves it anyway and notes that the project still needs feedback."},instructions:["Choose one image; label its specific goal and today’s useful action.","Use seeing it as a cue; plan a response to one likely obstacle.","Attempt the action and check tomorrow whether you noticed the cue."],action:["Write one portfolio caption","Send one project feedback request"],minimum:["Save a usable project caption","Send a focused feedback question"],cue:["When I see the board after breakfast","When I open my project folder"],place:["At my work desk","In my portfolio document"],obstacle:"The picture cues browsing instead of work",fallback:["Open the project before browsing","Use a text reminder beside the file"],observation:["Whether the image cued an actual start","The caption or request I completed"],stopRule:"Use existing pictures or words; skip images that pressure you into spending.",scenario:"Nora sees her board each morning but then browses studio photos. Her portfolio lacks the caption needed to explain one completed project.",question:"What is the most useful change?",options:[{key:"fresh",text:"Replace the studio image with a more inspiring one so the board feels relevant again.",feedback:"A new image may be enjoyable, but the record shows browsing after the cue. It does not show a missing aspiration. Change what seeing the picture asks her to do."},{key:"study",text:"Spend the next morning comparing studio portfolios to understand the standard she hopes to reach.",feedback:"Comparison can inform later work. Nora already has a completed project needing a caption. More browsing would repeat the current pattern unless it answers a specific question needed for that caption."},{key:"label",text:"Label the image “Open project, write caption,” then save one caption before browsing any studio photos.",feedback:"This connects the existing cue to the missing action. Tomorrow Nora can check whether she noticed the label and saved the caption. The board itself does not guarantee a studio job."}],best:"label",takeaway:"Give the picture a task and a cue. Review the task, not the image’s power.",review:"Did seeing your image lead to the saved action, or to something else?",deeper:[{heading:"Build the familiar board without buying anything",paragraphs:["1. Choose a desired direction or situation. 2. Gather a few pictures and words that represent it. 3. Arrange them on paper, an existing board, or a digital page. 4. Place the collection where you intend to revisit it. 5. Look at it and imagine the desired situation. These steps describe the practitioner exercise; they are not evidence that a board brings the situation into existence. [manifest-P03]","For this course, keep one direction instead of adding every possible life improvement. An existing photo, sketch, or written word is enough. Under one image, name the actual task: ask a training question, finish a sample, or submit a suitable application. Choose a place where you can act when the image appears. The materials and layout are your preference, with no scientific requirement to purchase special supplies. Separate arranging pictures from completing the task."]},{heading:"What noticing can and cannot explain",paragraphs:["Attention research describes selection influenced by current goals, physical salience, and selection history. This makes deliberate looking for relevant openings plausible; it does not validate every method proposed to improve noticing. The reticular activating system participates in wakefulness and arousal circuits. Those findings do not establish a board-controlled filter that delivers a job, partner, or house. A newly noticed opening may have existed before you paid attention to it. [manifest-T15, manifest-T19]","ODA turns the image into an explicit reminder rather than assigning it a hidden mechanism. Write the goal, today’s action, and a response to the obstacle most likely to interrupt it. If seeing the board starts another browsing session, plan to open the work file first. Tomorrow check whether the cue occurred, whether you noticed it, and what you actually did. Keep outside responses separate. This image-and-plan bundle has not been tested as a vision-board intervention."]}],sources:["manifest-P03","manifest-T15","manifest-T19"]},{number:9,technique:"Affirmations",title:"Affirmations: choose a line you can use",goal:"Pair an encouraging line with one observable goal action.",hook:"“I am wildly successful” feels false today. Try a sentence that gives you something to do.",reason:"Does this sentence help you attempt the task, or pressure you to feel certain?",paragraphs:["Affirmations are encouraging statements people say or write repeatedly, often phrased as an already-achieved outcome. Choose a line, repeat it, and imagine believing it. Mixed: Wood and colleagues found that one strongly positive statement worsened mood for some low-self-esteem participants. Research self-affirmation often means reflecting on important values, not repeating success slogans; health-behavior findings cannot establish job attraction.","ODA version: keep an encouraging line that feels usable. Name a value and an action expressing it: “I prepare one honest example.” Choose a specific goal, obstacle, and if-then response. Attempt the action today; tomorrow review what you did. Replace or skip a line that makes you feel worse."],example:{title:"Leah changes the sentence",text:"Leah repeats “I am an outstanding speaker” before a meeting and feels more embarrassed. She switches to “I prepare one clear point.” At her desk, she writes a suggestion and practices saying it. During the meeting she uses the first sentence, then loses her place. Her record names the contribution and the unfinished explanation."},instructions:["Choose an encouraging line tied to a value and a specific action.","Name one obstacle; add a feasible if-then response without demanding belief.","Attempt your action today; review the act and how the line felt tomorrow."],action:["Use one prepared meeting sentence","Ask one clear project question"],minimum:["Say the first suggestion sentence","Send one specific project question"],cue:["When the meeting invites suggestions","When I open the project thread"],place:["In our meeting room","In the project message thread"],obstacle:"My encouraging line feels false",fallback:["Use the prepared sentence without an affirmation","Switch to a plain action reminder"],observation:["What I said and the response","Whether the line helped or felt worse"],stopRule:"Replace or skip statements that feel distressing; no forced certainty is required.",scenario:"Leah’s repeated success statement makes her feel worse. She still wants to offer one useful suggestion at a meeting and has a rough sentence ready.",question:"Which adjustment fits both facts?",options:[{key:"persist",text:"Keep the success statement for several more sessions before changing it, while continuing to rehearse the suggestion.",feedback:"Rehearsal may help preparation, but there is no requirement to persist with a statement that worsens her mood. The available suggestion gives her another way to begin without forcing belief."},{key:"action",text:"Use a plain action reminder or skip the affirmation, then offer the prepared sentence when suggestions open.",feedback:"This preserves a feasible contribution while responding to the reported discomfort. Leah can review what she said and how the reminder felt. She does not need certainty about being an outstanding speaker."},{key:"wait",text:"Prepare a stronger statement of personal strengths, and postpone the suggestion until she feels more convinced.",feedback:"Reflecting on values differs from convincing herself of a grand statement. Waiting for conviction makes confidence a condition for an already prepared action. Keep the contribution small and the statement optional."}],best:"action",takeaway:"Use the sentence as an optional cue. Let the action supply evidence.",review:"What did you attempt, and did the sentence help, hinder, or make no difference?",deeper:[{heading:"The popular statement practice",paragraphs:["1. Choose an outcome or personal quality. 2. Phrase it positively, often in the present tense. 3. Say or write it repeatedly. 4. Imagine the desired situation while using the line. 5. Return to the statement at a chosen time. Frequency and wording vary across practitioner versions; the familiar recipe does not establish a scientifically required count or feeling. [manifest-P04]","You may enjoy the practice without making its strongest promise. For ODA, use a sentence that points to work you can actually attempt. “I prepare one clear point” can sit beside your meeting notes. You can also use no sentence at all. An uncomfortable or unbelievable statement is not a test you must pass. Wood and colleagues studied a particular positive statement and short-term mood effects; their result does not show that every kind phrase is harmful. [manifest-T06]"]},{heading:"A value is different from a success slogan",paragraphs:["In self-affirmation research, people often reflect on important values, qualities, or relationships before encountering potentially threatening information. Epton and colleagues pooled health-message experiments and found small average effects on acceptance and intentions, with a behavioral benefit in that setting. Those procedures differ from repeating a desired outcome as already true. They do not establish that a job offer follows from saying “I got the job.” [manifest-T07]","ODA borrows the distinction without claiming the whole ritual is tested. Pick a value, such as honesty, and one way to express it in your existing goal: prepare an accurate example of your work. Save the opportunity and minimum. Write a response to a likely obstacle, such as losing your place, and attempt the sentence today. Tomorrow record the actual contribution and whether the line felt usable. Skip the affirmation if it adds pressure; keep the feasible action. [manifest-T06, manifest-T07]"]}],sources:["manifest-P04","manifest-T06","manifest-T07"]},{number:10,technique:"Visualization",title:"Visualization: rehearse the move inside the scene",goal:"Choose a task, rehearse a difficulty, and make an actual attempt.",hook:"Picture getting the offer. Then practice answering the question that comes before it.",reason:"Will another scene expose a useful gap, or delay an action already ready?",paragraphs:["Visualization means imagining a desired event, often with sensory details and its feeling of success. Settle, picture the scene, participate mentally, and repeat if wanted. Mixed for manifestation: mental simulation supported later behavior on average, but this does not establish event attraction. An early exam study favored process imagery in some comparisons; the later meta-analysis found no reliable subtype winner.","ODA version: keep a brief outcome scene, then rehearse your actual task and one obstacle. Choose a specific goal and an if-then response, attempt one action today, and review tomorrow. Rehearsal remains preparation. Use written steps if imagery does not come; no vivid picture or special feeling is required."],example:{title:"Ben rehearses the difficult question",text:"Ben pictures finishing an interview, then rehearses explaining a gap in his work history. He plans to start with the dates if he freezes. After lunch, he records an answer and notices he has left out what he learned. He adds one sentence. The answer still needs practice, and no interview result exists yet."},instructions:["Keep a brief outcome scene; rehearse the next task and one likely difficulty.","Write a specific goal and an if-then response to that difficulty.","Make the actual attempt today and review it separately from rehearsal tomorrow."],action:["Record an interview practice answer","Send one prepared meeting suggestion"],minimum:["Save one rough answer recording","Send one suggestion sentence"],cue:["After lunch ends","When the meeting invites input"],place:["At my interview practice desk","In the team message thread"],obstacle:"I freeze at the first sentence",fallback:["Start with the dates in my notes","Read the short prepared opening"],observation:["The answer I actually recorded","Preparation and actual contribution, recorded separately"],stopRule:"Stop imagery that increases distress; use ordinary task notes and a daytime opportunity.",scenario:"Ben pictured a successful interview twice. His saved practice answer still avoids explaining the work-history gap. He has five minutes before leaving.",question:"What use of imagery fits the gap?",options:[{key:"rehearse",text:"Rehearse the first gap-explanation sentence, record a rough answer, and check whether it includes the necessary dates.",feedback:"This makes preparation address the observed gap and produces a recording to inspect. Imagery does not secure the interview result. Its useful role here is helping Ben attempt the answer."},{key:"outcome",text:"Repeat the successful-interview scene with richer details, then record how confident it makes him feel.",feedback:"Confidence is a possible observation, but it does not answer the missing question. Ben’s record identifies a specific explanation to practice. Use the remaining time to rehearse and record that explanation."},{key:"research",text:"Use the time to compare several visualization methods before choosing which one to practice tonight.",feedback:"Method comparison may be interesting, but no evidence here requires one subtype before beginning. Ben already knows the missing task. A short attempt supplies more relevant information than another method search."}],best:"rehearse",takeaway:"Let the scene reveal a task. Rehearsal prepares; an attempt tests.",review:"What did you actually attempt after rehearsal, and what gap became visible?",deeper:[{heading:"The familiar outcome scene",paragraphs:["1. Choose an event you would like to happen. 2. Settle somewhere comfortable. 3. Picture a short scene showing the desired result. 4. Imagine participating, with details you find meaningful. 5. Return to the scene if you want. Some practitioner versions ask for strong emotion or a feeling of already having the result. These instructions document a ritual; they do not establish that its scene attracts an external event. [manifest-P05]","For ODA, keep the outcome scene short enough to leave time for work. Identify the next task that belongs between now and that scene. Mentally rehearse a difficulty in that task, then write the response you will try. A person who does not form vivid pictures can describe the steps instead. That is an accessibility option, not proof that every preparation format has the same effect. No imagined employer reply should be logged as a real one."]},{heading:"Why there is no universal imagery winner",paragraphs:["The early Pham and Taylor exam study compared studying-process imagery, desired-grade imagery, combinations, and a control. Some comparisons favored process imagery; the grade finding does not justify a reliable process-versus-control benefit. Cole and colleagues later pooled varied mental simulations and found an average behavior benefit, without establishing differences between subtypes. Several subgroups were small. It would overstate this evidence to promise that one scene always works best. [manifest-T17, manifest-T04]","ODA asks what preparation your own task needs. If you know the goal but avoid its first sentence, rehearse starting and handling that obstacle. Save a feasible minimum, cue, place, and response. Try the action today, then review tomorrow. Record both a useful rehearsal and any actual task separately. If preparation continues without an attempt, shorten it or choose another available opening. This particular scene-to-attempt sequence is an ODA adaptation, not a protocol validated by the meta-analysis."]}],sources:["manifest-P05","manifest-T04","manifest-T17"]},{number:11,technique:"55x5 method",title:"55x5: keep time for the actual task",goal:"Pair optional writing with one feasible action and a review.",hook:"Fifty-five lines written, application still blank? Put the next useful sentence where you can act on it.",reason:"How much writing time can you spare without losing the useful task?",paragraphs:["The 55x5 method writes one present-tense affirmation 55 times a day for five days. Pick a desired outcome, repeat the same sentence, and complete the daily count. Not supported: that count or five-day run attracting an outcome. Some idealized-fantasy experiments reduced immediate energy; that does not show all imagination or this writing ritual harms effort.","ODA version: keep writing if you enjoy it, with repetitions optional. Choose a specific goal and one achievable action each day. Name the obstacle, then attach an if-then response to a recognizable cue. Act today before adding more writing; tomorrow review the task. Research supports specific planning, not the special repetition schedule."],example:{title:"Sam protects the application time",text:"Sam likes copying “I prepare useful applications,” but finishing 55 lines uses his entire break. He keeps a few lines and reserves five minutes after lunch for the application. If he lacks a detail, he writes a question for recruitment. Today he sends the question. He records that request, not an application or offer."},instructions:["Choose one goal; reserve time for action before deciding how much to repeat.","Add a recognizable cue and an if-then response to one obstacle.","Attempt today’s task and review it tomorrow; repetitions remain optional."],action:["Send a missing-detail question","Complete one application section"],minimum:["Send one recruitment question","Save one complete section"],cue:["After lunch ends","After my optional writing session"],place:["In the recruitment email draft","At my application desk"],obstacle:"Repetitions use all my available time",fallback:["Skip repetitions and do the minimum","Reserve action time before opening the notebook"],observation:["Actual task and writing time separately","What I sent or saved"],stopRule:"Reduce or skip writing that causes strain or crowds out your available action time.",scenario:"Sam completed two days of 55 repetitions. Neither day left time for his application. He has the same short break available today.",question:"What change tests a more useful routine?",options:[{key:"faster",text:"Write the repetitions faster so he can preserve the full ritual and possibly start the application afterward.",feedback:"Writing faster may still leave the application without an opening. His record identifies the time conflict. Reserve a feasible task slot first, then choose how much optional writing fits around it."},{key:"weekend",text:"Finish all five writing days, then give the application a longer session at the weekend.",feedback:"A weekend session might be possible, but it postpones the task to protect an unsupported count. There is already a small opportunity today. Test that opening before adding more repetition."},{key:"reserve",text:"Reserve five minutes for one application section, shorten or skip repetitions, and review the saved section tomorrow.",feedback:"This changes the condition that blocked the task. It preserves writing as a preference while making the application attempt feasible. A saved section remains preparation for submission, not an offer."}],best:"reserve",takeaway:"Protect the action opening. A completed count is not a completed goal task.",review:"What task did you attempt, and how much time did the writing leave for it?",deeper:[{heading:"The familiar five-day repetition recipe",paragraphs:["1. Choose one desired outcome. 2. Write a positive sentence as though it has already happened. 3. Copy the sentence 55 times in a daily session. 4. Repeat that session for five days. 5. Return attention to the desired result while writing. The recipe’s exact count is a practitioner requirement, not a dose established by controlled research. Versions may add instructions about emotion or uninterrupted focus. [manifest-P06]","Keep the recognizable writing format if it is enjoyable, but make its cost visible. Before starting, decide what time today’s actual goal action needs. A shorter writing session or no repetitions is allowed in the ODA version. Missing a day does not mean a future result has been canceled. A finished page belongs in the record as writing; a saved application section belongs as task work. Neither entry says an employer has made an offer."]},{heading:"Repetition is not the planning ingredient",paragraphs:["Gollwitzer and Sheeran’s meta-analysis supports linking a specific situation to a goal-directed response across varied tasks. It does not test 55 repetitions or a five-day manifestation rule. Kappes and Oettingen found that some idealized positive fantasies reduced immediate energy. Their short experiments are a caution about pleasant imagined completion replacing preparation, not proof that every optimistic thought or repeated sentence is harmful. [manifest-T02, manifest-T05]","ODA uses the page to hold a practical plan. Name your goal, the task’s smallest useful unit, and the opening in which you can do it. If writing tends to fill the whole break, plan to do the action first. If a missing detail blocks a section, send the specific question. Attempt today, then review tomorrow: did the cue arrive, what task was done, and what remains? The writing-plus-action schedule is an adaptation, without a promised five-day outcome."]}],sources:["manifest-P06","manifest-T02","manifest-T05"]},{number:12,technique:"Two-cup method",title:"Two cups: name the bridge between them",goal:"Use the labels to choose a feasible action and obstacle response.",hook:"Pouring water is the easy part. What bridges your current situation and the label you want?",reason:"What would make the desired label feasible with your time and resources?",paragraphs:["The two-cup method labels one cup with a current situation and another with a desired one. Fill the first, imagine the change, pour into the second, and drink the water. Not supported: water carrying intention or shifting dimensions. Goal-setting evidence concerns specific goals, strategies, and feedback, not a quantum explanation for pouring.","ODA version: keep the cups as symbols, or use two drawn circles. Between the labels, write a specific goal, a real obstacle, and an if-then plan. WOOP names wish, outcome, obstacle, and plan; research supports that planning combination on average. Attempt one bridge action today. Tomorrow review what you did, separately from any outside result."],example:{title:"Omar writes the bridge",text:"Omar labels cups “Portfolio unfinished” and “Ready to apply.” Between them he puts a note: “Save one project caption after lunch.” If he cannot explain the project, he will describe its main decision. He pours the water, then writes the caption. The portfolio still needs another project; the note records exactly what changed."},instructions:["Label the current situation and a desired goal; keep the change feasible.","Between them, write today’s bridge action and an obstacle-response if-then plan.","Attempt the bridge action; review the actual work tomorrow."],action:["Write one project caption","Ask about one training requirement"],minimum:["Save a caption describing one decision","Send one training question"],cue:["After lunch ends","When I put away the cups"],place:["In my portfolio document","At my kitchen table"],obstacle:"The desired label requires more resources",fallback:["Ask about access or a smaller route","Describe one project decision in plain words"],observation:["The bridge action I actually completed","What remains between the two labels"],stopRule:"Use drawings if preferred; drink only safe water if you choose the drinking step.",scenario:"Omar’s desired cup says “Ready to apply.” His portfolio has one finished project without a caption, and a second project still incomplete.",question:"What bridge action fits a five-minute opening?",options:[{key:"caption",text:"Write and save the finished project’s caption, then record what still prevents the portfolio from being ready.",feedback:"This chooses a feasible unit and preserves the remaining gap. A caption does not make the whole portfolio ready, but it gives the next review a real piece of progress to examine."},{key:"rename",text:"Change the desired label to “Hired designer” to keep the overall ambition visible during the ritual.",feedback:"The larger ambition can matter, but changing the label does not address the unfinished portfolio. Keep the aspiration and choose the small task that the available five minutes can support."},{key:"schedule",text:"Map every remaining portfolio task before touching the caption, so the whole route is fully planned.",feedback:"A task map may help a later review. In this short opening, the missing caption is already known. Completing it tests a feasible bridge instead of spending the whole opportunity preparing more."}],best:"caption",takeaway:"Let the labels name the gap. Let an affordable action bridge part of it.",review:"What changed through your action, and what still stands between your two labels?",deeper:[{heading:"The recognizable two-cup ritual",paragraphs:["1. Take two cups and label the first with the situation you have now. 2. Label the second with the situation you want. 3. Put water in the first cup. 4. Imagine the desired change as you pour into the second. 5. Drink the water and return attention to the desired situation. Some practitioner descriptions call this dimension jumping. That metaphysical explanation is not established by the inspected evidence. [manifest-P07]","You can keep the symbolic transfer without taking its explanation as fact. Existing cups or two drawn circles are enough for ODA’s exercise. Write an action between the labels before pouring. Avoid labeling an uncertain decision by someone else as already secured. A usable portfolio caption is your action; being hired is an outcome involving an employer. If you drink, use only water that is safe to drink. No special vessel or purchase is needed."]},{heading:"Use the gap for WOOP and feasibility",paragraphs:["WOOP organizes a wish, its desired outcome, a current obstacle, and a plan. The mental-contrasting-with-implementation-intentions meta-analysis found a modest average benefit for goal attainment, with variation and publication-bias indications. It did not test cups or water. Goal-setting theory also makes commitment, feedback, ability, and task complexity relevant. A meaningful label needs a workable route; a hard goal without access or a strategy is not enough. [manifest-T01, manifest-T11]","ODA makes the bridge explicit. Choose one specific task for your existing goal. Name an obstacle you can respond to, and check external barriers such as missing equipment or money. “If I cannot access the tool, I will ask about an available alternative” can make a support request the action. Save the minimum and cue, attempt today, then review tomorrow. Record requests separately from help received. The symbolic cups plus this practical workflow are an adaptation, not a tested combined treatment."]}],sources:["manifest-P07","manifest-T01","manifest-T11"]},{number:15,technique:"Gratitude journaling",title:"Gratitude: keep appreciation honest",goal:"Record something you actually appreciate and attempt one useful action without denying a difficulty.",hook:"You can appreciate a friend’s help and still admit the application was rejected.",reason:"What deserves appreciation without making you hide what needs to change?",paragraphs:["Gratitude journaling records things you appreciate, often with reasons and a reread. Some manifestation versions thank life for a future event as if it happened. Mixed: gratitude interventions show small average wellbeing benefits against some controls, with little advantage over psychologically active alternatives. Symptom findings are modest; gratitude is not sufficient treatment or evidence of future-event attraction.","ODA version: keep the journal and describe something real. Name your specific goal and a difficulty alongside the appreciation. Add an if-then response and one action today, such as thanking a helper or requesting focused feedback. Tomorrow review the action and any response. A grateful entry does not require hiding disappointment."],example:{title:"Aisha keeps both facts",text:"Aisha writes that she appreciates a friend checking her application. She also records the rejection email. After breakfast, she asks the friend which opening sentence needs work. Her plan allows a short message if a call is unavailable. The friend cannot reply today. Aisha logs the question and the disappointment without inventing feedback."},instructions:["Write one real appreciation and its reason; keep any difficulty visible.","Name today’s useful action and an if-then response to one likely obstacle.","Attempt the action; review it and any response tomorrow."],action:["Send a focused feedback request","Thank someone for specific help"],minimum:["Send one application feedback question","Send one specific thank-you message"],cue:["After breakfast ends","When I finish the gratitude entry"],place:["In my message thread","At my kitchen table"],obstacle:"My helper is unavailable for a call",fallback:["Send one concise feedback question","Choose another available reviewer"],observation:["Request sent and any actual reply","Appreciation and difficulty, recorded honestly"],stopRule:"Skip forced gratitude; persistent distress deserves support beyond a journal.",scenario:"Aisha appreciates a friend’s support but is upset by an application rejection. Her friend has offered to answer one focused question by message.",question:"What entry and action fit the situation?",options:[{key:"positive",text:"List only the supportive moments today and postpone examining the rejection until she feels more grateful.",feedback:"Appreciation can remain part of the entry, but it does not require postponing a concrete problem. The offered feedback opening lets Aisha ask one useful question while acknowledging that rejection hurts."},{key:"both",text:"Record the support and disappointment, then ask which opening sentence would make the next application clearer.",feedback:"This keeps gratitude grounded in an actual event and uses the available support. The message is a request, not feedback received. Tomorrow Aisha can record any reply and choose a revision."},{key:"future",text:"Write thanks for the next offer as if it happened, then reread the entry before requesting feedback.",feedback:"That future-focused version is a practitioner ritual, not the gratitude intervention tested in the cited reviews. It cannot establish an offer. A real appreciation and focused question keep the entry connected to facts."}],best:"both",takeaway:"Appreciate what is real. Keep the difficulty and the next useful action visible.",review:"What did you appreciate, what action did you attempt, and did anyone respond?",deeper:[{heading:"The familiar gratitude journal",paragraphs:["1. Open a notebook or your usual writing tool. 2. Name something you appreciate. 3. Describe why it matters to you. 4. Add another item if you want. 5. Reread the entry at a chosen time. A first-hand practitioner account describes this reasons-and-rereading format. Manifestation variants may add thanks for a wished-for future event; that is a different claim from appreciating help already received. [manifest-P10]","For ODA, an ordinary detail is enough: a useful answer, a shared tool, or a moment of rest. You do not need a positive item for every problem. If a rejection, access barrier, or disappointment matters today, record it alongside the appreciation. Choose one useful action that fits your existing goal. The entry is reflection; thanking someone or sending a request is a separate act. Neither writing nor a request guarantees a response."]},{heading:"Small average benefits, with comparison limits",paragraphs:["Davis and colleagues found small average wellbeing benefits for gratitude interventions against some controls. Gratitude did not outperform psychologically active alternatives for wellbeing, and anxiety findings were inconclusive. Cregg and Cheavens found modest average pooled depression-and-anxiety symptom changes, with larger effects against waitlist than active controls; their separate anxiety analysis was inconclusive. Those findings do not establish one optimal journal dose, guaranteed relief, or gratitude as sufficient treatment. They also do not test future events arriving because someone thanked the universe. [manifest-T09, manifest-T10]","ODA adds a practical plan without calling it the tested intervention. Keep your goal specific, name the current obstacle, and choose an if-then response. If a helpful person cannot call, send one focused question instead. Attempt today and review tomorrow. Note the request separately from any answer, and let disappointment remain part of the record. You can skip gratitude if it feels forced and still make the useful move or seek support."]}],sources:["manifest-P10","manifest-T09","manifest-T10"]},{number:16,technique:"Act as if / embodiment",title:"Act as if: practice without spending ahead",goal:"Give a desired identity one affordable behavior.",hook:"You want to feel like a professional. Start with a work sample before buying the wardrobe.",reason:"Which behavior expresses your goal without spending money you need elsewhere?",paragraphs:["Act as if, also called embodiment, behaves like the person who already has a desired outcome. Choose that identity, imagine its routines, then adopt some behavior or symbol. Mixed: specific goals and feedback can support performance; pretending the outcome is secured has no established attraction mechanism. Manifestation-belief surveys found associations with some financial risks, not proof that belief caused them.","ODA version: keep the identity rehearsal and choose an affordable behavior under your control. Name the specific goal, obstacle, and if-then response. A professional might prepare a useful sample or ask a clear question. Do one action today and review it tomorrow. Buying symbols is optional; another person’s agreement remains theirs."],example:{title:"Rafi practices the role",text:"Rafi wants to work as a freelance analyst. He considers buying an expensive office chair, then chooses to improve a sample spreadsheet instead. After lunch, he checks one calculation and adds an explanation. If software access fails, he will use a free available tool. The sample is clearer; he still has no client."},instructions:["Name the desired identity and one specific, affordable behavior it could express.","Add an obstacle-response if-then plan; keep other people’s decisions outside your promise.","Attempt that behavior today; review what you did and spent tomorrow."],action:["Improve one work sample","Ask one focused client question"],minimum:["Save one explained sample calculation","Send one project clarification question"],cue:["After lunch ends","When I open the sample file"],place:["At my work desk","In my sample spreadsheet"],obstacle:"I lack access to the planned tool",fallback:["Use an available free tool","Write the explanation in a text file"],observation:["Work produced and money actually spent","The change I saved in the sample"],stopRule:"Keep spending within your means; do not treat uncertain income or consent as secured.",scenario:"Rafi wants freelance work and has no confirmed client. Buying a premium tool would use money reserved for essentials; an available free tool supports his sample.",question:"Which act best expresses the role today?",options:[{key:"sample",text:"Improve one sample with the available tool, record the change, and keep essential spending protected.",feedback:"This gives the identity an affordable behavior and an inspectable result. It does not secure a client, but it strengthens something Rafi can share. Essential money need not fund an uncertain symbol."},{key:"purchase",text:"Buy the premium tool now so his work environment matches the professional identity he wants to inhabit.",feedback:"A tool can be useful when a task requires it and the cost fits. Here a free tool covers the task, while the purchase threatens essentials. Identity rehearsal does not establish future income."},{key:"wait",text:"Wait for a confirmed client before making a sample, so he avoids investing effort in an uncertain outcome.",feedback:"Protecting money is sensible, but a small sample can be made with available resources. Waiting for certainty also blocks this affordable test. Set a feasible effort limit and inspect what the sample needs."}],best:"sample",takeaway:"Practice the behavior you can afford. Keep identity, spending, and outside outcomes separate.",review:"What behavior did you attempt, what did it cost, and what result is actually known?",deeper:[{heading:"The familiar identity rehearsal",paragraphs:["1. Choose the situation or identity you want. 2. Imagine how that person spends an ordinary day. 3. Pick behaviors, objects, or routines associated with that life. 4. Act as if the desired change has already occurred. 5. Notice how the rehearsal feels and return to it if wanted. A practitioner account describes preparing clothes and luggage as though a job were confirmed. Its later offer is an anecdote, not a controlled comparison. [manifest-P11]","ODA keeps the role rehearsal but asks for a behavior with a safe cost. Preparing a work sample, arriving with an agenda, or asking a clear question can fit an existing goal. Expensive possessions are not a condition for practicing the role. Do not act as though another person has consented or an unconfirmed employer has hired you. A possible future is a direction, not a resource already in hand."]},{heading:"Goals need feedback and real resources",paragraphs:["Goal-setting theory describes how specific, challenging goals can support performance when commitment, feedback, ability, and task complexity are considered. It does not establish that adopting an identity independently produces the desired outcome. Dixon and colleagues found that manifestation beliefs correlated with some self-reported financial risks and bankruptcy, without establishing causation. Confidence or perceived success is not the same as income already received. [manifest-T11, manifest-T13]","ODA chooses one behavior before a symbol. Name the concrete result of today’s task and the available time or tools. Plan a response to a likely obstacle, such as missing software access, and keep the minimum affordable. Attempt it today and review tomorrow. Record the work produced, any cost, and any outside response separately. If a purchase or promise assumes success has already arrived, reconsider the route. This identity-to-action package is an adaptation; the cited studies did not test it as an embodiment intervention."]}],sources:["manifest-P11","manifest-T11","manifest-T13"]},{number:17,technique:"Letter from your future self",title:"Future-self letter: include the difficult Tuesday",goal:"Give your future-self letter one feasible action for this week.",hook:"Your future self has a calmer life. How did they handle a difficult Tuesday?",reason:"Which future matters to you enough to make one affordable move this week?",paragraphs:["A future-self letter imagines a later you writing to the person you are now. Choose a future date, describe the life and changes, offer encouragement, then reread. Mixed: related best-possible-self research supports average wellbeing and optimism benefits, not communication from the future or guaranteed goal attainment. That research includes working toward the imagined life.","ODA version: keep the letter’s voice, but include effort, help, and a difficult ordinary day. Name your specific goal, current obstacle, and an if-then response. Choose one action today and save a feasible opportunity. Specific planning has research support; this letter-plus-plan package is an adaptation. Tomorrow review your attempt, not whether the future prediction came true."],example:{title:"Jess writes the ordinary day",text:"Jess’s future letter describes a steadier work week, then explains asking for priorities when tasks clash. Today, after opening her work inbox, she sends one clarification question. If her manager is unavailable, she will use the team thread. The answer does not arrive immediately. Her record shows a request and a still-unresolved workload."},instructions:["Write from your future self; include effort, help, and an ordinary obstacle.","Choose today’s action and a specific cue; add a feasible if-then response.","Attempt the minimum and review the actual record tomorrow."],action:["Send one work-priority question","Reserve a feasible practice opening"],minimum:["Send one clarification request","Confirm one available practice slot"],cue:["When I open my work inbox","After dinner is cleared"],place:["In the team message thread","At my kitchen table"],obstacle:"The person I need is unavailable",fallback:["Use the agreed team message route","Choose another available practice opening"],observation:["Request sent and any actual answer","The opening I actually confirmed"],stopRule:"Use a nearer or less demanding future if the letter adds pressure; pausing is allowed.",scenario:"Jess’s future letter promises a balanced work week. Today two urgent tasks clash, and her manager invited clarification questions in the team thread.",question:"Which addition earns its place in the letter?",options:[{key:"calendar",text:"Describe a complete ideal-week calendar before asking which of today’s urgent tasks should come first.",feedback:"A calendar can guide later choices, but it cannot decide this priority conflict by itself. Jess has an available clarification route. Use that opening and keep the unanswered question visible."},{key:"certainty",text:"Add stronger encouragement about trusting the future, then wait until the workload feels less overwhelming.",feedback:"Encouragement may be welcome, but waiting for a different feeling leaves both urgent tasks competing. A short clarification request is already feasible. The letter should help her take that step without predicting the reply."},{key:"request",text:"Describe asking for priorities on difficult days, then send one clarification question through the agreed team thread.",feedback:"This gives the future scene a behavior that fits the current obstacle. Sending is her action; an answer remains unknown until it arrives. Tomorrow she can review the request and choose the next step."}],best:"request",takeaway:"Let the future voice name today’s work and the support it may need.",review:"Which letter step became an attempt, and what help or result remains unknown?",deeper:[{heading:"The familiar letter format",paragraphs:["1. Pick a future point in your life. 2. Imagine being yourself at that point. 3. Address a letter to your present self. 4. Describe what changed and how ordinary life feels. 5. Offer encouragement or advice, then reread the letter. A practitioner resource documents this future-to-present voice and its compassionate framing. Dates and greetings are format choices, not scientifically necessary ingredients. [manifest-P12]","For ODA, write about a future you want without claiming it is a message or prediction. Include an ordinary difficulty, the effort involved, and help you might need. A calmer work week may require a priority conversation rather than stronger certainty. Keep the direction linked to your course experiment. Underline one feasible action for the person who will wake up tomorrow with the same real resources. A near-future letter is allowed if a distant one feels burdensome."]},{heading:"Hopeful writing needs a way back to today",paragraphs:["The best possible self meta-analysis found average benefits for wellbeing, optimism, and positive affect compared with controls. Samples were often young students, and no study met every quality criterion. The imagined future follows working toward it; the findings do not establish that letters predict or deliver external events. Implementation-intention research separately supports a specific cue linked to an achievable response. Neither source tested this exact future-letter package. [manifest-T08, manifest-T02]","ODA uses the letter to choose a move. Name a specific goal, identify the obstacle closest to today’s task, and write “If that happens, I will…” with a feasible response. Save the cue, place, and minimum, then attempt it today or at the chosen later opening. Tomorrow review what actually occurred: a request, a task, a delay, or a pause. If another person has not replied, leave the answer unknown. Revise the next step without pretending the imagined future is already evidence."]}],sources:["manifest-P12","manifest-T08","manifest-T02"]}],s=[...S,...q].sort((e,t)=>e.number-t.number).map(A),W=[...h,...l,{id:"M01",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"24 independent effects from 21 articles, 15,907 participants: modest average goal-attainment benefit, g = .336 [.229, .443]. Bias adjustment estimated .242 [.143, .342].",limitation:"Substantial variation and publication-bias indications. This course and its brief exercises were not tested; outcomes are not guaranteed."},{id:"M02",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 independent tests, 8,461 participants: specific if-then planning supported goal attainment on average, d = .65 [.60, .70].",limitation:"Older heterogeneous evidence, not uniformly preregistered. Plans do not eliminate effort, memory, practical constraints, or uncertainty."},{id:"M03",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 experiments, 19,951 participants overall. Goal-attainment analysis used 18,398 participants: d = .40 [.32, .48]; a small-study sensitivity adjustment estimated .19 [.10, .28].",limitation:"Goals and interventions varied. Moderator associations do not require public reporting. No validation of this exact log, review schedule, or ODA course."},{id:"M04",title:"Cole et al. · 2021 · Mental simulation and behavior change",url:"https://link.springer.com/article/10.3758/s13423-021-01880-6",type:"research",finding:"94 studies, 123 effects, 5,685 participants: overall mental-simulation effect g = .49 [.37, .62]. The omnibus subtype comparison was nonsignificant.",limitation:"Mostly student samples and varied simulations. Process-only imagery had five effects with an inconclusive estimate. No reliable subtype ranking or validation of this brief exercise."},{id:"M07",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Belief in manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Three US online survey samples, 1,023 participants: manifestation belief correlated with some financial-risk reports and reported bankruptcy, but not reported income or education.",limitation:"Associations do not establish causation or objectively test every manifestation technique. Self-reported financial outcomes are not an individual forecast."},{id:"M10",title:"Gollwitzer & Brandstätter · 1997 · Specific opportunity planning",url:"https://sparq.stanford.edu/sites/g/files/sbiybj19021/files/media/file/gollwitzer_brandstatter_1997_-_implementation_intentions_effective_goal_pursuit.pdf",type:"research",finding:"Study 2 assigned 86 students a report. Among 36 identifiable returners, 12/17 planners versus 6/19 controls wrote within two days.",limitation:"The 71% versus 32% comparison concerns returners, not everyone recruited. Planning did not increase overall cooperation. Narrow student task; no ODA-course validation."},{id:"M11",title:"Oettingen et al. · 2015 · Planning and calendar scheduling",url:"https://doi.org/10.1002/ejsp.2090",type:"research",finding:"Study 1 analyzed 84 undergraduates. The planned contrast favored mental contrasting plus if-then plans for scheduled hours, p = .03; omnibus p = .057.",limitation:"Scheduling was measured, not completed work or productivity. Incomplete respondents were excluded; the brief course adaptation and external-feasibility taxonomy were not tested."},{id:"M14",title:"NIMH · Help for mental illnesses",url:"https://www.nimh.nih.gov/health/find-help",type:"guidance",finding:"Official guidance provides qualified-care and crisis routes for distress, impairment, or immediate danger.",limitation:"Guidance, not an efficacy study. ODA does not diagnose or treat mental illness; outside the US use local care and emergency services."},{id:"manifest-positive-fantasies",title:"Kappes & Oettingen · 2011 · Idealized positive fantasies",url:"https://bpb-us-e1.wpmucdn.com/wp.nyu.edu/dist/c/6235/files/2019/02/kappes-et-al-2011-positive-fantasies-about-idealized-futures-sap-energu.pdf",type:"research",finding:"Four primarily student experiments found lower immediate energy after some idealized positive fantasies. Study 3 compared positive with neutral or undirected fantasies, not questioning fantasies.",limitation:"Small short experiments. Not all optimism or imagination is harmful; a recurring fantasy loop and a brain signal of completed goals were not measured."},{id:"manifest-belief-study",title:"Dixon, Hornsey & Hartley · 2025, online 2023 · Belief in manifestation",url:"https://journals.sagepub.com/doi/full/10.1177/01461672231181162",type:"research",finding:"Three US online surveys totaling 1,023 participants linked manifestation belief with confidence and some financial-risk reports, including reported bankruptcy. No association with reported income or education.",limitation:"Associations do not establish causation or objectively test every technique. Self-reported outcomes are not an individual forecast."},{id:"manifest-murphy",title:"Joseph Murphy · The Power of Your Subconscious Mind · Publisher provenance",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"The publisher identifies Murphy's popular self-help book and its imagination and belief teachings.",limitation:"Publisher synopsis, not a controlled study. Exact bedtime ritual passages were not verified. No evidence here for wealth attraction, healing, or uniquely effective bedtime learning."}],i=[{schemaVersion:2,revision:2,id:"manifest-1",courseId:"manifest",locale:"en",title:"Dream still waiting? Make one useful thing",goal:"Produce one usable piece of work for a goal you choose.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Another week of wanting a different life? Give one wish a piece of work.",reason:{id:"manifest-1-reason",label:"Whose goal is this, and what deserves your time?",kind:"text",maxLength:160,optional:!0,suggestions:["My goal; evening scrolling can wait","Family priority; extra polishing can wait","Someone else’s goal; reconsider the time","I am unsure whose goal this is"]},why:{id:"manifest-1-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A better job is an outcome. Improving one résumé line is a behavior. Other people still decide whether to call. Choose work worth doing without making their reply the test of your effort.","In one student experiment, selecting a starting time and place improved timeliness among people who returned a report. It did not increase overall cooperation. A plan can support starting; it cannot guarantee results. Choose one usable line, answer, or request today. Keep this goal through the course, and bring back what actually happened."],example:{title:"Daniel makes a start",text:"At the kitchen table after dinner, Daniel gives his logistics-job goal ten minutes. He rewrites one résumé line to describe scheduling eight warehouse shifts. The wording still feels clumsy. He saves it anyway and records the change. No employer has seen it yet. Tomorrow he can improve a real draft."}},move:{invitation:"Name your own useful act; suggestions show Daniel’s résumé example.",instructions:["Name the document, question, or object you will change before saving.","Do the minimum; record it separately from any outside reply."],prompts:[],suggestions:{action:["Rewrite a résumé line about scheduling shifts","Ask a reviewer which résumé detail is missing","Build a work sample showing shift coverage"],minimum:["Save one résumé sentence about scheduling shifts","Send the résumé-detail question","Save a work sample showing shift coverage"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After dinner is cleared","When lunch ends","After my morning drink"],place:["At my kitchen table","At the library desk","In the résumé document"],minutes:[10,2,5],fallback:["Write one shift change in plain words","Choose and name another available opening","Ask library staff about computer access"],observation:["The résumé sentence I actually saved","Whether I sent the résumé question","What prevented the minimum"]},suggested:{action:"Rewrite a résumé line about scheduling shifts",minimum:"Save one résumé sentence about scheduling shifts",minutes:10,cueHint:"After dinner is cleared",placeHint:"At my kitchen table",obstacleHint:"My available time is shorter than planned",fallbackHint:"Write one shift change in plain words",observationHint:"The résumé sentence I actually saved"},accessibleAlternative:"Type, dictate, or use your usual tools; ask for practical assistance if needed.",stopRule:"Pause unsafe or unaffordable steps; choose practical support instead."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-1-decision",scenario:"Daniel has a suitable vacancy and ten minutes before dinner. His résumé does not describe the scheduling work it requires.",question:"What is the strongest first test?",options:[{id:"manifest-1-research-more",text:"Compare more vacancies to check whether this role really matches the kind of life he wants.",feedback:"Comparing roles can clarify a goal. This vacancy already fits, and the missing piece is a usable description of Daniel's experience. Improve that line in the available time."},{id:"manifest-1-improve-line",text:"Rewrite one résumé line for this vacancy, save the draft, and note what still needs work.",feedback:"This produces something Daniel can use while staying within ten minutes. The draft may need feedback and the employer may not respond. Neither fact erases the actual work."},{id:"manifest-1-clarify-future",text:"Write a detailed description of his ideal working day before deciding what to put on the résumé.",feedback:"A desired working day may guide later choices. Daniel already chose a suitable role. More description postpones this concrete gap. Write the résumé line, then review what it needs."}],bestOptionId:"manifest-1-improve-line"}},carry:{takeaway:"Give the wish a useful act. Record the act separately from the answer you hope for.",followUp:{questionId:"manifest-1-return",question:"What usable work exists after your saved attempt?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"What a starting plan can support",paragraphs:["Gollwitzer and Brandstätter's 1997 Study 2 assigned 86 Munich students a report about Christmas. Planners chose an exact time and place, pictured that opportunity, committed to starting, and recorded those choices. Among the 36 identifiable report returners, 12 of 17 planners and six of 19 controls wrote within the requested two days. Those percentages describe returners, not everyone recruited. Planning did not increase overall cooperation. [M10]","The lesson borrows the concrete opportunity, then asks for usable work at that opportunity. That general-purpose adaptation was not tested in the Christmas-report study. A date alone does not tell you where the time will come from. Use an event you can recognize and a place you can access. If the resources are missing, asking for them can be the actual move. Record that request as a request, even when help has not arrived."]},{heading:"A wish does not control other people",paragraphs:["Wang and colleagues' 2021 review pooled 24 independent effects from 21 articles, with 15,907 participants. Pairing a desired outcome with an obstacle and an if-then response showed a modest average goal-attainment benefit: g = .336, with a 95% confidence interval from .229 to .443. Findings varied substantially, and a publication-bias adjustment reduced the estimate. This supports bounded planning, not a promise for this course. [M01]","Dixon and colleagues studied manifestation beliefs in three US online surveys totaling 1,023 participants. Belief correlated with some financial-risk reports and reported bankruptcy, but not reported income or education. These associations do not show that belief caused bankruptcy or objectively test every manifestation exercise. [M07] Use your wish to choose work and assess constraints. Do not infer that thoughts attracted an opportunity, caused hardship, or made you deserve an outcome. Money, care, access, and other people's decisions still matter."]}],sourceIds:["M10","M01","M07"]}},{schemaVersion:2,revision:2,id:"manifest-2",courseId:"manifest",locale:"en",title:"Rehearsing again? Give the scene an ending",goal:"Rehearse one sticking point, then produce the next usable part of your existing goal task.",minutes:{learning:6,suggestedAction:5,review:2,rehearsal:1},direction:{hook:"The finished life is easy to picture. What happens when you meet the blank page?",reason:{id:"manifest-2-reason",label:"Will another rehearsal help, or replace the actual attempt?",kind:"text",maxLength:160,optional:!0,suggestions:["It exposes a missing instruction","It delays a ready sentence","I have no rehearsal record yet"]},why:{id:"manifest-2-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Retrieve your chosen task and any record. Rehearsing means mentally doing a particular move, such as saying the first sentence. Listing steps is a different kind of preparation. Neither is the real attempt.","A review found average behavior benefits from mental simulation, but did not establish a best subtype. It does not prove that this brief rehearsal works. Use it only to identify your sticking point and a response. Describe the move in words if pictures do not come. Then make the next usable line in the same task."],example:{title:"Daniel meets the blank line",text:"Daniel returns to his résumé after dinner. For thirty seconds he rehearses describing a difficult scheduling change. He expects to freeze, so he practices starting with “Changed eight shifts when…” Then he types a usable sentence. He deletes two words and leaves a question for feedback. The rehearsal missed how much detail he needed."},rehearsal:{label:"Optional preparation",steps:["Describe the next move and one likely sticking point.","Rehearse your first response once. This is preparation."]}},move:{invitation:"Keep your named task; the résumé suggestions are editable examples.",instructions:["Keep the saved action, minimum, cue, and place; target its sticking point.","Without a plan, name your act and available opening before saving.","Rehearse once, then act; rehearsal alone is preparation."],prompts:[],suggestions:{action:["Rehearse, then write one résumé scheduling sentence","Rehearse, then ask about a résumé detail","Use written steps to revise a résumé date"],minimum:["Save one résumé sentence after rehearsal","Send the résumé-detail question","Save one corrected résumé date"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After dinner is cleared","When lunch ends","When the résumé document opens"],place:["At my kitchen table","At the library desk","In the résumé document"],minutes:[5,2,10],fallback:["Stop rehearsing; write one actual shift change","Skip imagery; use the written first step","Ask the reviewer which detail is missing"],observation:["What rehearsal missed in the real act","The résumé sentence I actually produced","Whether I only rehearsed"]},suggested:{action:"Rehearse, then write one résumé scheduling sentence",minimum:"Save one résumé sentence after rehearsal",minutes:5,cueHint:"After dinner is cleared",placeHint:"At my kitchen table",obstacleHint:"I keep refining the rehearsal instead of beginning",fallbackHint:"Stop rehearsing; write one actual shift change",observationHint:"What rehearsal missed in the real act"},accessibleAlternative:"Type, dictate, or use your usual tools; ask for practical assistance if needed.",stopRule:"If planning in bed keeps you awake, stop and use a daytime opportunity."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-2-decision",scenario:"Daniel can describe his first résumé sentence and has the document ready. He is tempted to rehearse the whole application again.",question:"Which next move serves this attempt?",options:[{id:"manifest-2-full-rehearsal",text:"Rehearse the entire application once more so he can choose the strongest opening before writing anything.",feedback:"A full rehearsal may prepare later work. Daniel already has a usable opening and a ready document. Another complete run delays the available test. Type the sentence and inspect it."},{id:"manifest-2-new-goal-scene",text:"Picture his first day in the new role to renew motivation before returning to the application later.",feedback:"Imagining the role may clarify why it matters. It does not test Daniel's prepared opening. Use the sentence in the document now, then learn from what was harder than expected."},{id:"manifest-2-perform-opening",text:"Rehearse the first sentence once, type it into the draft, and compare the actual difficulty with expectations.",feedback:"This uses preparation to support an actual move. The typed sentence gives Daniel something to review. Its quality and his discomfort remain open questions, rather than conditions for counting the attempt."}],bestOptionId:"manifest-2-perform-opening"}},carry:{takeaway:"End useful preparation with a real move. Keep their records separate.",followUp:{questionId:"manifest-2-return",question:"What differed between rehearsing your move and actually doing it?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"What simulation evidence does and does not rank",paragraphs:["Cole and colleagues' 2021 review combined 94 studies, 123 effects, and 5,685 participants. Mental simulation showed an overall behavior effect of g = .49, with a 95% confidence interval from .37 to .62. Most samples were students. Simulations differed in content, dose, and outcome, so the average is not a forecast for your short exercise. [M04]","The review distinguished thinking through process steps from mentally performing a task. Its process-only estimate used five effects and had a confidence interval spanning no effect. The overall subtype comparison was not statistically significant. Higher subgroup averages therefore do not establish a reliable winner. Do not turn a chart into instructions to visualize harder. This lesson uses rehearsal to expose one practical detail, then asks you to attempt the task. Written description is an accessibility choice, not a claim of research-tested equivalence to imagery."]},{heading:"Prepare for an opportunity, then use it",paragraphs:["In the original report-planning experiment, participants pictured a specific time and place for beginning a task. The reported timeliness comparison concerned identifiable returners and a narrow student assignment. It does not establish a universal imagination script or a benefit from rehearsing in bed. [M10] Here, preparation earns its place when it helps you perform the next piece of your existing goal task.","You might notice a missing password, an unclear instruction, or a sentence you cannot yet explain. Resetting a password is preparation; submitting the needed information is task work. Make the distinction visible in your record. Stop bedtime planning if it keeps you awake, and choose a daytime opportunity instead. This is a practical course adaptation. Brief rehearsal is an optional app exercise, not a validated ritual or a condition for beginning. No vivid picture or particular feeling is required."]}],sourceIds:["M04","M10"]}},{schemaVersion:2,revision:2,id:"manifest-3",courseId:"manifest",locale:"en",title:"The obstacle is real. Change the conditions",goal:"Use your last attempt to choose and test one feasible obstacle response.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Childcare, missing access, or exhaustion in the way? Believing harder will not rearrange the day.",reason:{id:"manifest-3-reason",label:"What needs support, and what can you change now?",kind:"text",maxLength:160,optional:!0,suggestions:["Shared laptop access needs agreement","I can reduce the résumé edit","Care duties leave no opening today","I have not encountered a barrier yet"]},why:{id:"manifest-3-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Use your same goal and any attempt record. No attempt yet? Name a likely barrier. “No shared computer after dinner” guides a response; “I lack discipline” does not identify the condition.","Studies pairing a desired outcome, a real obstacle, and an if-then response found modest average benefits. They did not establish discomfort as the reason it works. Money, care, time, and access are conditions, not belief defects. Test one change: a smaller task, an available opening, or a specific support request. A request counts as asking, not receiving help."],example:{title:"Daniel changes the opening",text:"Daniel planned another résumé edit after dinner, but his daughter needed the shared laptop for homework. His record names the clash. He asks whether he can use it for ten minutes before dinner the next day. They agree. At that opening he improves one line, then stops. The application still needs work."}},move:{invitation:"Need access? Choose Adapt this, then Support. Name your contact; suggestions show Daniel’s laptop request.",instructions:["Retain your named act, minimum, cue, and place when access is already agreed.","Without access, name the person, resource, and opening in a support request.","Record asking separately from receiving help or completing the task."],prompts:[],suggestions:{action:["Ask daughter for laptop time before dinner","Ask library staff about available computer time"],minimum:["Ask daughter for ten-minute laptop access","Send the library computer-access question"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["When household homework plans are discussed","After lunch today","After dinner is cleared"],place:["At my kitchen table","In the library’s contact form","At the library desk"],minutes:[5,2,10],fallback:["Ask library staff about computer access","Send household member the laptop-time request","Pause until a feasible opening is agreed"],observation:["The access request and any reply","Whether laptop time was actually agreed","Whether I did the named résumé edit"]},suggested:{action:"Ask daughter for laptop time before dinner",minimum:"Ask daughter for ten-minute laptop access",minutes:5,cueHint:"When household homework plans are discussed",placeHint:"At my kitchen table",obstacleHint:"My daughter cannot offer laptop time",fallbackHint:"Ask library staff about computer access",observationHint:"The access request and any reply",kind:"support"},accessibleAlternative:"Type, speak, or use assistance. Choose Adapt for task work after access is agreed.",stopRule:"If the exercise overwhelms you or the setting is unsafe, pause and seek appropriate support."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-3-decision",scenario:"Daniel's evening edits clash with shared-laptop homework. A ten-minute opening before dinner is available if they agree on it.",question:"Which response fits this obstacle?",options:[{id:"manifest-3-arrange-opening",text:"Agree on the available ten-minute opening and use it to improve one line in the same draft.",feedback:"This changes the condition that blocked the task and preserves a useful minimum. Agreement is still needed. Record the request separately if the opening cannot yet be confirmed."},{id:"manifest-3-keep-evening",text:"Keep the evening appointment and add a longer rehearsal so he feels ready when the laptop becomes available.",feedback:"Rehearsal may prepare wording, but it leaves the access clash unchanged. Daniel has a possible alternative opening. Agree on that opening before adding another preparation routine."},{id:"manifest-3-wait-week",text:"Wait until homework demands settle down next week, then restart with the larger résumé session he originally wanted.",feedback:"Waiting can be appropriate when no feasible opening exists. Here, a smaller opening may be arranged now. Test that option instead of postponing all task work automatically."}],bestOptionId:"manifest-3-arrange-opening"}},carry:{takeaway:"Name the blocking condition. Change the task or ask for the support it actually needs.",followUp:{questionId:"manifest-3-return",question:"Did you make the access request or task move, and what agreement is still pending?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"An obstacle is information, not an ingredient",paragraphs:["The 2021 mental-contrasting-with-planning review found a modest average improvement in goal attainment across 24 independent effects. Substantial variation and publication-bias indications limit certainty. It did not isolate feeling uncomfortable as an active ingredient. Naming a difficulty may be unpleasant, but deliberately intensifying distress is not the task. [M01]","Oettingen and colleagues' inspected 2015 procedure asked students to elaborate a desired outcome and a main obstacle, select a response, form an obstacle-to-action plan, and add its usual time and place. In Study 1, the planned comparison favored the method for scheduled calendar hours. The outcome was scheduling, not completed work, and the overall condition test was inconclusive. [M11] ODA adds a practical feasibility check and an actual attempt. Neither this shorter exercise nor its distinction between external conditions and personal responses was separately validated by that experiment."]},{heading:"When the right response is support",paragraphs:["Keep your desired outcome separate from the conditions needed to pursue it. A missing tool calls for access; an unsafe situation calls for protection; a care conflict may call for a different opening. This is a course design choice informed by the planning evidence, not a taxonomy that assigns every obstacle to one box. A support request is concrete when it names the help and opportunity you need. [M01, M11]","If someone has not answered, record the request and the absence of a reply. Do not record help received or task work completed. You can choose another feasible step, revise the goal, or pause. For persistent distress or significant impairment, seek qualified support rather than making the exercise more intense. The NIMH help guidance provides care and crisis routes, not evidence that ODA treats a condition. [M14] Your next record should describe the act you chose, including protection or support, without recasting the original obstacle as a failure of belief."]}],sourceIds:["M01","M11","M14"]}},{schemaVersion:2,revision:2,id:"manifest-4",courseId:"manifest",locale:"en",title:"Stop waiting for the right mood",goal:"Use a recognizable start cue and a small response to your experiment's observed sticking point.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"“When I feel ready” keeps moving. Choose a moment you can actually notice.",reason:{id:"manifest-4-reason",label:"When the cue last arrived, what did postponing the move cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Compared examples; missed writing","Waited for readiness; left the draft untouched","Care needed me; no safe opening","No prior cue; wording may delay me"],help:"No prior attempt? Name a possible hesitation."},why:{id:"manifest-4-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A start cue and an obstacle response have different jobs. “After the plates are cleared, write one résumé line” creates an opening. “If I get stuck, describe one shift change” helps inside that opening.","Research across varied goals found that specific if-then plans supported follow-through on average. They do not remove all memory, effort, or practical barriers. Keep your task; respond to a recorded obstacle if one exists. Pick one noticeable cue and one response you can carry out there. If the cue never occurs, record no occasion and choose another opening."],example:{title:"Daniel uses the cue",text:"Daniel places a note beside the shared laptop: “After the plates are cleared, improve one line. If stuck, describe one shift change.” On Thursday the cue arrives and he notices the note. He writes one useful line, but cannot finish the section before family duties resume. His record keeps both facts."}},move:{invitation:"Keep your actual task and opening. Suggestions show Daniel’s résumé example.",instructions:["Keep the saved act, minimum, cue, and place unless one needs changing.","Name the smaller response to your actual sticking point before saving."],prompts:[],suggestions:{action:["After dinner, write one résumé scheduling sentence","After lunch, send the résumé-detail question","After tea, correct one résumé date"],minimum:["Save one résumé sentence about scheduling shifts","Send the résumé-detail question","Save one corrected résumé date"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["After the plates are cleared","When lunch ends","When I put down my tea"],place:["At my kitchen table","In the résumé document","At the library desk"],minutes:[5,2,10],fallback:["Describe one shift change in one sentence","Choose and name another available opening","Ask library staff about computer access"],observation:["Whether the cue occurred and was noticed","Whether I described the shift change","The résumé change I actually saved"]},suggested:{action:"After dinner, write one résumé scheduling sentence",minimum:"Save one résumé sentence about scheduling shifts",minutes:5,cueHint:"After the plates are cleared",placeHint:"At my kitchen table",obstacleHint:"I reach the cue but get stuck on wording",fallbackHint:"Describe one shift change in one sentence",observationHint:"Whether the cue occurred and was noticed"},accessibleAlternative:"Type, dictate, or use your usual tools; ask for practical assistance if needed.",stopRule:"Keep care and safety obligations; use another opening if this cue becomes unsuitable."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-4-decision",scenario:"Daniel has five minutes after clearing dinner. His draft and one accurate shift-change example are ready, but he stalls over the wording.",question:"Which plan fits both starting and getting stuck?",options:[{id:"manifest-4-mood-cue",text:"When he feels clearer after dinner, spend five minutes improving the résumé section with his strongest examples.",feedback:"A clearer mood would be welcome, but it is a moving start cue. Use the observable dinner event and a response small enough for the available five minutes."},{id:"manifest-4-full-section",text:"After clearing the plates, compare three scheduling examples before choosing the strongest one for the résumé line.",feedback:"Comparison can improve selection. Daniel already has an accurate example, and searching would consume his five-minute opening. Describe that shift change first; review the wording after a real line exists."},{id:"manifest-4-cue-and-response",text:"After clearing the plates, improve one line; if wording stalls, describe one actual shift change plainly.",feedback:"This gives the opening and the sticking point distinct responses. Daniel can attempt it with his ready draft. The plan supports a move without promising effortless memory or a finished section."}],bestOptionId:"manifest-4-cue-and-response"}},carry:{takeaway:"Give starting an opening and getting stuck a response. Then test whether either actually happened.",followUp:{questionId:"manifest-4-return",question:"Did you notice the start cue, and could you use your planned response?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"What specific planning supports",paragraphs:["Gollwitzer and Sheeran's 2006 chapter pooled 94 independent tests with 8,461 participants. If-then planning showed an average goal-attainment effect of d = .65, with a 95% confidence interval from .60 to .70. Tasks and procedures varied, and this older evidence was not uniformly preregistered. It does not establish that any sentence a learner writes will work. [M02]","The opportunity-planning experiment asked students to select a specific time and place to begin a report. Its timeliness comparison concerned identifiable returners, not everyone assigned to the task. [M10] The practical lesson is narrower than “a plan replaces willpower.” Decide a response in advance, then check whether the situation occurred, you noticed it, and the response fit. Keep external reminders if you need them. A note beside a tool is an ODA option, not a tested guarantee of noticing."]},{heading:"Two jobs, one continuing experiment",paragraphs:["Your starting appointment answers when you will attempt the task. Your coping response answers what you will do if an observed obstacle appears. The inspected mental-contrasting procedure linked an obstacle to a response and added its usual time and place; it did not establish that everyone needs two separate rules. [M11] This course separates their jobs to make your existing experiment easier to diagnose.","Suppose the planned opening never arrives. There is no basis for saying the coping response failed. If the opening arrives but you miss it, change the cue or reminder. If you notice it but the response is too large, shrink the next useful task unit. These are choices to test, not findings proven by one private log. Keep old records tied to their original minimum. A different next plan should not turn an incomplete past attempt into completed work. Review your actual move, and retain the option to seek support, rest, pause, or change the goal."]}],sourceIds:["M02","M10","M11"]}},{schemaVersion:2,revision:2,id:"manifest-5",courseId:"manifest",locale:"en",title:"No result yet? Read your actual record",goal:"Use your experiment's records to choose a feasible next step and next week's review.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Before you abandon the dream, check whether you tested the route or only kept planning it.",reason:{id:"manifest-5-reason",label:"What would make you keep, change, or stop this route?",kind:"text",maxLength:160,optional:!0,suggestions:["Usable draft; submit it","Repeated clashes; change the opening","Specific feedback; revise the unclear sentence","No attempt yet; choose a first test"]},why:{id:"manifest-5-purpose",label:"What would this move make possible in your week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Read the records for the same goal. Separate what you planned, rehearsed, actually did, and received from others. A saved draft proves draft work. It does not prove an application was sent or an employer is interested.","A review of 138 experiments found average benefits from increasing progress monitoring. It did not validate this exact record or an ideal review schedule. Choose from your facts: repeat a workable step, change one problem, seek feedback, or stop an unsuitable goal. If no attempt exists, name that gap and make your first useful unit."],example:{title:"Daniel chooses next week",text:"Daniel reads three dated edits and one missed laptop opening. His résumé is clearer, but he has not sent an application. He chooses one suitable vacancy, checks its requirements, and submits the prepared version on Friday. He records the submission and schedules a review next week. There is no reply yet."}},move:{invitation:"Keep what fit; name the next act. Suggestions show a ready application.",instructions:["Keep the saved minimum and appointment when repeating; change only the observed bottleneck.","Without a record, name a first act and matching minimum before saving.","An information request counts as asking, not completion of the blocked task."],prompts:[],suggestions:{action:["Submit the prepared application to the selected vacancy","Ask hiring contact about an unclear requirement","Revise one résumé sentence using reviewer feedback"],minimum:["Send the prepared application once","Send the question about the application requirement","Save the revised résumé sentence"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1},{label:"In two days",daysFromToday:2}],cue:["When lunch ends","After dinner is cleared","When the vacancy application page opens"],place:["At my kitchen table","At the library desk","In the vacancy’s application form"],minutes:[10,2,5],fallback:["Ask hiring contact about the unclear requirement","Request reviewer feedback on the unclear sentence","Pause until required information is available"],observation:["The submission and its confirmation, if available","The information request and any pending reply","What remains outside my control"]},suggested:{action:"Submit the prepared application to the selected vacancy",minimum:"Send the prepared application once",minutes:10,cueHint:"When lunch ends",placeHint:"At my kitchen table",obstacleHint:"A required application detail is unclear",fallbackHint:"Ask hiring contact about the unclear requirement",observationHint:"The submission and its confirmation, if available"},accessibleAlternative:"Type, dictate, or use your usual tools; ask for practical assistance if needed.",stopRule:"Do not increase spending or sacrifice needed care to rescue an uncertain outcome."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do or produce?"},judgment:{primary:{id:"manifest-5-decision",scenario:"Daniel edited his résumé but has not applied. A suitable vacancy closes tonight. His draft meets its requirements; a reviewer can compare versions tomorrow.",question:"What should his review lead to?",options:[{id:"manifest-5-next-application",text:"Submit the prepared application, record the submission, and choose a later review while the reply remains unknown.",feedback:"The record reveals a concrete next step that is ready and under Daniel's control. Submission is the act. An employer's decision stays unknown until there is actual feedback."},{id:"manifest-5-double-editing",text:"Ask a reviewer to compare two résumé versions before submitting the application, to reduce the chance of weak wording.",feedback:"Comparison could reveal quality problems, but it arrives after tonight’s deadline. Daniel has checked the requirements with no known gap remaining. Submit this suitable version; use later feedback for an actual change."},{id:"manifest-5-change-direction",text:"Use the opening to send several less targeted applications, increasing coverage before deciding which résumé version to keep.",feedback:"Broader coverage can create opportunities. Here one suitable application is already ready. Sending it tests that match; volume can be a later choice without replacing this prepared, targeted submission."}],bestOptionId:"manifest-5-next-application"}},carry:{takeaway:"Let records change the next move. Effort, preparation, and outside results tell different stories.",followUp:{questionId:"manifest-5-return",question:"What happened with your chosen task or information request, and what is still pending?",observationPrompt:"What happened at the saved opportunity?",adjustmentPrompt:"What one change fits your next opportunity?"}},goDeeper:{sections:[{heading:"Monitoring informs a decision",paragraphs:["Harkin and colleagues' 2016 review included 138 experiments with random allocation and 19,951 participants overall. The goal-attainment analysis used 18,398 participants and found d = .40, with a 95% confidence interval from .32 to .48. A small-study sensitivity adjustment gave a lower estimate. Interventions, goals, and recording methods differed. The review did not test ODA's receipt or next-day card. [M03]","Larger effects were associated with recorded or publicly reported progress across studies. Those moderator comparisons do not establish that public disclosure is necessary or that one app format causes a benefit. Keep personal details private if that fits your situation. Use records to compare what the plan asked for with the act you actually reported. An absent record remains unknown. A completed preparation step, unanswered request, or stopped attempt should retain its own label. This makes your next decision reviewable without demanding a positive story."]},{heading:"Choose next week without rewriting this one",paragraphs:["A short personal log can suggest a pattern, but it cannot prove why an outside outcome occurred. Applications, orders, and another person's response may depend on quality, timing, resources, or circumstances your record does not measure. Monitoring research supports using information; it does not establish a universal number of attempts before changing a goal. [M03] Your review should keep that uncertainty visible.","Select one feasible next opportunity and a review point for the coming week. Retain your usable minimum and what helped access the task; change the part your records actually question. If no attempt is recorded, either report known facts or treat the next small act as your first experiment. Do not invent a history of effort. Planning studies show average benefits with variation, not guaranteed outcomes. [M01] Pausing, requesting feedback, finding practical support, or choosing another direction can be a deliberate result of the review. Keep the earlier record so the reason for that choice remains visible."]}],sourceIds:["M03","M01"]}},...s],M={id:"manifest",title:"Dreams going nowhere? Give one wish real work",subtitle:"Five foundation lessons, then 15 popular techniques with honest evidence and a useful action.",description:"Turn one chosen wish into useful work. Keep your experiment through the technique library: learn the rituals, check the research, and try an achievable move.",scope:"Here, manifesting means the practice of intention, preparation and action. The course does not claim that thoughts steer events through quantum effects, that the universe delivers what you focus on, or that any wish is sure to come true. It is not financial, medical or psychological advice.",outcome:"One meaningful goal with a usable minimum, honest attempt records, and a feasible next-week plan.",lessonLibrary:{id:"manifest-technique-library",title:"Technique library",description:"15 familiar rituals. How people do them, what research supports, and an ODA version with action and review.",lessonIds:s.map(e=>e.id),sourceIds:[...h,...l].map(e=>e.id)},photo:{id:"1676782778930-11b311ec5134",alt:"Dirt road climbing a grassy hill toward distant mountains"},lessons:[{id:"manifest-1",v2:i[0],photo:{id:"1768055104910-8c8d213835fb",alt:"Hand writing a to-do list in a notebook"},schemaVersion:2,title:"Dream still waiting? Make one useful thing",minutes:6,goal:"Produce one usable piece of work for a goal you choose.",reading:["A better job is an outcome. Improving one résumé line is a behavior. Other people still decide whether to call. Choose work worth doing without making their reply the test of your effort.","In one student experiment, selecting a starting time and place improved timeliness among people who returned a report. It did not increase overall cooperation. A plan can support starting; it cannot guarantee results. Choose one usable line, answer, or request today. Keep this goal through the course, and bring back what actually happened."],practice:["Write or think of one wish that matters to you, in a single sentence.","Choose one behavior within your control that moves you toward that wish.","Describe the behavior with a small finish line, for example “three lines of a draft”."],reflection:"What is today’s behavior version of your wish?",question:"Which of these is a behavior you can choose directly?",options:["The employer definitely choosing me.","Editing three lines of my résumé tomorrow.","Nothing going wrong at all."],correct:1,feedback:"You cannot guarantee other people’s decisions. You can make your own preparation concrete.",takeaway:"Give the wish a useful act. Record the act separately from the answer you hope for.",sources:["M10","M01","M07"],deeper:[{heading:"What a starting plan can support",paragraphs:["Gollwitzer and Brandstätter's 1997 Study 2 assigned 86 Munich students a report about Christmas. Planners chose an exact time and place, pictured that opportunity, committed to starting, and recorded those choices. Among the 36 identifiable report returners, 12 of 17 planners and six of 19 controls wrote within the requested two days. Those percentages describe returners, not everyone recruited. Planning did not increase overall cooperation. [M10]","The lesson borrows the concrete opportunity, then asks for usable work at that opportunity. That general-purpose adaptation was not tested in the Christmas-report study. A date alone does not tell you where the time will come from. Use an event you can recognize and a place you can access. If the resources are missing, asking for them can be the actual move. Record that request as a request, even when help has not arrived."]},{heading:"A wish does not control other people",paragraphs:["Wang and colleagues' 2021 review pooled 24 independent effects from 21 articles, with 15,907 participants. Pairing a desired outcome with an obstacle and an if-then response showed a modest average goal-attainment benefit: g = .336, with a 95% confidence interval from .229 to .443. Findings varied substantially, and a publication-bias adjustment reduced the estimate. This supports bounded planning, not a promise for this course. [M01]","Dixon and colleagues studied manifestation beliefs in three US online surveys totaling 1,023 participants. Belief correlated with some financial-risk reports and reported bankruptcy, but not reported income or education. These associations do not show that belief caused bankruptcy or objectively test every manifestation exercise. [M07] Use your wish to choose work and assess constraints. Do not infer that thoughts attracted an opportunity, caused hardship, or made you deserve an outcome. Money, care, access, and other people's decisions still matter."]}],example:{title:"Daniel makes a start",text:"At the kitchen table after dinner, Daniel gives his logistics-job goal ten minutes. He rewrites one résumé line to describe scheduling eight warehouse shifts. The wording still feels clumsy. He saves it anyway and records the change. No employer has seen it yet. Tomorrow he can improve a real draft."}},{id:"manifest-2",v2:i[1],photo:{id:"1517363898874-737b62a7db91",alt:"Person sitting quietly by a window in warm light"},schemaVersion:2,title:"Rehearsing again? Give the scene an ending",minutes:6,goal:"Rehearse one sticking point, then produce the next usable part of your existing goal task.",reading:["Retrieve your chosen task and any record. Rehearsing means mentally doing a particular move, such as saying the first sentence. Listing steps is a different kind of preparation. Neither is the real attempt.","A review found average behavior benefits from mental simulation, but did not establish a best subtype. It does not prove that this brief rehearsal works. Use it only to identify your sticking point and a response. Describe the move in words if pictures do not come. Then make the next usable line in the same task."],practice:["Name one difference you want your goal to make in your life.","Put your first two moves in order, as images or as words.","After the rehearsal, actually do one preparation step."],reflection:"Which missing preparation did you notice during the rehearsal?",question:"What does mental rehearsal mean in this course?",options:["An exercise that prepares you for real action.","Controlling outside events for certain with your thoughts.","No longer needing to try at all."],correct:0,feedback:"Rehearsal is preparation. The cited studies do not validate this exact brief exercise or show that it controls external outcomes. Use preparation to support a real move.",takeaway:"End useful preparation with a real move. Keep their records separate.",sources:["M04","M10"],deeper:[{heading:"What simulation evidence does and does not rank",paragraphs:["Cole and colleagues' 2021 review combined 94 studies, 123 effects, and 5,685 participants. Mental simulation showed an overall behavior effect of g = .49, with a 95% confidence interval from .37 to .62. Most samples were students. Simulations differed in content, dose, and outcome, so the average is not a forecast for your short exercise. [M04]","The review distinguished thinking through process steps from mentally performing a task. Its process-only estimate used five effects and had a confidence interval spanning no effect. The overall subtype comparison was not statistically significant. Higher subgroup averages therefore do not establish a reliable winner. Do not turn a chart into instructions to visualize harder. This lesson uses rehearsal to expose one practical detail, then asks you to attempt the task. Written description is an accessibility choice, not a claim of research-tested equivalence to imagery."]},{heading:"Prepare for an opportunity, then use it",paragraphs:["In the original report-planning experiment, participants pictured a specific time and place for beginning a task. The reported timeliness comparison concerned identifiable returners and a narrow student assignment. It does not establish a universal imagination script or a benefit from rehearsing in bed. [M10] Here, preparation earns its place when it helps you perform the next piece of your existing goal task.","You might notice a missing password, an unclear instruction, or a sentence you cannot yet explain. Resetting a password is preparation; submitting the needed information is task work. Make the distinction visible in your record. Stop bedtime planning if it keeps you awake, and choose a daytime opportunity instead. This is a practical course adaptation. Brief rehearsal is an optional app exercise, not a validated ritual or a condition for beginning. No vivid picture or particular feeling is required."]}],example:{title:"Daniel meets the blank line",text:"Daniel returns to his résumé after dinner. For thirty seconds he rehearses describing a difficult scheduling change. He expects to freeze, so he practices starting with “Changed eight shifts when…” Then he types a usable sentence. He deletes two words and leaves a question for feedback. The rehearsal missed how much detail he needed."}},{id:"manifest-3",v2:i[2],photo:{id:"1767134063671-322e6faf9206",alt:"Fallen tree lying across a leafy forest path"},schemaVersion:2,title:"The obstacle is real. Change the conditions",minutes:6,goal:"Use your last attempt to choose and test one feasible obstacle response.",reading:["Use your same goal and any attempt record. No attempt yet? Name a likely barrier. “No shared computer after dinner” guides a response; “I lack discipline” does not identify the condition.","Studies pairing a desired outcome, a real obstacle, and an if-then response found modest average benefits. They did not establish discomfort as the reason it works. Money, care, time, and access are conditions, not belief defects. Test one change: a smaller task, an available opening, or a specific support request. A request counts as asking, not receiving help."],practice:["Name the nearest obstacle standing in front of your goal.","Separate the part of the obstacle you can influence from the part that needs support or time.","If it cannot be done right now, make the goal smaller or move it to a suitable time."],reflection:"Looking at your obstacle more realistically, what changed in your plan?",question:"When outside conditions get in the way…",options:["I should assume it is because I did not believe enough.","I should ignore the conditions.","I can reconsider support, timing or the size of the goal."],correct:2,feedback:"A realistic plan takes outside conditions into account. Outcomes are not decided by your thoughts alone.",takeaway:"Name the blocking condition. Change the task or ask for the support it actually needs.",sources:["M01","M11","M14"],deeper:[{heading:"An obstacle is information, not an ingredient",paragraphs:["The 2021 mental-contrasting-with-planning review found a modest average improvement in goal attainment across 24 independent effects. Substantial variation and publication-bias indications limit certainty. It did not isolate feeling uncomfortable as an active ingredient. Naming a difficulty may be unpleasant, but deliberately intensifying distress is not the task. [M01]","Oettingen and colleagues' inspected 2015 procedure asked students to elaborate a desired outcome and a main obstacle, select a response, form an obstacle-to-action plan, and add its usual time and place. In Study 1, the planned comparison favored the method for scheduled calendar hours. The outcome was scheduling, not completed work, and the overall condition test was inconclusive. [M11] ODA adds a practical feasibility check and an actual attempt. Neither this shorter exercise nor its distinction between external conditions and personal responses was separately validated by that experiment."]},{heading:"When the right response is support",paragraphs:["Keep your desired outcome separate from the conditions needed to pursue it. A missing tool calls for access; an unsafe situation calls for protection; a care conflict may call for a different opening. This is a course design choice informed by the planning evidence, not a taxonomy that assigns every obstacle to one box. A support request is concrete when it names the help and opportunity you need. [M01, M11]","If someone has not answered, record the request and the absence of a reply. Do not record help received or task work completed. You can choose another feasible step, revise the goal, or pause. For persistent distress or significant impairment, seek qualified support rather than making the exercise more intense. The NIMH help guidance provides care and crisis routes, not evidence that ODA treats a condition. [M14] Your next record should describe the act you chose, including protection or support, without recasting the original obstacle as a failure of belief."]}],example:{title:"Daniel changes the opening",text:"Daniel planned another résumé edit after dinner, but his daughter needed the shared laptop for homework. His record names the clash. He asks whether he can use it for ten minutes before dinner the next day. They agree. At that opening he improves one line, then stops. The application still needs work."}},{id:"manifest-4",v2:i[3],photo:{id:"1591462391971-9ffc57b382b9",alt:"Colorful sticky notes and pens"},schemaVersion:2,title:"Stop waiting for the right mood",minutes:6,goal:"Use a recognizable start cue and a small response to your experiment's observed sticking point.",reading:["A start cue and an obstacle response have different jobs. “After the plates are cleared, write one résumé line” creates an opening. “If I get stuck, describe one shift change” helps inside that opening.","Research across varied goals found that specific if-then plans supported follow-through on average. They do not remove all memory, effort, or practical barriers. Keep your task; respond to a recorded obstacle if one exists. Pick one noticeable cue and one response you can carry out there. If the cue never occurs, record no occasion and choose another opening."],practice:["Describe one obstacle signal in the form “If …”.","In the “then …” part, write a single small behavior.","Check that the plan fits the time and tools you have, then rehearse it once."],reflection:"What is your if-then sentence?",question:"Which plan can actually be tried?",options:["Everything will sort itself out.","If I get stuck when I open the file, I will write the title first.","If I send good energy, all the obstacles will disappear."],correct:1,feedback:"The second option links a specific situation to an observable behavior. The approach studied in research looks like this kind of action planning.",takeaway:"Give starting an opening and getting stuck a response. Then test whether either actually happened.",sources:["M02","M10","M11"],deeper:[{heading:"What specific planning supports",paragraphs:["Gollwitzer and Sheeran's 2006 chapter pooled 94 independent tests with 8,461 participants. If-then planning showed an average goal-attainment effect of d = .65, with a 95% confidence interval from .60 to .70. Tasks and procedures varied, and this older evidence was not uniformly preregistered. It does not establish that any sentence a learner writes will work. [M02]","The opportunity-planning experiment asked students to select a specific time and place to begin a report. Its timeliness comparison concerned identifiable returners, not everyone assigned to the task. [M10] The practical lesson is narrower than “a plan replaces willpower.” Decide a response in advance, then check whether the situation occurred, you noticed it, and the response fit. Keep external reminders if you need them. A note beside a tool is an ODA option, not a tested guarantee of noticing."]},{heading:"Two jobs, one continuing experiment",paragraphs:["Your starting appointment answers when you will attempt the task. Your coping response answers what you will do if an observed obstacle appears. The inspected mental-contrasting procedure linked an obstacle to a response and added its usual time and place; it did not establish that everyone needs two separate rules. [M11] This course separates their jobs to make your existing experiment easier to diagnose.","Suppose the planned opening never arrives. There is no basis for saying the coping response failed. If the opening arrives but you miss it, change the cue or reminder. If you notice it but the response is too large, shrink the next useful task unit. These are choices to test, not findings proven by one private log. Keep old records tied to their original minimum. A different next plan should not turn an incomplete past attempt into completed work. Review your actual move, and retain the option to seek support, rest, pause, or change the goal."]}],example:{title:"Daniel uses the cue",text:"Daniel places a note beside the shared laptop: “After the plates are cleared, improve one line. If stuck, describe one shift change.” On Thursday the cue arrives and he notices the note. He writes one useful line, but cannot finish the section before family duties resume. His record keeps both facts."}},{id:"manifest-5",v2:i[4],photo:{id:"1762920738995-f393efe82205",alt:"Wooden signpost pointing in several directions in a forest"},schemaVersion:2,title:"No result yet? Read your actual record",minutes:6,goal:"Use your experiment's records to choose a feasible next step and next week's review.",reading:["Read the records for the same goal. Separate what you planned, rehearsed, actually did, and received from others. A saved draft proves draft work. It does not prove an application was sent or an employer is interested.","A review of 138 experiments found average benefits from increasing progress monitoring. It did not validate this exact record or an ideal review schedule. Choose from your facts: repeat a workable step, change one problem, seek feedback, or stop an unsuitable goal. If no attempt exists, name that gap and make your first useful unit."],practice:["Do your first small attempt, or fix exactly when you will do it.","Set a reasonable date to check the result, and use the questions “What did I try, and what did I learn?”","Choose what fits best: continue, make it smaller, get support, or change the goal."],reflection:"On which day, and looking at which information, will you review your plan?",question:"When the result you wanted does not come, what is the most useful review?",options:["My thoughts were not strong enough.","Looking at the behaviors I tried and the conditions, then making the next choice.","Keeping the same expectation without looking at reality."],correct:1,feedback:"Comparing the plan with reality gives you new information. No course guarantees a result; you can weigh your own part and the outside conditions together.",takeaway:"Let records change the next move. Effort, preparation, and outside results tell different stories.",sources:["M03","M01"],deeper:[{heading:"Monitoring informs a decision",paragraphs:["Harkin and colleagues' 2016 review included 138 experiments with random allocation and 19,951 participants overall. The goal-attainment analysis used 18,398 participants and found d = .40, with a 95% confidence interval from .32 to .48. A small-study sensitivity adjustment gave a lower estimate. Interventions, goals, and recording methods differed. The review did not test ODA's receipt or next-day card. [M03]","Larger effects were associated with recorded or publicly reported progress across studies. Those moderator comparisons do not establish that public disclosure is necessary or that one app format causes a benefit. Keep personal details private if that fits your situation. Use records to compare what the plan asked for with the act you actually reported. An absent record remains unknown. A completed preparation step, unanswered request, or stopped attempt should retain its own label. This makes your next decision reviewable without demanding a positive story."]},{heading:"Choose next week without rewriting this one",paragraphs:["A short personal log can suggest a pattern, but it cannot prove why an outside outcome occurred. Applications, orders, and another person's response may depend on quality, timing, resources, or circumstances your record does not measure. Monitoring research supports using information; it does not establish a universal number of attempts before changing a goal. [M03] Your review should keep that uncertainty visible.","Select one feasible next opportunity and a review point for the coming week. Retain your usable minimum and what helped access the task; change the part your records actually question. If no attempt is recorded, either report known facts or treat the next small act as your first experiment. Do not invent a history of effort. Planning studies show average benefits with variation, not guaranteed outcomes. [M01] Pausing, requesting feedback, finding practical support, or choosing another direction can be a deliberate result of the review. Keep the earlier record so the reason for that choice remains visible."]}],example:{title:"Daniel chooses next week",text:"Daniel reads three dated edits and one missed laptop opening. His résumé is clearer, but he has not sent an application. He chooses one suitable vacancy, checks its requirements, and submits the prepared version on Friday. He records the submission and schedules a review next week. There is no reply yet."}},...s.map(I)]},K=Object.freeze(Object.defineProperty({__proto__:null,COURSE:M,MANIFEST_LESSONS_V2:i,SOURCES:W},Symbol.toStringTag,{value:"Module"})),D=[{id:"meditation-M01",title:"Goyal et al. · 2014 · Meditation programs for psychological stress and well-being",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"47 randomized trials involving 3,515 adults with clinical conditions or stress found modest average anxiety, depression and pain benefits. Programs included at least four hours of teacher-present training.",limitation:"These were taught programs, not brief ODA practices. No superiority over active treatments was established; that does not prove equivalence. Several outcomes had insufficient evidence."},{id:"meditation-M03",title:"NCCIH · Meditation and mindfulness: effectiveness and safety",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"Public guidance cautions against replacing conventional care or delaying assessment. Research on harms is limited; brain images alone do not establish practical health benefits.",limitation:"Guidance is not a trial of ODA. Shortening practice, opening eyes or choosing outward anchors cannot guarantee safety."},{id:"meditation-M04",title:"Farias et al. · 2020 · Adverse events in meditation practices and therapies",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"The review included 83 heterogeneous studies with 6,703 participants; 55 studies reported at least one adverse experience. Pooled prevalence was 8.3%, with substantially different estimates in experimental and observational studies.",limitation:"Definitions and ascertainment varied. This is not an individual risk estimate for a brief app session, and reported events were not all established as caused by meditation."},{id:"meditation-M05",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 independent tests involving 8,461 participants found an average goal-attainment benefit from plans linking a recognizable situation with a specific response.",limitation:"Goals and designs varied, mostly with university students. This does not establish a benefit for ODA’s routine, an optimal meditation dose or a calm state."},{id:"meditation-M06",title:"Gan, Zhang & Chen · 2022 · Effects of body scan meditation",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"14 independent randomized-trial articles found a small mindfulness difference versus passive controls: g=.268, 95% CI .032 to .504. Standalone health evidence remains uncertain.",limitation:"Quality was low and heterogeneity high. The abstract does not verify total participants or health-effect estimates. It establishes neither universal ineffectiveness nor brief-scan health benefits."},{id:"meditation-M07",title:"Fischer, Messner & Pollatos · 2017 · Interoceptive processes after body scanning",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2017.00452/full",type:"research",finding:"An eight-week, twenty-minute daily body-scan protocol did not significantly outperform an audiobook on heartbeat counting in Study 1. Study 2 favored scanning over an inactive control.",limitation:"Small student samples and comparator-sensitive results. Heartbeat counting does not diagnose disease, explain numbness or validate ODA’s abbreviated contact exercise."},{id:"meditation-M08",title:"Hasenkamp et al. · 2012 · Mind wandering during focused meditation",url:"https://wendyhasenkamp.net/wp-content/uploads/2016/02/hasenkamp-neuroimage-2012.pdf",type:"research",finding:"Fourteen experienced meditators marked wandering during breath-focused MRI practice. Researchers modeled wandering, awareness, shifting attention and sustained focus.",limitation:"Small exploratory imaging study, not a beginner intervention. It does not establish brain improvement, health benefits or effects of sound, contact or task-transfer adaptations."},{id:"meditation-M09",title:"Zeng et al. · 2015 · Loving-kindness and positive emotions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"24 empirical reports involved 1,759 people. Eight randomized waitlist comparisons found a modest average daily positive-emotion benefit. Pooled g=.395 or .392 used alternative measurements from one trial.",limitation:"Those estimates are sensitivity variants, not separate energetic and calm effects. Few active comparisons; no guaranteed kindness, relationship improvement or personality change. The bias-percentage denominator is unverified."},{id:"meditation-M11",title:"Fredrickson et al. · 2008 · Loving-kindness workshop and personal resources",url:"https://d1ftyfwtsv9bor.cloudfront.net/cbrt-readings/mod-6/fredrickson-open-hearts-build-lives-2008.pdf",type:"research",finding:"The program used six instructor-led sessions over seven weeks plus home recordings. A condition-by-week positive-emotion effect was significant among 139 completers.",limitation:"The same effect was nonsignificant in intent-to-treat and per-protocol analyses. Exclusions and waitlist comparison limit inference. Brief wishes are not this workshop or evidence of behavioral transfer."},{id:"meditation-M12",title:"Álvarez-Pérez et al. · 2022 · Mantra-based meditation review",url:"https://doi.org/10.3390/ijerph19063380",type:"research",finding:"51 studies covered varied mantra methods. The anxiety analysis included 25 studies and 1,825 people; its average estimate favored intervention, with a prediction interval including no benefit.",limitation:"No study had overall low bias risk. This does not validate Benson’s exact method or ODA’s short word anchor, establish superiority, or make paid training necessary."},{id:"meditation-M13",title:"Toth et al. · 2020 · Mental practice and performance",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"The university abstract reports 37 task and skill studies and a small publication-bias-adjusted performance association, r=.131.",limitation:"Full methods, total participants, confidence interval, 115-effects count and older comparison were not verified. This does not establish personality change, healing or the efficacy of ODA’s rehearsal-and-action combination."},{id:"meditation-M14",title:"Lally et al. · 2010 · Habit formation in everyday life",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"96 volunteers tracked eating, drinking or activity behaviors for 84 days. Among 39 acceptable models, time to 95% of modeled automaticity varied substantially.",limitation:"Observational modeling, partly extrapolated beyond follow-up. Neither 21 nor 66 days is a deadline; this was not meditation. The nonrandomized omission analysis cannot guarantee consequences of future missed practice."},{id:"meditation-M15",title:"Simonsson et al. · 2026 · Adverse experiences in brief meditation",url:"https://mental.jmir.org/2026/1/e95628/",type:"research",finding:"5,049 US and UK adults were randomized to brief practices or usual internet use. No detectable excess distress appeared for meditation versus internet use: OR 1.05, 95% CI .76 to 1.47.",limitation:"Distress still occurred. Overall 4.1% includes all groups, not meditation only. This secondary analysis does not prove identical risk, repeated-session safety or a meditation-specific duration effect."},{id:"meditation-M16",title:"Harvard Health · 2011 · Benson’s relaxation response",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Practitioner guidance describes comfortable quiet sitting, repeating an acceptable word, sound, phrase or prayer, and returning when thoughts intrude. The recommendation was ten to twenty minutes daily.",limitation:"Blog and anecdote, not an efficacy trial. Complete feet-to-face and exhale instructions, required one-week word use, secular/religious equivalence and a tested short version were not verified."},{id:"meditation-M17",title:"Plum Village · Walking meditation",url:"https://plumvillage.org/live-events/walking-meditation",type:"technique",finding:"Traditional guidance attends to foot contact and ordinary breathing. Step coordination is optional and follows a comfortable rhythm; attention can include surroundings.",limitation:"Practice guidance, not an isolated efficacy trial or optimal dose. Keep eyes open and hazards first. Seated and shorter ODA alternatives are adaptations."},{id:"meditation-M18",title:"Sharon Salzberg · Lovingkindness book page",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"The author page establishes Buddhist loving-kindness provenance and displays brief good wishes.",limitation:"Book body and complete scripts were not inspected. The page does not verify every phrase or recipient sequence or establish clinical efficacy. ODA wording and voluntary recipients are adaptations."},{id:"meditation-M19",title:"David Treleaven · Trauma-sensitive mindfulness",url:"https://davidtreleaven.com/",type:"guidance",finding:"The educator warns that sustained inward attention can activate traumatic stress, including flashbacks, distress and dissociation.",limitation:"Homepage and practitioner framing, not an efficacy trial. It does not establish risk frequency or that specific eyes-open, shorter or outward-anchor adjustments prevent harm."},{id:"meditation-M20",title:"Joe Dispenza · Breaking the Habit of Being Yourself · publisher contents",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Publisher contents identify a staged four-week sequence including recognition, declaring, surrendering, redirecting and creating or rehearsing.",limitation:"Book body not inspected. No controlled validation of the branded package or ODA’s combined rehearsal exercise was identified. Planning and task-rehearsal evidence do not establish quantum, genetic, healing or personality claims."},{id:"meditation-M21",title:"Kral et al. · 2022 · Absence of structural brain changes after MBSR",url:"https://doi.org/10.1126/sciadv.abk3316",type:"research",finding:"Across two randomized trials, 218 meditation-naïve participants completed structural scans. Eight-week MBSR produced no detected gray-matter volume, density or cortical-thickness changes against controls.",limitation:"This counters guaranteed structural rewiring. It does not establish no functional changes or no clinical benefit, and does not test ODA."},{id:"meditation-goyal",title:"Goyal et al. · 2014 · Meditation programs for psychological stress and well-being",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"47 randomized trials involving 3,515 adults with clinical conditions or stress found modest average anxiety, depression and pain benefits. Programs included at least four hours of teacher-present training.",limitation:"These were taught programs, not brief ODA practices. No superiority over active treatments was established; that does not prove equivalence. Several outcomes had insufficient evidence."},{id:"meditation-body-scan",title:"Gan, Zhang & Chen · 2022 · Effects of body scan meditation",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"14 independent randomized-trial articles found a small mindfulness difference versus passive controls: g=.268, 95% CI .032 to .504. Standalone health evidence remains uncertain.",limitation:"Quality was low and heterogeneity high. The abstract does not verify total participants or health-effect estimates. It establishes neither universal ineffectiveness nor brief-scan health benefits."},{id:"meditation-lovingkindness",title:"Zeng et al. · 2015 · Loving-kindness and positive emotions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"24 empirical reports involved 1,759 people. Eight randomized waitlist comparisons found a modest average daily positive-emotion benefit. Pooled g=.395 or .392 used alternative measurements from one trial.",limitation:"Those estimates are sensitivity variants, not separate energetic and calm effects. Few active comparisons; no guaranteed kindness, relationship improvement or personality change. The bias-percentage denominator is unverified."},{id:"mental-practice",title:"Toth et al. · 2020 · Mental practice and performance",url:"https://pure.ul.ie/en/publications/does-mental-practice-still-enhance-performance-a-24-year-follow-u/",type:"research",finding:"The university abstract reports 37 task and skill studies and a small publication-bias-adjusted performance association, r=.131.",limitation:"Full methods, total participants, confidence interval, 115-effects count and older comparison were not verified. This does not establish personality change, healing or the efficacy of ODA’s rehearsal-and-action combination."},{id:"meditation-adverse",title:"Farias et al. · 2020 · Adverse events in meditation practices and therapies",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"The review included 83 heterogeneous studies with 6,703 participants; 55 studies reported at least one adverse experience. Pooled prevalence was 8.3%, with substantially different estimates in experimental and observational studies.",limitation:"Definitions and ascertainment varied. This is not an individual risk estimate for a brief app session, and reported events were not all established as caused by meditation."},{id:"meditation-nccih",title:"NCCIH · Meditation and mindfulness: effectiveness and safety",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"Public guidance cautions against replacing conventional care or delaying assessment. Research on harms is limited; brain images alone do not establish practical health benefits.",limitation:"Guidance is not a trial of ODA. Shortening practice, opening eyes or choosing outward anchors cannot guarantee safety."},{id:"meditation-mind-wandering-cycle",title:"Hasenkamp et al. · 2012 · Mind wandering during focused meditation",url:"https://wendyhasenkamp.net/wp-content/uploads/2016/02/hasenkamp-neuroimage-2012.pdf",type:"research",finding:"Fourteen experienced meditators marked wandering during breath-focused MRI practice. Researchers modeled wandering, awareness, shifting attention and sustained focus.",limitation:"Small exploratory imaging study, not a beginner intervention. It does not establish brain improvement, health benefits or effects of sound, contact or task-transfer adaptations."},{id:"meditation-trauma-sensitive",title:"David Treleaven · Trauma-sensitive mindfulness",url:"https://davidtreleaven.com/",type:"guidance",finding:"The educator warns that sustained inward attention can activate traumatic stress, including flashbacks, distress and dissociation.",limitation:"Homepage and practitioner framing, not an efficacy trial. It does not establish risk frequency or that specific eyes-open, shorter or outward-anchor adjustments prevent harm."},{id:"meditation-kabat-zinn",title:"Goyal et al. · 2014 · Meditation programs for psychological stress and well-being",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"47 randomized trials involving 3,515 adults with clinical conditions or stress found modest average anxiety, depression and pain benefits. Programs included at least four hours of teacher-present training.",limitation:"These were taught programs, not brief ODA practices. No superiority over active treatments was established; that does not prove equivalence. Several outcomes had insufficient evidence."},{id:"meditation-benson",title:"Harvard Health · 2011 · Benson’s relaxation response",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Practitioner guidance describes comfortable quiet sitting, repeating an acceptable word, sound, phrase or prayer, and returning when thoughts intrude. The recommendation was ten to twenty minutes daily.",limitation:"Blog and anecdote, not an efficacy trial. Complete feet-to-face and exhale instructions, required one-week word use, secular/religious equivalence and a tested short version were not verified."},{id:"meditation-thich-nhat-hanh",title:"Plum Village · Walking meditation",url:"https://plumvillage.org/live-events/walking-meditation",type:"technique",finding:"Traditional guidance attends to foot contact and ordinary breathing. Step coordination is optional and follows a comfortable rhythm; attention can include surroundings.",limitation:"Practice guidance, not an isolated efficacy trial or optimal dose. Keep eyes open and hazards first. Seated and shorter ODA alternatives are adaptations."},{id:"meditation-salzberg",title:"Sharon Salzberg · Lovingkindness book page",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"The author page establishes Buddhist loving-kindness provenance and displays brief good wishes.",limitation:"Book body and complete scripts were not inspected. The page does not verify every phrase or recipient sequence or establish clinical efficacy. ODA wording and voluntary recipients are adaptations."},{id:"dispenza-breaking-habit",title:"Joe Dispenza · Breaking the Habit of Being Yourself · publisher contents",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Publisher contents identify a staged four-week sequence including recognition, declaring, surrendering, redirecting and creating or rehearsing.",limitation:"Book body not inspected. No controlled validation of the branded package or ODA’s combined rehearsal exercise was identified. Planning and task-rehearsal evidence do not establish quantum, genetic, healing or personality claims."}],u=[{schemaVersion:2,revision:2,id:"meditation-1",courseId:"meditation",locale:"en",title:"Your mind wandered. Make one return.",goal:"Practice one comfortable attention return, then do one useful act.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Lost another minute to worry? Give your attention somewhere to return, then use it.",reason:{id:"meditation-1-reason",label:"What deserves your attention, and what is distraction costing?",kind:"text",maxLength:160,optional:!0,suggestions:["Lost drafting time to dinner planning","Missed what someone said","Left a useful task unfinished","No previous occasion"]},why:{id:"meditation-1-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Experienced meditators still notice their minds wandering. In a small breath-focus study, researchers tracked wandering, noticing, returning and staying. The study described attention during practice; it did not prove improved health. You can use that distinction without waiting for a quiet mind.","Choose a comfortable anchor: ordinary breathing, a sound or a visible object. Notice where attention went, then return once. Keep your eyes open if preferred. After this short pause, do one useful act for your chosen task or conversation. Record the return and the act separately; neither requires calm."],example:{title:"Leyla’s first return",text:"At 1:10, Leyla sits at her kitchen table before drafting a volunteer update. She attends to a room sound, notices she is planning dinner, and returns. Then she writes the first useful sentence of the update. Her attention drifts again. She records both the return and the sentence, without claiming a quiet mind."}},move:{invitation:"Keep your act; edit the volunteer-update example.",instructions:["Notice a comfortable anchor, then return when you notice wandering.","Do your chosen useful act; record what happened."],prompts:[],suggestions:{action:["Return; write the volunteer update’s opening sentence","Return; ask when the volunteer shift starts"],minimum:["Make one return; write one update sentence","Return; ask one question about the shift"],cue:["After lunch, before drafting the volunteer update","When the volunteer coordinator invites questions"],place:["Kitchen table, seated with eyes open","In the volunteer coordinator’s message thread"],minutes:[2,1,3],fallback:["Use a visible object; write the update sentence","Pause and choose support"],observation:["Attention return and update sentence written","What anchor felt workable"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Return; write the volunteer update’s opening sentence",minimum:"Make one return; write one update sentence",minutes:2,cueHint:"After lunch, before drafting the volunteer update",placeHint:"Kitchen table, seated with eyes open",obstacleHint:"Watching my breath feels uncomfortable",fallbackHint:"Use a visible object; write the update sentence",observationHint:"Attention return and update sentence written"},stopRule:"Stop for growing distress, dizziness or detachment. Orient outward; seek support if symptoms persist or concern you.",accessibleAlternative:"Keep eyes open; use sound, a visible object or seated contact."},result:{question:"Did you return and do your chosen useful act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-1-decision",scenario:"Leyla’s one-minute sound practice is restless but tolerable. She notices dinner planning. Her update still needs its first sentence.",question:"What fits this attempt?",options:[{id:"meditation-1-restart",text:"Restart the minute for a cleaner practice before beginning the update.",feedback:"A fresh start is tempting, but the planned pause was not a concentration test. Return once, finish as planned, and write the useful sentence."},{id:"meditation-1-return",text:"Return to the sound, finish the pause, then write the sentence.",feedback:"This tests the chosen skill and its purpose. A restless pause can contain a real return; the sentence shows what happened afterward, without proving calm."},{id:"meditation-1-solve",text:"Use the remaining pause to settle dinner plans before starting the update.",feedback:"Solving dinner may feel productive, but it changes this attempt’s purpose. Note the thought if needed, return to the anchor, then do the chosen act."}],bestOptionId:"meditation-1-return"}},carry:{takeaway:"Practice the return, then use your attention for something you chose.",followUp:{questionId:"meditation-1-return",question:"Did the return lead to your chosen act, or stop at the pause?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Experienced minds wander too",paragraphs:["Hasenkamp and colleagues studied fourteen experienced meditators during twenty minutes of breath-focused practice in an MRI scanner. Participants attended to sensations at the nostrils or upper lip. They pressed a button when they realized attention had completely wandered, then returned. Researchers modeled four phases: wandering, awareness, shifting back and sustained focus. This is a useful description of one task, not a prescription for how long everyone should sit. (meditation-M08)","The imaging associations do not establish that each return rewires your brain, increases intelligence or changes health. ODA’s sound anchor, open eyes and short introductory pause differ from the laboratory procedure. Use them as voluntary adaptations. In your record, distinguish attending, noticing a drift and returning. You do not need to count every thought or manufacture wandering to meet a target."]},{heading:"A short pause has a different promise",paragraphs:["Goyal’s review included forty-seven randomized trials and 3,515 adults with clinical conditions or stress. Programs involved at least four hours of teacher-present training. Average anxiety, depression and pain outcomes favored some mindfulness programs modestly. These findings do not establish those outcomes from a one-minute ODA pause. The review found no superiority over active treatments; that does not demonstrate equivalence to them. (meditation-M01)","Your experiment has a narrower question: can you choose an anchor, return and then use attention for an ordinary act? ODA has not tested this combination. A useful sentence, a question or a decision to pause can be reported without a health claim. NCCIH cautions against replacing care or delaying assessment. Keep prescribed care and seek appropriate support when practice or symptoms concern you. (meditation-M03)"]}],sourceIds:["meditation-M08","meditation-M01","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-2",courseId:"meditation",locale:"en",title:"Notice discomfort before you push through",goal:"Test comfortable contact, make a practical adjustment, then return to your chosen act.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Ignored your uncomfortable chair again? Notice enough to make a useful choice.",reason:{id:"meditation-2-reason",label:"What need are you overriding to keep going?",kind:"text",maxLength:160,optional:!0,suggestions:["Uncomfortable seating","A break I needed","Pain that needs assessment","No need I noticed"]},why:{id:"meditation-2-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A body scan notices sensations; it does not diagnose them. In one eight-week study, body scanning did not outperform an audiobook on a heartbeat-counting task. Another comparison favored scanning over doing nothing. That difference matters: noticing your body is not a proven shortcut to better health.","Use this only if your earlier anchor felt awkward or you overlooked an ordinary need. Briefly notice two comfortable contact points, such as hands and seat. No clear sensation is an observation. Make one practical adjustment if useful, then do the same act you chose earlier. You may stay with an outward anchor instead."],example:{title:"Leyla changes the chair",text:"Before the next update session, Leyla notices her hands on the table and her seat on a hard chair. She chooses a cushion, then writes one useful sentence. Her shoulders still feel tense. She records the adjustment and sentence. She keeps room sounds as an alternative rather than committing to a full body scan."}},move:{invitation:"Keep your act; edit the chair-and-update example.",instructions:["Notice two comfortable contact points, or choose an outward anchor.","Make an ordinary adjustment, then do the same useful act."],prompts:[],suggestions:{action:["Adjust chair; write volunteer update’s opening sentence","Notice contact; ask when the volunteer shift starts"],minimum:["Write opening sentence after a comfortable contact check","Notice contact; ask one shift question"],cue:["After sitting for the volunteer update","When the volunteer coordinator invites questions"],place:["Kitchen table, using a comfortable chair","In the volunteer coordinator’s message thread"],minutes:[3,2,1],fallback:["Use room sounds; write the update sentence","Pause and request suitable support"],observation:["Comfort adjustment and update sentence written","Whether contact felt comfortable"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Adjust chair; write volunteer update’s opening sentence",minimum:"Write opening sentence after a comfortable contact check",minutes:3,cueHint:"After sitting for the volunteer update",placeHint:"Kitchen table, using a comfortable chair",obstacleHint:"Contact focus becomes uncomfortable",fallbackHint:"Use room sounds; write the update sentence",observationHint:"Comfort adjustment and update sentence written"},stopRule:"Stop if distress grows. New or persistent pain, numbness or concerning symptoms need medical assessment.",accessibleAlternative:"Use open eyes and room sounds; seated, nonmovement practice is enough."},result:{question:"Did you make a practical choice and do your act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-2-decision",scenario:"At her table, Leyla notices familiar shoulder tension. Focusing on it grows uncomfortable. Her update still needs one sentence.",question:"What fits this attempt?",options:[{id:"meditation-2-extend",text:"Scan additional regions first to understand the tension before choosing an adjustment.",feedback:"More observations can feel informative, but discomfort is growing and this exercise cannot explain its cause. Stop or shift outward, then choose a practical response."},{id:"meditation-2-hold",text:"Keep attention on the shoulder until it relaxes, then write the sentence.",feedback:"Waiting for relaxation makes a feeling the entry requirement. You can stop the uncomfortable focus, adjust the setting and write if appropriate without changing that feeling."},{id:"meditation-2-adapt",text:"Shift to room sounds, adjust the chair, then write if the setting fits.",feedback:"This preserves choice and the useful act while responding to discomfort. A contact exercise is optional; it does not require enduring unpleasant focus or diagnosing a sensation."}],bestOptionId:"meditation-2-adapt"}},carry:{takeaway:"Noticing earns its place when it informs a responsible next choice.",followUp:{questionId:"meditation-2-return",question:"Did you make a useful adjustment and then do your chosen act?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"A sensation is not a diagnosis",paragraphs:["Fischer and colleagues examined eight weeks of daily twenty-minute guided body scanning in small student samples. The recording moved attention through body regions and included whole-body attention and a closing phase. The complete script and region timings were not printed. ODA’s brief contact exercise is an adaptation rather than a reconstruction of that tested recording. (meditation-M07)","In Study 1, heartbeat-counting change was not significantly greater than with an audiobook. Study 2 favored scanning over an inactive comparison. Neither result establishes disease detection, interpretation of every bodily need or a health effect from today’s abbreviated exercise. “No clear sensation noticed” describes attention during this attempt. It must not be used to relabel new numbness, dismiss pain or postpone medical assessment. An ordinary comfort adjustment and a medical help request serve different needs."]},{heading:"Choose fit without claiming treatment",paragraphs:["Gan and colleagues reviewed fourteen independent randomized-trial articles about standalone body scanning. They reported a small mindfulness difference against passive controls, with low study quality and substantial variation. Standalone health benefits remain uncertain. That is neither proof that scanning never helps anyone nor evidence that a short scan is better than a long one. (meditation-M06)","Your comparison is about fit: was contact comfortable enough to use, and did you make a useful choice afterward? Keep the same chosen act so changing the anchor does not create a separate course project. Open eyes, outward attention, skipped regions and shortening are precautionary options, not verified trauma treatment or guaranteed protection. NCCIH advises keeping medical care and avoiding delayed assessment. An honest paused record can support a decision to get help, rest or use another suitable setting. (meditation-M03)"]}],sourceIds:["meditation-M07","meditation-M06","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-3",courseId:"meditation",locale:"en",title:"Breath watching awkward? Try one word.",goal:"If your anchor was awkward, test a neutral word before the same useful act.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Checking your breathing instead of doing your task? Try one neutral word.",reason:{id:"meditation-3-reason",label:"Will this pause support your act or postpone it?",kind:"text",maxLength:160,optional:!0,suggestions:["Supports the act when my anchor feels awkward","Postpones the act while I check for calm","Unsure until I try"]},why:{id:"meditation-3-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A repeated word is another anchor, not a stronger command. Benson’s practitioner guidance describes returning to a chosen word when thoughts intrude. It does not establish that a neutral word and a prayer have identical effects, or that one word must be kept for a week.","If breathing or contact felt awkward in your record, try an acceptable word such as “here.” Keep ordinary breathing and an easy gaze. When you notice distraction, return to the word. End at your chosen point, then do the same useful act. If your existing anchor fits, repeat it instead. Feeling calm is not the pass mark."],example:{title:"Leyla tries “here”",text:"Leyla’s record says breath watching made her check each inhale. At 1:10 the next day, she uses “here” as a quiet anchor for one minute, eyes open. She returns after a shopping thought, then writes her update sentence. The word feels ordinary rather than soothing. She records that and keeps the sentence as her useful minimum."}},move:{invitation:"Keep your act; edit the word-and-update example.",instructions:["Return to one acceptable word without adjusting your breathing.","End the pause, then do your same useful act."],prompts:[],suggestions:{action:["Use “here”; write volunteer update’s opening sentence","Use room sounds; ask when volunteer shift starts"],minimum:["Return to “here”; write the update sentence","Return once; ask one shift question"],cue:["After lunch, before writing the volunteer update","When the volunteer coordinator invites questions"],place:["Kitchen table, seated with eyes open","In the volunteer coordinator’s message thread"],minutes:[2,1,3],fallback:["Finish pause, then write the update sentence","End the pause and seek support"],observation:["Word tolerability and update sentence written","The useful act after the pause"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Use “here”; write volunteer update’s opening sentence",minimum:"Return to “here”; write the update sentence",minutes:2,cueHint:"After lunch, before writing the volunteer update",placeHint:"Kitchen table, seated with eyes open",obstacleHint:"I start testing whether I feel calm",fallbackHint:"Finish pause, then write the update sentence",observationHint:"Word tolerability and update sentence written"},stopRule:"Stop for growing distress, dizziness or detachment; orient outward and get support if needed.",accessibleAlternative:"If the word is uncomfortable, choose sound or a visible object. Keep eyes open."},result:{question:"Did you end the pause and do your chosen act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-3-decision",scenario:"Leyla’s word feels neutral and tolerable, but she keeps checking for calm. Her planned minute is almost over.",question:"What fits this attempt?",options:[{id:"meditation-3-end",text:"Return to the word, finish the planned minute, then write her sentence.",feedback:"The word supplies an anchor, not a mood test. Ending as planned keeps the useful act available. Record tolerability and the actual sentence rather than demanding calm."},{id:"meditation-3-switch",text:"Try another word for the remaining minute to find a more soothing one.",feedback:"Changing an uncomfortable anchor can be reasonable. Here the word is tolerable; repeated searching answers a different question and risks replacing the useful act with mood checking."},{id:"meditation-3-lengthen",text:"Add a second minute so the word has more time to produce calm.",feedback:"Extra practice is a choice, but no evidence establishes a required calming dose here. Finish the feasible pause and do the act before deciding whether another trial helps."}],bestOptionId:"meditation-3-end"}},carry:{takeaway:"Choose an anchor you can use; judge the act that follows separately.",followUp:{questionId:"meditation-3-return",question:"Was the word workable, and did your chosen act follow?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Where the word practice comes from",paragraphs:["The Harvard Health account of Benson’s relaxation response describes comfortable sitting, quiet surroundings, a chosen word, sound, phrase or prayer, and returning when thoughts intrude. Its practitioner recommendation is ten to twenty minutes daily. It is a blog and personal account rather than a trial of every listed step. The opened page does not verify a complete feet-to-face relaxation script or a required exhale sequence. (meditation-M16)","ODA’s shorter word trial, open eyes and neutral wording are adaptations. They do not inherit an established medical effect from that page. You can choose a prayer privately if it fits your beliefs, but no comparative trial here establishes equal effects for religious and secular anchors. Nor does the page establish a necessary one-week word commitment. Choose based on acceptability and your actual record rather than historical fidelity."]},{heading:"A review of mantras is broader than this trial",paragraphs:["Álvarez-Pérez and colleagues combined fifty-one studies of varied mantra-based practices. Their anxiety analysis included twenty-five studies and 1,825 people. The average estimate favored intervention, but the prediction interval included no benefit. No study was rated overall low risk of bias, and follow-up was limited. These qualifications matter when a named method is offered as a universal solution. (meditation-M12)","The review does not validate Benson’s exact method, today’s one-minute word anchor or superiority over other practices. No purchase or paid training is necessary for this voluntary experiment. Keep the same real-life act while testing one anchor change so the record stays interpretable. Describe what you used and what followed; a single favorable day cannot prove the word caused improvement. NCCIH’s care boundary still applies, including when a practice feels pleasant. (meditation-M03)"]}],sourceIds:["meditation-M16","meditation-M12","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-4",courseId:"meditation",locale:"en",title:"Arrive before your phone does",goal:"Use one safe transition to return attention, then do your chosen act on arrival.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Reached your desk still inside your phone? Use one transition to arrive on purpose.",reason:{id:"meditation-4-reason",label:"Which arrival habit will you give up so your chosen act can start?",kind:"text",maxLength:160,optional:!0,suggestions:["Delay messages until after the first sentence","Put phone away before the conversation","No competing habit noticed"]},why:{id:"meditation-4-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Walking attention uses foot contact and ordinary breathing. Plum Village’s guidance offers step coordination as an option, not a required breathing ratio. It is traditional instruction rather than proof of a special health effect. Your surroundings take priority over an anchor.","If your earlier pause keeps getting crowded out, use an existing transition. Keep eyes open and move at a safe pace. Notice contact only where it does not compete with hazards. A seated, stationary version works as an adaptation. At the destination, do your same useful act. This tests arrival and follow-through, not how slowly you can walk."],example:{title:"Leyla’s library arrival",text:"Leyla keeps missing the kitchen cue, so she tries her usual library arrival. She watches crossings normally and notices a few foot contacts in the quiet entrance. At her table she puts her phone aside and writes one useful update sentence. A later notification still interrupts her. She records the arrival and sentence rather than calling the day distraction-free."}},move:{invitation:"Keep your act; edit the library-arrival example.",instructions:["Keep eyes open and surroundings first; breathing stays ordinary.","At your destination, do the same useful act."],prompts:[],suggestions:{action:["Arrive; write the volunteer update’s opening sentence","Arrive; ask when the volunteer shift starts"],minimum:["Notice seated contact; write one update sentence","Notice contact; ask one shift question"],cue:["When I arrive at the library table","When I arrive for the volunteer check-in"],place:["At the library writing table","At the accessible volunteer meeting table"],minutes:[2,1,3],fallback:["Notice seated contact at arrival","Skip the anchor and attend to hazards"],observation:["Library arrival and update sentence written","Whether the transition cue occurred"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Arrive; write the volunteer update’s opening sentence",minimum:"Notice seated contact; write one update sentence",minutes:2,cueHint:"When I arrive at the library table",placeHint:"At the library writing table",obstacleHint:"The route demands all my attention",fallbackHint:"Notice seated contact at arrival",observationHint:"Library arrival and update sentence written"},stopRule:"Keep eyes open. Stop anchor practice when hazards compete; stop and seek support if distress or dizziness grows.",accessibleAlternative:"Use a seated, stationary sound or contact anchor; no movement is required."},result:{question:"Did you arrive safely and do your chosen act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-4-decision",scenario:"Leyla’s route has crowded crossings. Her chosen writing table is available when she arrives. She planned attention to foot contact.",question:"What fits this attempt?",options:[{id:"meditation-4-count",text:"Preserve her step rhythm on the route, then write at the table.",feedback:"A familiar rhythm may appeal, but crossings need attention. Drop counting whenever it competes with hazards; the useful act can still happen at the destination."},{id:"meditation-4-arrive",text:"Attend to the crossings, notice seated contact on arrival, then write.",feedback:"This keeps safety first and tests the chosen arrival cue. Seated contact is an ODA adaptation, not a lesser result or a proven equivalent treatment."},{id:"meditation-4-relocate",text:"Wait for a quiet park route before returning to the writing experiment.",feedback:"A park may fit another practice, but her task space is available now. Use a safe stationary arrival anchor rather than making an ideal route a prerequisite."}],bestOptionId:"meditation-4-arrive"}},carry:{takeaway:"Let safe arrival support your chosen act; the route is not a concentration test.",followUp:{questionId:"meditation-4-return",question:"Did the transition help you start your chosen act?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Rhythm follows the route",paragraphs:["Plum Village’s walking guidance attends to feet contacting the ground, ordinary breathing and the surrounding world. It gives examples of coordinating steps with a comfortable breath rhythm. Those examples are not respiratory targets to force, and the page is practitioner guidance rather than an isolated walking-meditation efficacy trial. The tradition’s spiritual language is not evidence of medical healing. (meditation-M17)","ODA uses a short, familiar transition only when it addresses a problem in your earlier record, such as a seated cue that rarely occurs. Keep eyes open everywhere, including quiet paths. Drop counts when they interfere with route awareness. A seated or stationary anchor is an accessibility adaptation, not a scientifically established equivalent. Your useful act belongs at the destination; record it separately from the walk or arrival pause."]},{heading:"An existing transition can become a cue",paragraphs:["Gollwitzer and Sheeran’s review combined ninety-four independent tests of situation-linked response plans. On average, these plans supported goal attainment across varied domains. Most participants were university students, and the synthesis does not establish an effect for this library-arrival routine. It supports a bounded planning idea: choose a recognizable opportunity and a feasible response. (meditation-M05)","“When I reach my table, I return once and write my first useful sentence” names both the opportunity and behavior. If the destination is unavailable, choose an accessible alternative rather than pretending the original attempt happened. A busy route is a real constraint, not poor discipline. This adaptation does not borrow benefits from exercise research or promise less rumination. NCCIH cautions against replacing care and notes limited harm research; being outside does not make every practice suitable. (meditation-M03)"]}],sourceIds:["meditation-M17","meditation-M05","meditation-M03"]}},{schemaVersion:2,revision:2,id:"meditation-5",courseId:"meditation",locale:"en",title:"Keep the boundary. Drop the sting.",goal:"If harshness blocks your act, try an optional good wish before a clear response.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"About to add a jab to your reply? Keep your point without the extra sting.",reason:{id:"meditation-5-reason",label:"What boundary or useful point should survive this reply?",kind:"text",maxLength:160,optional:!0,suggestions:["I cannot cover Sunday","My actual available hours","The information needed for the update"]},why:{id:"meditation-5-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Loving-kindness studies measure reported feelings, not guaranteed kindness in behavior. A review found modest average positive-emotion benefits, mostly against waitlists. That does not prove a brief wish will improve your reply or repair a relationship.","Use this option if your record shows harshness getting in the way of your chosen act. Offer one voluntary wish to yourself or a safe loved person: “May you have support.” Warmth is optional. Then do your same useful act, such as sending a clear sentence without a jab. Keep the boundary. Skip wishes or stop if they hurt; contact with an unsafe person is never required."],example:{title:"Leyla’s firm sentence",text:"Leyla’s update needs a reply about extra volunteer work. Her draft includes “As you should already know.” At her table, she offers a quiet wish for her sister, then removes the jab and sends her sentence: “I can cover Saturday, but not Sunday.” She still feels annoyed. She records the sent boundary, without crediting the wish for a better relationship."}},move:{invitation:"Keep your act; edit the volunteer-reply example.",instructions:["Choose yourself or a safe recipient; warmth is optional.","Use your clear sentence while preserving the point or boundary."],prompts:[],suggestions:{action:["Tell coordinator I can cover Saturday only","Write the update sentence without self-attack"],minimum:["Send Saturday availability without the jab","Write one usable volunteer update sentence"],cue:["Before replying to the volunteer coordinator","After lunch, before writing the volunteer update"],place:["In the volunteer coordinator’s message thread","At the kitchen writing table"],minutes:[2,1,3],fallback:["Skip wishes; send the clear availability sentence","Pause and choose protection or support"],observation:["Availability sentence sent; reply or silence","Whether wishes felt acceptable"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Tell coordinator I can cover Saturday only",minimum:"Send Saturday availability without the jab",minutes:2,cueHint:"Before replying to the volunteer coordinator",placeHint:"In the volunteer coordinator’s message thread",obstacleHint:"The wish feels painful or forced",fallbackHint:"Skip wishes; send the clear availability sentence",observationHint:"Availability sentence sent; reply or silence"},stopRule:"Stop distressing wishes; use outward attention or support. Keep boundaries and avoid unsafe contact.",accessibleAlternative:"Keep eyes open; choose a safe recipient, neutral wording or no wishes."},result:{question:"Did you use your clear sentence or chosen act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-5-decision",scenario:"Leyla’s safe volunteer coordinator requests Sunday work. She cannot cover it. Her draft has a jab, and she still feels annoyed.",question:"What fits this attempt?",options:[{id:"meditation-5-delay",text:"Hold the reply until the good wish changes her annoyed feeling.",feedback:"A delay can help when facts are missing. Here her availability is clear. She can remove the jab and send the boundary without waiting for warmth."},{id:"meditation-5-accept",text:"Send the original reply because the jab might make the Sunday limit unmistakable.",feedback:"Wanting the limit taken seriously makes the jab tempting. A clear availability sentence already communicates it; the extra criticism risks distracting from the boundary she needs to preserve."},{id:"meditation-5-send",text:"Remove the jab, state her availability, and send the clear reply now.",feedback:"This carries the chosen act into life without making emotion the gate. An optional wish may accompany it; the evidence is the sentence she actually sends."}],bestOptionId:"meditation-5-send"}},carry:{takeaway:"A voluntary wish can accompany a clear act; it never requires surrendering your boundary.",followUp:{questionId:"meditation-5-return",question:"Did your actual sentence keep the point and remove any unnecessary sting?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Positive feeling is a different outcome",paragraphs:["Zeng and colleagues reviewed twenty-four reports involving 1,759 people. Eight randomized waitlist comparisons informed the daily positive-emotion estimate. The pooled values .395 and .392 came from choosing alternative arousal measurements in one trial. They are alternative estimates of the same outcome, not separate effects on energetic and calm emotions. Few studies used active comparisons. (meditation-M09)","Another early workshop included six instructor-led sessions over seven weeks plus home recordings. Its condition-by-week positive-emotion effect was significant among 139 completers, but not in intent-to-treat or per-protocol analyses. Exclusions and waitlist comparison limit what can be concluded. A short wish before writing is not that workshop. Neither paper establishes that wishes make you kinder, improve this relationship or cause the invented example’s clear reply. (meditation-M11)"]},{heading:"Intention, choice and boundaries",paragraphs:["Salzberg’s author page establishes the loving-kindness tradition and displays brief good wishes. The author page does not supply a complete script or establish every phrase and recipient order. Today’s original wording, safe recipient choice and abbreviated practice are ODA adaptations, not a complete teacher protocol. A difficult person is optional and never a requirement for completion. (meditation-M18)","Keep the distinction between an intention and a feeling. You may offer a wish without warmth, choose someone safe rather than yourself, skip the practice or stop if it becomes distressing. None of those choices decides whether your boundary is valid. Review the actual sentence: what was necessary, what was a jab, and what response followed? An unchanged mood or unanswered message is still a factual record. Use your previous anchor if it fits better; the course experiment remains your chosen useful act."]}],sourceIds:["meditation-M09","meditation-M11","meditation-M18"]}},{schemaVersion:2,revision:2,id:"meditation-6",courseId:"meditation",locale:"en",title:"Rehearse the response you keep missing",goal:"If a familiar trigger derails your act, prepare one response and use it at the cue.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Still sent the sharp message? Rehearse your actual response.",reason:{id:"meditation-6-reason",label:"What did the last reaction cost, and what response is yours to change?",kind:"text",maxLength:160,optional:!0,suggestions:["Sent words I later had to repair","Missed a useful opening","Left the unresolved detail unclear","No earlier attempt"]},why:{id:"meditation-6-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Mental-practice research concerns tasks and skills, not creating a new personality. Across thirty-seven studies, the bias-adjusted average performance association was small. It did not validate emotional surrender, thought-driven healing or a required three-repeat ritual.","Use rehearsal if your record shows a specific trigger blocking the same useful act. Name the cue and one response you control. Optionally picture it once, or write the line without imagery. Then use that response at a safe real opening. Preparation alone stays preparation. If the cue never occurs, record no occasion; you do not owe an invented success or a calmer feeling."],example:{title:"Leyla’s late-update question",text:"At 9:00, Leyla writes “What is still missing?” because late updates often pull her into a sharp reply. She briefly pictures asking it, then saves the noon conversation as her real action. The report is late. She asks the question and learns a detail is unresolved. She records the question, not a transformed personality or a smooth meeting."}},move:{invitation:"Keep your act; edit the late-update example.",instructions:["Name your real opening before saving; optional rehearsal remains preparation.","Use your saved response there; a writing act need not become a conversation."],prompts:[],suggestions:{action:["Ask the coordinator what is still missing","Write the volunteer update’s next factual sentence"],minimum:["Ask what is still missing","Write one factual volunteer update sentence"],cue:["When the volunteer update arrives late","When I open the unfinished volunteer update"],place:["In the volunteer coordinator’s message thread","At the kitchen writing table"],minutes:[2,1,3],fallback:["Use written “What is still missing?”","Choose the next suitable real opening"],observation:["Late update, actual question, and reply or silence","What happened after my response"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask the coordinator what is still missing",minimum:"Ask what is still missing",minutes:2,cueHint:"When the volunteer update arrives late",placeHint:"In the volunteer coordinator’s message thread",obstacleHint:"The trigger occurs before I remember the line",fallbackHint:"Use written “What is still missing?”",observationHint:"Late update, actual question, and reply or silence"},stopRule:"Pause if the setting is unsafe or distress grows. Choose protection, support or an outward anchor.",accessibleAlternative:"Name the actual response and opening before saving. Writing, signing and no imagery are valid."},result:{question:"Did you use the response at the real opening?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-6-decision",scenario:"Leyla knows her question and has a safe opening with the coordinator. The late update arrives; she feels annoyed.",question:"What fits this attempt?",options:[{id:"meditation-6-ideal",text:"Picture the whole discussion going smoothly before deciding whether to ask her question.",feedback:"A smooth scene can feel reassuring, but it avoids the cue already present. She has a usable question and safe opening; use it and record the response."},{id:"meditation-6-ask",text:"Notice the late update, then ask her prepared question before commenting further.",feedback:"This tests the actual response linked to the cue. Annoyance can remain. Rehearsal was preparation; asking and recording the reply supplies the real-life evidence."},{id:"meditation-6-rehearse",text:"Rehearse the question several more times so her delivery feels fully steady.",feedback:"More rehearsal may serve a genuine skill gap. In this case the question is ready; additional preparation could lose the opening. Ask once without requiring steady feelings."}],bestOptionId:"meditation-6-ask"}},carry:{takeaway:"Rehearse a behavior you can use, then record whether you used it.",followUp:{questionId:"meditation-6-return",question:"Did the cue appear, and did you use the response rather than only rehearse it?",observationPrompt:"What does your actual record show?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"Task rehearsal has a narrower evidence base",paragraphs:["Toth and colleagues’ institutional abstract reports thirty-seven studies of mental practice published from 1995 to 2018. The bias-adjusted performance association was small, r=.131. The abstract does not supply full methods, participant total, or a confidence interval. It also does not verify the older comparison or total number of effects. (meditation-M13)","This evidence concerns tasks and skills. It does not establish personality change, emotion release or healing, and does not test today’s particular cue, question or optional single rehearsal. Writing or imagining a response can be recorded as preparation. The later real response has its own occurrence and outcome. Keep them separate so a successful rehearsal never stands in for a conversation that did not happen. No particular emotional state or repetition count is required."]},{heading:"A response plan without an identity ritual",paragraphs:["Gollwitzer and Sheeran’s goal-planning review supports linking a recognizable situation to a feasible response across varied domains. It does not validate every combined rehearsal routine. “If the update is late, then I ask what is missing” specifies an act under your control; “be a calm leader” does not name one. The timing and wording here are ODA choices. (meditation-M05)","Dispenza’s publisher contents identify stages in a four-week package, but the book body was not inspected and controlled validation of that combined package was not identified. Planning and task-rehearsal findings cannot establish its surrender, quantum, genetic or healing claims. Treat a safe opening as a chance to test the line, rather than wait to feel changed. Use an observable response, allow feelings to remain, and review any consequence or repair that belongs to your actual behavior. Keep prescribed care. (meditation-M20)"]}],sourceIds:["meditation-M13","meditation-M05","meditation-M20"]}},{schemaVersion:2,revision:2,id:"meditation-7",courseId:"meditation",locale:"en",title:"Keep what survived a real day",goal:"Review your attention-and-action records, keep a workable version, and schedule the next attempt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Liked the lessons but lost the routine? Build next week from what you actually tried.",reason:{id:"meditation-7-reason",label:"What will you protect, shrink or stop next week?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep the library arrival cue","Shrink pause; keep the act","Stop distressing practice","No record; choose a first act"]},why:{id:"meditation-7-why",label:"What would this move make room for this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Repetition in a stable context can become more automatic, but habit timing varies. One observational study followed everyday behaviors, not meditation. Its modeled times do not establish a twenty-one-day or sixty-six-day deadline for your practice.","Review your same experiment: which cues occurred, which anchors were tolerable, and which useful acts actually followed? Keep a version supported by a record, or schedule a first trial if you have none. Plan three suitable opportunities next week as a course choice, not a required dose. Start with the next one; each gets its own record. Support, rest or stopping may be the appropriate decision."],example:{title:"Leyla keeps the workable cue",text:"On Sunday, Leyla checks three records. Kitchen practice happened once; library arrivals happened twice, each followed by an update sentence. She keeps the library cue and schedules Monday’s short version. On Monday she returns to a room sound and writes one sentence. It feels busy rather than peaceful. She records it and leaves later days unclaimed."}},move:{invitation:"Keep your act; edit the towel-folding example.",instructions:["Keep your saved action, minimum, cue and place; otherwise choose an example or first act.","Set the new start cue before saving a changed plan.","Log support, rest, or another act using its own minimum."],prompts:[],suggestions:{action:["Return to room sounds; fold one towel","Return; listen through one volunteer update"],minimum:["Fold one towel after one attention return","Listen until the speaker finishes one update"],cue:["After lunch dishes are put away","When the volunteer check-in begins"],place:["At the kitchen table","At the accessible volunteer meeting table"],minutes:[2,1,3],fallback:["Choose available cue; keep the tolerable anchor","Pause without scheduling another attempt"],observation:["Cue, attention return, and towel folded","Update heard; interruption or no interruption"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Return to room sounds; fold one towel",minimum:"Fold one towel after one attention return",minutes:2,cueHint:"After lunch dishes are put away",placeHint:"At the kitchen table",obstacleHint:"The after-lunch cue no longer fits my week",fallbackHint:"Choose available cue; keep the tolerable anchor",observationHint:"Cue, attention return, and towel folded"},stopRule:"Stop for distress, dizziness or detachment; seek qualified help for recurring concerns. Do not delay care.",accessibleAlternative:"Use outward, seated or nonmovement practice. Set a changed start cue before saving. For help, choose Adapt and Support; name the request and its minimum."},result:{question:"Did you try the next version or chosen support act?",observationPrompt:"What did you actually do, and what got in the way?"},judgment:{primary:{id:"meditation-7-decision",scenario:"Leyla’s records show crowded mornings and two workable library arrivals. She wants attention for the same update task next week.",question:"What fits this attempt?",options:[{id:"meditation-7-restore",text:"Protect longer morning sessions next week because the original routine deserves a fair trial.",feedback:"A longer trial might fit changed circumstances, but her records identify crowded mornings now. Use the observed library cue before increasing a plan that rarely happens."},{id:"meditation-7-rotate",text:"Choose a different technique each day to find one that renews her interest.",feedback:"Exploration can be useful, but her records already show a tolerable anchor and available cue. Changing everything would make the known bottleneck harder to evaluate."},{id:"meditation-7-keep",text:"Keep the library cue and tolerable anchor, then schedule her next useful sentence.",feedback:"This uses actual attempts to choose a feasible next version. Later opportunities remain plans until tried. Review each record without requiring calm or a perfect week."}],bestOptionId:"meditation-7-keep"}},carry:{takeaway:"Keep a workable return and useful act. Let your records guide the next week.",followUp:{questionId:"meditation-7-return",question:"What happened with your chosen act or support request, and what needs to change?",observationPrompt:"What was done, and what response or next step is still pending?",adjustmentPrompt:"What will you keep or change at the next cue?"}},goDeeper:{sections:[{heading:"A week is a review window",paragraphs:["Lally and colleagues followed ninety-six volunteers for eighty-four days as they repeated eating, drinking or activity behaviors in recurring contexts. Eighty-two supplied sufficient data; thirty-nine had acceptable automaticity models. Their estimated times varied widely and partly extended beyond the observation period. The median sixty-six-day estimate is a modeling result, not a habit-completion deadline or a meditation finding. (meditation-M14)","The observed omission analysis found no significant subsequent automaticity reduction after one missed opportunity, but omissions were not randomized. It cannot guarantee what every future miss means. ODA’s three suitable opportunities and weekly review are design choices. Use them to see whether the cue, size and setting fit your real life. A later date is not a completed attempt. Keep previous records intact when changing the next plan; a new minimum does not rewrite an earlier promise."]},{heading:"Stopping belongs in the continuing plan",paragraphs:["NCCIH advises against replacing medical care or delaying assessment and notes limited harm research. Farias and colleagues’ review combined eighty-three heterogeneous studies, including observational reports and experiments. Its pooled 8.3% adverse-event estimate is not a probability for your next brief app session; definitions, doses and ascertainment differed substantially. Difficult experiences are not proof that practice is working. (meditation-M03; meditation-M04)","Keep a stop route with whichever anchor you retain. Eyes-open, short, outward or seated choices are precautions, not guarantees. Recurring distress or concerns about detachment warrant qualified mental health support; a meditation teacher does not replace assessment. A plan for rest or a help request can serve your life better than another sit. The continuing experiment tests fit and a useful act, not symptom cure, constant calm, perfect attendance or an obligation to practice every technique."]}],sourceIds:["meditation-M14","meditation-M03","meditation-M04"]}}],R=[{id:"meditation-1",practice:["Sit safely for a chosen short time, such as one minute; a timer is optional.","Use ordinary breath sensations, an eyes-open sound or a visible object as your anchor.","When you notice wandering, return once; stop if distress, dizziness or detachment grows."],reflection:"Where did your attention wander most, and how did it feel to come back?",question:"If your attention keeps wandering during a sit, what does that mean?",options:["Meditation is not for me, and I should stop.","Noticing the wandering and coming back is the exercise itself.","I should push myself harder until my mind is completely empty."],correct:1,feedback:"Wandering is normal. In mindfulness meditation the goal is not a thought-free mind but the skill of noticing and gently coming back.",photo:{id:"1758273240112-c7724c9bb4a5",alt:"A young woman meditating with her eyes closed on the floor at home"}},{id:"meditation-2",practice:["Choose a comfortable seated or lying position and a feasible short duration; keep eyes open if preferred.","Optionally notice comfortable contact points, skip uncomfortable regions or use an outward anchor.","Name what you actually noticed, make a practical adjustment if useful, and stop if distress grows."],reflection:"Which part of your body felt new or surprising to notice?",question:"During a body scan, what do you do if you feel nothing in one area?",options:["I tense or move that area until I feel something.","I notice “no clear sensation here” and move on.","I assume I did it wrong and start again from the beginning."],correct:1,feedback:"Not noticing a clear sensation is an attentional observation, not a diagnosis of numbness. Do not force sensations; new or persistent concerning symptoms warrant medical assessment.",photo:{id:"1535987271305-c26a8935f74a",alt:"A woman lying on the grass in sunlight, resting"}},{id:"meditation-3",practice:["Choose an acceptable short word, sound, phrase or private prayer, if you want a verbal anchor.","Sit comfortably for a chosen short time; keep eyes open if preferred and breathing ordinary.","Return to your word when thoughts intrude, or stop or shift outward if discomfort grows."],reflection:"How did the word you chose feel, and will you use the same one tomorrow?",question:"In Benson’s method, what do you do when thoughts come in?",options:["I push the thought away and empty my head.","I stop the sit halfway; it means I cannot focus.","Without forcing, I notice the thought and return to my word."],correct:2,feedback:"The practitioner guidance describes returning without forcing. It does not require a particular phrase, breathing pattern or week of using one word; stop or adapt if distress grows.",photo:{id:"1513097847644-f00cfe868607",alt:"A woman sitting quietly on a wooden jetty in sunlight"}},{id:"meditation-4",practice:["Choose a safe familiar route, or use a seated, stationary contact alternative.","Keep eyes open, attend to hazards and breathe normally; comfortable step coordination is optional.","For a chosen short period, notice safe contact or surroundings; stop counting whenever safety requires attention."],reflection:"While walking slowly, what did you see or hear that you had not noticed before?",question:"In walking meditation, how is the number of steps decided?",options:["It is fixed for everyone: four steps per breath.","It is adjusted to your own breathing rhythm and pace.","The goal is to take as many steps as possible."],correct:1,feedback:"Optional step coordination follows a comfortable natural rhythm. Keep eyes open and surroundings first; no fixed ratio or isolated health effect is established by this practice guidance.",photo:{id:"1477332552946-cfb384aeaf1c",alt:"A woman walking slowly along a sunny path"}},{id:"meditation-5",practice:["Choose acceptable short wishes for yourself or a safe loved person; the wording is an ODA adaptation.","Offer wishes voluntarily, without requiring warmth; skip recipients or use an outward anchor if uncomfortable.","A difficult recipient is optional and never necessary. Stop if distressed; keep boundaries and avoid unsafe contact."],reflection:"To whom was it easiest, and to whom hardest, to direct your good wishes?",question:"What do you do if you feel no warm emotion during metta?",options:["I decide the method does not fit me and choose to stop.","I try to force the feeling to appear.","If it feels tolerable, I can continue voluntarily without requiring warm feelings."],correct:2,feedback:"Warmth is not required for a voluntary wish. Continuing through distress is not required either. You can change recipients, use outward attention or stop; wishes do not require forgiveness or contact.",photo:{id:"1604881991720-f91add269bed",alt:"Two people holding hands kindly across a table"}},{id:"meditation-6",practice:["Name a specific recurring cue, the thought that appears and the behavior you want to change.","Optionally write or imagine one feasible response in a safe scene; this is preparation, not personality change.","Choose the real response and its cue: “If this happens, then I will do this.” Record the real attempt separately."],reflection:"In the moment your old state switches on, what would the person you want to be do differently?",question:"Which part of this technique is best supported by research?",options:["Changing events and reality through the quantum field.","Rehearsing the behavior you want in your mind and then trying it in real life.","Healing illness with thought so that medication is no longer needed."],correct:1,feedback:"Research concerns small average task and skill performance benefits, not a new-self ritual or an established advantage from adding a real-life attempt. Keep care; quantum and healing claims are unsupported.",photo:{id:"1631832293782-2eda7804489b",alt:"A quiet room with morning sun streaming through the window and a potted plant in front of it"}},{id:"meditation-7",practice:["Choose a recognizable cue and safe place for a practice that fits your life.","Choose a tolerable short version and schedule its next opportunity; log later attempts only after they occur.","Write a feasible outward, seated or nonmovement backup, including stopping and support when needed."],reflection:"Which technique in this course helped you most, and why?",question:"If your distress clearly grows during meditation and old memories shake you, what should you do?",options:["I stop, open my eyes, feel my feet and get support from a professional.","I sit longer and wait for these feelings to pass on their own.","I take it as a sign the meditation is going well and keep pushing."],correct:0,feedback:"Difficult experiences can occur, but a pooled review percentage is not your brief-session risk. Stop if distress grows and seek qualified support for recurring concerns. Do not delay care or emergency help.",photo:{id:"1781255575628-d645cc39160f",alt:"A simple corner with colorful floor cushions and woven poufs on a wooden floor"}}],H={id:"meditation",title:"Mind keeps wandering? Return to what matters",subtitle:"Seven short lessons. Test a comfortable anchor, then use attention in a task or conversation.",description:"Build one voluntary attention experiment around a useful act in your own life. Try another anchor only when it addresses a real difficulty, review what happened and keep a workable version.",scope:"Meditation education for adults; it is not diagnosis or treatment and does not replace therapy or medication. Do not change prescribed care without your clinician. For trauma, psychosis or severe distress, plan with a qualified mental health professional; a teacher does not replace assessment. Keep eyes open, choose an outward anchor or pause when needed. Stop if distress, dizziness or detachment grows; seek support for persistent, recurring or concerning symptoms. Do not practice while driving. Seek medical assessment for new or persistent pain, numbness or other concerning symptoms. Self-harm thoughts warrant prompt professional or crisis support; immediate danger requires local emergency help.",outcome:"A chosen attention-and-action plan, honest attempt records, and a workable next week with clear stop and support routes.",photo:{id:"1522075782449-e45a34f1ddfb",alt:"A woman sitting quietly on a bench looking out over a mountain view"},lessons:u.map((e,t)=>({...R[t],schemaVersion:2,v2:e,title:e.title,goal:e.goal,minutes:e.minutes.learning,reading:e.idea.paragraphs,example:e.idea.example,deeper:e.goDeeper.sections,sources:[...new Set([...e.goDeeper.sourceIds,"meditation-M03"])],takeaway:e.carry.takeaway,visual:{kind:"steps",title:"One continuing experiment",steps:[{label:"Cue",text:"Choose a workable opening."},{label:"Act",text:"Try the useful minimum."},{label:"Return",text:"Record and choose the next attempt."}]}}))},z=Object.freeze(Object.defineProperty({__proto__:null,COURSE:H,MEDITATION_LESSONS_V2:u,SOURCES:D},Symbol.toStringTag,{value:"Module"})),C=[{id:"identity-gollwitzer",title:"I01 · Gollwitzer & Sheeran · 2006 · If-then plans and goal attainment",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"Across 94 independent tests involving 8,461 participants, if-then plans improved goal attainment on average (d = 0.65).",limitation:"83 experimental and 11 correlational tests covered varied goals and methods. This does not validate a branded habit package or the exact ODA plan."},{id:"identity-harkin",title:"I02 · Harkin et al. · 2016 · Monitoring goal progress",url:"https://doi.org/10.1037/bul0000025",type:"research",finding:"Across 138 randomized studies, monitoring interventions improved goal attainment on average (d = 0.40). A bias-adjusted estimate was smaller (d = 0.19).",limitation:"Goals and recording methods varied. Moderator findings do not require public disclosure. This receipt and next-day review were not tested."},{id:"identity-cole",title:"I03 · Cole et al. · 2021 · Mental simulation and behavior change",url:"https://doi.org/10.3758/s13423-021-01880-6",type:"research",finding:"Across 94 randomized studies, mental simulation had an average behavioral effect (g = 0.49). The overall comparison between simulation subtypes was not significant.",limitation:"Most samples were students; reporting and subgroup sizes limit certainty. This does not establish a winning imagery subtype or an identity meditation effect."},{id:"identity-lally",title:"I04 · Lally et al. · 2010 · How are habits formed?",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"In 39 good-fitting models, estimated time to 95% of the automaticity plateau had a median of 66 days and range of 18-254 days.",limitation:"96 volunteers entered; behavior was observed for 84 days. Longer estimates were extrapolated. This was not an identity-change deadline or a test of a two-day-gap rule."},{id:"identity-habit-times",title:"I05 · Singh et al. · 2024 · Habit formation review",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"A review of 20 health-behavior studies found wide variation in habit formation. Only four studies reported formation times.",limitation:"11 studies had high risk of bias. Pre/post habit-score improvement is not a randomized causal effect. No universal formation deadline is supported."},{id:"identity-wood-runger",title:"I06 · Wood & Rünger · 2016 · Psychology of habit",url:"https://doi.org/10.1146/annurev-psych-122414-033417",type:"research",finding:"The review describes habits developing through repeated responses in recurring contexts. Habitual and deliberate processes can operate together.",limitation:"A narrative review, with no pooled effect. It does not classify every mood or thought as a habit, or prove that changing context always beats effort."},{id:"identity-wood-everyday",title:"I07 · Wood, Quinn & Kashy · 2002 · Habits in everyday life",url:"https://doi.org/10.1037/0022-3514.83.6.1281",type:"research",finding:"In two student diary samples, 35% and 43% of reported behaviors met an almost-daily, same-location habit definition.",limitation:"The samples contained 70 and 209 students. These percentages are not population estimates or mind-wandering prevalence. Diary assessment did not test an identity intervention."},{id:"identity-lieberman",title:"I10 · Lieberman et al. · 2007 · Putting feelings into words",url:"https://doi.org/10.1111/j.1467-9280.2007.01916.x",type:"research",finding:"In 30 adults viewing faces, emotion-word labeling produced lower amygdala activation than gender-name labeling.",limitation:"A small laboratory brain-imaging study, not a measure of everyday emotional recovery. It does not establish that naming your own distress makes it smaller."},{id:"identity-breines",title:"I11 · Breines & Chen · 2012 · Self-compassion and improvement motivation",url:"https://doi.org/10.1177/0146167212445599",type:"research",finding:"Four short experiments found support for immediate improvement motivation after compassionate responses. One experiment found more study time than a no-intervention condition.",limitation:"Mainly student and online samples; effects differed by comparison. Test scores did not significantly differ in that study. Lasting identity change was not established."},{id:"identity-clear-identity",title:"I15 · James Clear · Identity-based habits",url:"https://jamesclear.com/identity-based-habits",type:"technique",finding:"Clear frames small actions as evidence for a desired identity. The action-as-vote idea is a practitioner metaphor.",limitation:"The author article is not a trial, and its publication year was not established. Identity-first superiority and the never-miss-twice rule are not verified scientific laws."},{id:"identity-task-belief",title:"I17 · Bandura · 1977 · Self-efficacy theory",url:"https://doi.org/10.1037/0033-295X.84.2.191",type:"research",finding:"The framework describes perceived capability for a specific task, informed by mastery, observing others, persuasion, and physiological information.",limitation:"A theoretical synthesis, not a pooled intervention estimate. Capability beliefs do not measure personal worth or verify an identity-vote method."},{id:"identity-activity-identity",title:"I19 · Rhodes et al. · 2025 · Physical-activity identity interventions",url:"https://doi.org/10.1080/17437199.2024.2412996",type:"research",finding:"Across 40 experimental or quasi-experimental effects involving 4,939 adults, physical-activity identity changed a little on average (g = 0.18).",limitation:"Behavior effects came from a different 30-effect subsample and were heterogeneous. The review does not establish that identity caused behavior change or generalize to whole-person transformation."},{id:"identity-motor-rehearsal",title:"I18 · Toth et al. · 2020 · Mental practice and task performance",url:"https://doi.org/10.1016/j.psychsport.2020.101672",type:"research",finding:"The review of 37 studies reported a small bias-adjusted mental-practice effect on motor or task performance (r = .131).",limitation:"The opened abstract did not establish participant total or confidence interval. Motor-task evidence does not demonstrate identity change, healing, or emotional biology effects."}],p={schemaVersion:2,revision:2,id:"identity-1",courseId:"identity",locale:"en",title:"Still scrolling? Find your changeable moment",goal:"Choose one recurring cue and try a useful response that serves your week.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Another afternoon lost to the same distraction? Find one moment you can change.",reason:{id:"identity-1-reason",label:"What does this pattern protect now and postpone later?",kind:"text",maxLength:160,optional:!0,suggestions:["Finish work without another late evening","Make room for my creative work","Give people my attention"]},why:{id:"identity-1-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A familiar setting can cue a familiar action, even after your priorities change. Habit research separates that repeated response from your whole personality. “After lunch, I scroll before starting” names a pattern. “I am lazy” gives you no moment to work with.","Choose one ordinary cue and one useful alternative. Notice what the old response offers now and what it postpones. Then try the alternative once. This course keeps improving that same experiment. You can start with a small act without rejecting who you are or promising a new personality."],example:{title:"Leyla's first report sentence",text:"At 1:30, Leyla returns to her desk and reaches for her phone before writing a report. She wants fewer late evenings. She puts the phone aside and writes one rough opening sentence instead. The wording is awkward, and she later scrolls again. Her record says what she did at the cue, without calling the afternoon a transformation."}},move:{invitation:"Choose one familiar cue. Try a response that does something useful for your chosen direction.",instructions:["Name the cue and the actual behavior you will try.","Record what you did when that cue appeared."],prompts:[],suggestions:{action:["Write one usable sentence","Ask one attentive question","Complete one small practical step"],minimum:["Add one sentence to my draft","Listen to one full answer","Finish one useful part"],cue:["When I return after lunch","When I put my bag down","At my usual evening start"],place:["At my usual work surface","In our safe conversation space"],fallback:["Dictate the sentence instead","Use my next available cue","Ask for practical assistance"],observation:["Whether I wrote the sentence","What I did at the cue","What the old response postponed"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one usable sentence",minimum:"Add one sentence to my draft",minutes:2,cueHint:"When I return after lunch",placeHint:"At my usual work surface",obstacleHint:"The familiar distraction is easier to reach.",fallbackHint:"Dictate the sentence instead",observationHint:"Whether I wrote the sentence"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-1-decision",scenario:"Leyla planned to write after lunch but scrolled. She has five minutes and the report open.",question:"Which move starts a useful experiment?",options:[{id:"identity-1-redesign-day",text:"Build a stricter afternoon schedule, then begin the report once the new schedule is complete.",feedback:"A schedule may help later. Right now it adds preparation before an available attempt. Name the lunch cue, write one useful sentence, and record what gets in the way."},{id:"identity-1-test-cue",text:"Name what happened after lunch, then write one report sentence and record the cue.",feedback:"This tests a response in the real setting. The sentence does useful work, and the note identifies the cue. One attempt provides information without proving a whole personality change."},{id:"identity-1-change-break",text:"Move tomorrow’s writing before lunch and use today’s remaining five minutes to review the new plan.",feedback:"Changing a cue can help if lunch timing is the problem. Here an actual five-minute attempt is still available. Test one sentence and record the cue before deciding that a new schedule fits better."}],bestOptionId:"identity-1-test-cue"}},carry:{takeaway:"Change one response in one setting. Let the record describe what happened.",followUp:{questionId:"identity-1-return",question:"When your chosen cue appeared, what did you do instead of the familiar response?",observationPrompt:"Name your response at the cue, or note that the cue never occurred.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"A pattern is smaller than a person",paragraphs:["Wood and Rünger’s review describes habits as repeated responses associated with recurring contexts [I06]. A setting can call up a familiar response alongside deliberate choices. That is a narrower claim than saying every thought, mood, or difficult day is an automatic program. This lesson asks about one observable behavior, not an “old self” that must be removed.","The diary research used student samples of 70 and 209 people [I07]. Respectively, 35% and 43% of their reports met an almost-daily, same-location definition of habit. Those figures do not describe all adults, and they are not percentages of time spent mind-wandering. Sampling behavior was assessment, not a demonstrated identity treatment.","ODA’s cue-and-response note is a teaching adaptation. Keep only the detail useful for your next choice. An unchanged mood or imperfect afternoon does not invalidate an accurately reported attempt."]},{heading:"Make the alternative consequential",paragraphs:["Gollwitzer and Sheeran’s review combined 94 independent tests involving 8,461 participants [I01]. It found an average goal-attainment benefit from specific if-then plans. The evidence included 83 experimental and 11 correlational tests, with varied goals and methods. It does not establish that this particular ODA sequence changes identity.","For this experiment, connect a recognizable event with a feasible response: when you return after lunch, write one useful report sentence. Specify a cue you actually encounter. Choose an alternative that contributes to your direction, rather than simply opening an app or arranging supplies. Those may be preparation, but the practice should be named accurately.","There is no requirement to interrupt every familiar behavior. Keep routines that serve your life. If the setting calls for safety, rest, or assistance, choose that response deliberately. Review this one attempt before adding another system."]}],sourceIds:["identity-wood-runger","identity-wood-everyday","identity-gollwitzer"]}},m={schemaVersion:2,revision:2,id:"identity-2",courseId:"identity",locale:"en",title:"Worry still here? Choose your response anyway",goal:"Use your same cue to do the useful action while an ordinary feeling remains.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Waiting for worry to leave before you start? Give your chosen action a safe chance.",reason:{id:"identity-2-reason",label:"What is waiting for this feeling costing your direction?",kind:"text",maxLength:160,optional:!0,suggestions:["Start while ordinary worry remains","Protect an evening I value","Respond without hiding my needs"]},why:{id:"identity-2-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bring back your cue and action. A familiar feeling is something to notice, not proof of a fixed personality. Naming feelings has a narrow research basis: one small study found a changed brain response when people labeled emotions on faces. It did not test whether your own worry disappears.","Use a label as a description: “Worry is here.” Check whether it points to a real need, then choose your response. You may write your sentence while worried, or seek help if the concern needs action. The useful act counts without a calmer feeling afterward."],example:{title:"Leyla's worried start",text:"After lunch on Thursday, Leyla feels worried about the same report. She checks that she has the required figures, names the worry, and writes her next usable sentence. She still wants to recheck everything. She records the sentence and that the worry stayed. She has practiced writing, not proved that the feeling is a habit."}},move:{invitation:"Keep your experiment. Name an ordinary feeling if useful, then do the chosen response.",instructions:["Check for a real problem before treating this as ordinary worry.","Let the feeling remain while you try."],prompts:[],suggestions:{action:["Write my next usable sentence","Listen while ordinary guilt remains","Ask for the help I need"],minimum:["Add one sentence to my draft","Ask one attentive question","Send one practical help request"],cue:["When worry appears at my cue","After checking the urgent need","At my next safe opening"],place:["At my usual work surface","In a safe shared space"],fallback:["Dictate one useful sentence","Address the real problem first","Choose support instead"],observation:["Whether I acted while worry remained","Whether there was a real unmet need","The actual request or response"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write my next usable sentence",minimum:"Add one sentence to my draft",minutes:2,cueHint:"When worry appears at my cue",placeHint:"At my usual work surface",obstacleHint:"I want the feeling to disappear before acting.",fallbackHint:"Dictate one useful sentence",observationHint:"Whether I acted while worry remained"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-2-decision",scenario:"Leyla has five minutes. Her figures match the approved table, and her sentence makes no new calculation. She still feels worried.",question:"Which response fits this moment?",options:[{id:"identity-2-recheck",text:"Recheck the figures once more so she can feel more certain before writing the sentence.",feedback:"Another check can help when information is missing. The needed figures are already checked here. Rechecking postpones the available writing attempt without making a calmer feeling a reliable starting cue."},{id:"identity-2-provisional-check",text:"Draft a provisional sentence and ask a colleague to verify its figure before keeping the line in the report.",feedback:"A provisional line and second check help when a figure is uncertain. Here the approved table already supports the sentence. Requiring another reply delays keeping a usable line without addressing a known gap."},{id:"identity-2-act-with-feeling",text:"Name the worry, write one usable sentence, and record whether the concern needed further action.",feedback:"This preserves the feeling and checks its meaning without giving it an automatic veto. The sentence is the practice. If a real concern appears, her next response can be practical help."}],bestOptionId:"identity-2-act-with-feeling"}},carry:{takeaway:"A feeling can remain while you choose a useful, safe response.",followUp:{questionId:"identity-2-return",question:"Did the feeling remain during your action, and did it point to a real unmet need?",observationPrompt:"Name any feeling that remained and any need it revealed, or note no clear need.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"What labeling actually measured",paragraphs:["Lieberman and colleagues studied 30 healthy adults looking at emotional faces in a brain scanner [I10]. Choosing an emotion word produced lower amygdala activation than choosing a gender-matched name. That is a difference in a laboratory brain measure, not a finding that naming your own distress makes it smaller or improves mood for weeks.","ODA uses a short feeling label as optional description. The study did not test this cue, your chosen behavior, or a course about identity. Skip labeling if it adds nothing, and avoid turning every emotion into something you must correct. Grief, anger about unfairness, and fear in danger can deserve a different response.","Bring the observation back to the same action. Did you do it, did you need assistance, or did a real problem change the plan? A record can hold a difficult feeling and a useful behavior without claiming one caused the other."]},{heading:"Support without removing accountability",paragraphs:["Breines and Chen tested compassionate responses in four short experiments, mainly with student or online samples [I11]. Some outcomes supported immediate improvement motivation. In one study, participants spent more time studying after a difficult test than those receiving no intervention. Their later test scores did not significantly differ, and comparison with a self-esteem condition was only marginal.","That evidence does not prove lasting identity change or universal superiority of kindness. It does challenge the assumption that a harsh response is always needed before trying again. This lesson’s instruction to describe a feeling and continue a chosen action is an ODA adaptation, not the tested compassionate-writing procedure.","Use a fair response that keeps responsibility visible. A missing skill calls for learning; an unmet need may call for help. You can act without insulting yourself and can pause without calling the pause a failed personality."]}],sourceIds:["identity-lieberman","identity-breines"]}},g={schemaVersion:2,revision:2,id:"identity-3",courseId:"identity",locale:"en",title:"Caught yourself late? Make the next move useful",goal:"Return to your chosen action after a distraction, or repair a response that caused harm.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Already scrolling or already snapped? The next sentence can still do useful work.",reason:{id:"identity-3-reason",label:"What needs a return or repair in this same experiment?",kind:"text",maxLength:160,optional:!0,suggestions:["Return before the afternoon disappears","Repair a sharp response","Keep my useful action available"]},why:{id:"identity-3-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Noticing a distraction is different from returning. Keep your chosen cue and action. Add a late-catch response: “If I notice I have drifted, I will do my useful minimum.” Specific cue-and-action plans have improved goal attainment on average in research.","If your response hurt someone, a private catch is not the repair. In a safe setting, acknowledge your part and restart one sentence. If nobody was harmed, return to the task. Record the response, not just notices. You can change the next act without declaring the day ruined."],example:{title:"Leyla's late catch",text:"At 1:42, Leyla notices she has spent twelve minutes scrolling instead of writing. She closes the feed and adds one useful sentence to her report. Later she notices an abrupt message she sent her colleague. She sends a brief correction of her tone. Neither act erases the lost time, but both are specific responses she can record."}},move:{invitation:"Keep your action. Choose what you will do when you notice the pattern late.",instructions:["Return to the useful minimum, or repair your own harmful response.","Record what followed the catch."],prompts:[],suggestions:{action:["Return to my useful sentence","Restart one sentence respectfully","Repair my own sharp message"],minimum:["Add one useful sentence now","Acknowledge and restate one sentence","Send one clear repair message"],cue:["When I notice I am scrolling","When I hear my sharp tone","After a safe interruption ends"],place:["At my usual work surface","In the safe message thread"],fallback:["Use a shorter useful sentence","Choose a safer repair channel","Ask for help restarting"],observation:["What I did after noticing","Whether I made the actual repair","Where I noticed the pattern"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Return to my useful sentence",minimum:"Add one useful sentence now",minutes:2,cueHint:"When I notice I am scrolling",placeHint:"At my usual work surface",obstacleHint:"I notice only after the distraction has started.",fallbackHint:"Use a shorter useful sentence",observationHint:"What I did after noticing"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-3-decision",scenario:"During a safe discussion, Leyla snaps at a colleague. She notices her tone while they are still talking.",question:"What best completes the interruption?",options:[{id:"identity-3-repair",text:"Acknowledge the sharp sentence and restate her point respectfully while the conversation is still open.",feedback:"This makes the catch consequential. Leyla takes responsibility for her own tone and practices a different response. The colleague does not have to forgive her for the repair attempt to be real."},{id:"identity-3-private-catch",text:"Pause privately and record the catch, then focus on speaking more patiently in their next discussion.",feedback:"Noticing provides information, but the sharp sentence has already affected this conversation. Where repair is safe and appropriate, a brief acknowledgment and restatement address the current effect rather than only tomorrow’s behavior."},{id:"identity-3-full-explanation",text:"Explain why the deadline pressure caused her tone, then return to the work discussion without revisiting it.",feedback:"Context may explain the strain and may need changing. It does not replace a repair for her own response. Acknowledge the tone first, then discuss workload without making agreement a condition."}],bestOptionId:"identity-3-repair"}},carry:{takeaway:"A catch becomes useful when you return, repair, or choose a safer response.",followUp:{questionId:"identity-3-return",question:"When did you notice the pattern, and what actual return or repair followed?",observationPrompt:"Note when you noticed, then any return, repair, protection, or no occasion.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"A cue can include late noticing",paragraphs:["Implementation intentions connect a specific situation with a chosen response. Gollwitzer and Sheeran’s synthesis found an average benefit for goal attainment across 94 independent tests [I01]. Goals, delivery, and study methods varied. It does not validate a particular pause word, breathing sequence, or number of daily catches.","This lesson adds late noticing as another possible situation: if you notice scrolling has begun, write your chosen useful sentence. The response is still the same course experiment. A silent cue word is optional shorthand, not the active behavior you are trying to build. No breath or calm feeling is required before returning.","Wood and Rünger describe habits operating alongside deliberate processes [I06]. That leaves room for an intentional response within an imperfect routine. It does not mean every distraction was a habit. Describe what you observed and test whether this cue is recognizable in your actual setting."]},{heading:"Notice, then respond to the consequence",paragraphs:["A record should distinguish noticing, returning, and repairing. Harkin and colleagues reviewed 138 randomized progress-monitoring studies [I02]. Monitoring interventions improved goal attainment on average, though a bias-adjusted estimate was smaller. The review does not establish that counting catches alone changes your relationships or that every private note needs to be shared.","For this ODA adaptation, record the behavior that followed your notice. “I caught my sharp tone” and “I acknowledged it and restated my request” are different facts. If your original task was interrupted, record the useful part you resumed. If you caused no harm, an apology is not required.","Protection takes priority in an unsafe relationship. You do not owe contact, forgiveness, or an explanation to someone who threatens you. Choose a boundary or support step when it fits. Keep those acts named accurately rather than treating every pause as successful repair."]}],sourceIds:["identity-gollwitzer","identity-wood-runger","identity-harkin"]}},f={schemaVersion:2,revision:2,id:"identity-4",courseId:"identity",locale:"en",title:"Busy preparing? Make your next action real proof",goal:"Check that your minimum practices the behavior your direction needs, then do it once.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Another polished plan, still no draft? Make one useful action the evidence.",reason:{id:"identity-4-reason",label:"Is this minimum building the skill or postponing it?",kind:"text",maxLength:160,optional:!0,suggestions:["Practice the work itself","Keep the minimum meaningful","Describe only what I actually did"]},why:{id:"identity-4-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bring back your last attempt. James Clear calls actions “votes” for an identity. That is a metaphor, not a scientific law. You can use it without saying your identity must change first. The useful question is whether this action practices something your direction needs.","Opening a draft proves you opened it. Writing one usable sentence proves you wrote. Both can have a purpose, but name preparation as preparation. Keep the minimum small enough for your week and substantial enough to matter. After an actual attempt, describe only that evidence. “I wrote a sentence” needs no claim about permanent confidence."],example:{title:"Leyla's useful minimum",text:"On Friday, Leyla spends five minutes arranging headings but has written no report text. She checks her experiment and changes the minimum to one usable sentence under a heading. She writes it before stopping. The sentence needs editing. Her optional note says, “I wrote a sentence today,” rather than “I am now a disciplined person.”"}},move:{invitation:"Check your saved minimum. If it only prepares, name that honestly or choose actual practice.",instructions:["Do one useful unit of the behavior your direction needs.","Afterward, describe only the action you actually completed."],prompts:[],suggestions:{action:["Write one usable report sentence","Practice one actual skill attempt","Use one respectful repair sentence"],minimum:["Add one usable sentence","Complete one real practice attempt","Make one actual repair"],cue:["When I open my existing draft","At my next practice cue","When a safe repair is possible"],place:["In my actual draft","At the usual practice location"],fallback:["Dictate a usable sentence","Shrink the actual practice unit","Record preparation as preparation"],observation:["The actual behavior completed","Whether the minimum served my direction","What preparation still remains"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one usable report sentence",minimum:"Add one usable sentence",minutes:2,cueHint:"When I open my existing draft",placeHint:"In my actual draft",obstacleHint:"Preparation feels easier than the actual behavior.",fallbackHint:"Dictate a usable sentence",observationHint:"The actual behavior completed"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-4-decision",scenario:"Leyla has five tired minutes and wants report text. Her headings are ready; the next sentence's figure already matches its source.",question:"Which minimum does useful work now?",options:[{id:"identity-4-organize",text:"Arrange the notes into a clearer folder so tomorrow’s writing session starts with less friction.",feedback:"Organization can support later writing. Here the notes and headings are already ready, so more setup delays the skill Leyla wants to practice. Name it as preparation if she chooses it."},{id:"identity-4-write-unit",text:"Write one rough sentence in the real report, then decide whether stopping fits her capacity.",feedback:"This minimum practices the desired behavior and respects the time available. It proves one sentence was written, not that her identity changed. She can stop without making the sentence impressive."},{id:"identity-4-verify-support",text:"Recheck the cited figure against its source, then leave a verified note for tomorrow's sentence.",feedback:"Verification is useful when factual support is uncertain. This figure has already been checked, so repeating that preparation uses tonight's writing time. One rough supported sentence would advance the report now."}],bestOptionId:"identity-4-write-unit"}},carry:{takeaway:"Let your evidence name the behavior. Keep preparation and practice distinct.",followUp:{questionId:"identity-4-return",question:"What did your minimum actually demonstrate, and was it useful for your chosen direction?",observationPrompt:"Name the behavior your minimum demonstrated and whether it helped your direction.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"An identity metaphor has limits",paragraphs:["Clear’s author article presents a desired identity and small supporting actions as a practitioner framework [I15]. It is not a controlled trial proving identity-first change is required or superior. The familiar action-as-vote framing can be memorable without becoming a scientific explanation.","Bandura’s self-efficacy framework concerns perceived capability for a particular task [I17]. Mastery experiences are one source of that belief, alongside observation, persuasion, and physiological information. The framework does not turn one action into a measure of your worth or a verdict about your whole personality.","ODA’s optional evidence statement stays narrow: “I added a usable sentence” or “I made my request.” An untried plan and a correct quiz answer do not establish those behaviors. You may leave identity language out entirely while continuing the same practical experiment."]},{heading:"Behavior and identity are different outcomes",paragraphs:["Rhodes and colleagues reviewed 40 experimental or quasi-experimental effects involving 4,939 adults [I19]. Physical-activity identity changed a little on average, with an effect of g = 0.18. A 30-effect behavior subsample showed a larger average activity effect, but the samples and outcomes differ. Those numbers do not prove identity caused behavior change.","The studies concern physical activity, with heterogeneous results and possible publication bias. They do not validate broad personality transformation, Clear’s vote method, or this report-writing experiment. Difficulty also does not automatically show that a goal matters enough to pursue. It can reveal a missing skill, insufficient resources, or a need to revise the plan.","Use the record to decide what your minimum contributes. Keep a small unit when it fits capacity, increase it only by choice, or change an unsuitable goal. The aim is useful practice in your life, not collecting symbolic votes."]}],sourceIds:["identity-clear-identity","identity-task-belief","identity-activity-identity"]}},y={schemaVersion:2,revision:2,id:"identity-5",courseId:"identity",locale:"en",title:"Rehearsed enough? Give the real moment a chance",goal:"Use optional brief preparation to address one obstacle, then attempt your same real action.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"If imagining the perfect start keeps replacing the real start, finish preparation with an attempt.",reason:{id:"identity-5-reason",label:"What obstacle would brief rehearsal help you meet?",kind:"text",maxLength:160,optional:!0,suggestions:["Prepare for the actual opening","Try before delivery feels perfect","Keep rehearsal separate from action"]},why:{id:"identity-5-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Rehearsal is preparation, not the action itself. Research on imagining behavior found an average behavioral benefit, but no clear winning type of imagery. It does not prove that imagining the steps beats imagining the outcome, or that a timed identity meditation changes personality.","Use rehearsal if your record shows a preparation gap. Describe or imagine the first step and a likely obstacle. Then try your action at its real cue. If imagery is uncomfortable or unavailable, use words or skip it. Record preparation separately. The attempt can stay awkward, and its outcome remains uncertain."],example:{title:"Leyla's imperfect first line",text:"Before Monday’s report session, Leyla describes how she will start: read her last line, then add one sentence even if it sounds clumsy. She rehearses the transition briefly, with eyes open. At her lunch cue, she adds the sentence. It is less fluent than she imagined. She records the real line separately from the preparation."}},move:{invitation:"If preparation would help, keep it brief. Save the real action as your practice.",instructions:["Rehearse the first useful step only if needed.","Try it at your actual cue; record preparation separately."],prompts:[],suggestions:{action:["Add my next real draft sentence","Use my prepared response once","Complete my chosen practice unit"],minimum:["Write one sentence in the draft","Use one response at the cue","Finish one actual practice unit"],cue:["After lunch when I start writing","At the opening I rehearsed","When my usual cue appears"],place:["In my actual draft","At my usual safe action setting"],fallback:["Skip rehearsal and write one usable sentence","Use words, then try at lunch","Request help with the missing skill"],observation:["What happened in the actual attempt","Whether the expected obstacle appeared","What was only preparation"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Add my next real draft sentence",minimum:"Write one sentence in the draft",minutes:2,cueHint:"After lunch when I start writing",placeHint:"In my actual draft",obstacleHint:"I keep rehearsing instead of starting the actual action.",fallbackHint:"Skip rehearsal and write one usable sentence",observationHint:"What happened in the actual attempt"},stopRule:"Skip trauma scenes. Stop distressing imagery; use words, support, or a safe direct attempt.",accessibleAlternative:"Keep eyes open or skip imagery. For words-only preparation, choose Adapt and name the real-use cue."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-5-decision",scenario:"Leyla knows her first report point and how to enter it. She has ten minutes. Rehearsing a confident session delayed her last two starts.",question:"What best connects preparation with practice?",options:[{id:"identity-5-direct-attempt",text:"Skip further rehearsal, add one sentence at her report cue, and record where starting was actually difficult.",feedback:"Her record identifies expanding rehearsal, not an unclear first step. Trying the known sentence addresses that obstacle. Record any difficulty the real attempt reveals before deciding whether a specific preparation would help."},{id:"identity-5-timed-process",text:"Spend two minutes rehearsing a smooth start, then write one report sentence before the session ends.",feedback:"A timed rehearsal gives preparation an endpoint and may clarify an unfamiliar step. Leyla already knows this step, and rehearsal has delayed two starts. Direct practice tests the problem her record actually identifies."},{id:"identity-5-timed-outcome",text:"Imagine finishing the report for one minute, then write one sentence and record what helped her start.",feedback:"This includes a real attempt, and research establishes no winning imagery subtype. But no motivation gap is identified here. Skipping more imagery responds more directly to Leyla's repeated preparation delay."}],bestOptionId:"identity-5-direct-attempt"}},carry:{takeaway:"Useful rehearsal has an endpoint and a real opportunity beyond it.",followUp:{questionId:"identity-5-return",question:"What differed between your preparation and the actual attempt at your cue?",observationPrompt:"Compare what you prepared with what happened at the cue; skipped preparation is valid.",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"No established winning imagery subtype",paragraphs:["Cole and colleagues combined 94 randomized studies, 123 effects, and 5,685 participants [I03]. Mental simulation had an overall behavioral effect of g = 0.49. Some subtype estimates were numerically larger than others, but the overall subtype comparison was not significant. The process-only subgroup contained just five effects and was uncertain.","Most samples were students, and many studies reported limited information about bias. The review does not establish a superior imagery subtype, an advantage from longer practice, or identity change from a ten-minute meditation. This lesson’s brief preparation is a chosen design, not the reviewed protocol.","Choose words, imagery, or no rehearsal according to the actual preparation gap. A description of a useful first step can be easier to inspect than a perfect future scene. The course record should still ask what happened when that step met the real setting."]},{heading:"Prepare the task you will actually do",paragraphs:["Toth and colleagues’ review of 37 studies concerned motor and task performance [I18]. It reported a small bias-adjusted mental-practice effect, r = .131. Motor-task evidence does not establish changed emotional biology, illness recovery, or whole-person identity change. Rehearsal can support a task without replacing instruction, materials, or real practice.","Specific if-then planning has broader goal-attainment support across varied tests [I01]. For this ODA experiment, connect a real cue with the action you already chose, and use rehearsal only to make the response clearer. Preparing your first report sentence and writing it remain different behaviors. Do not infer one from the other.","Skip scenes involving trauma or distressing memories. You can keep your eyes open, describe the steps without pictures, use assistance, or proceed directly to a safe attempt. If preparation keeps expanding, shrink it rather than requiring another morning ritual."]}],sourceIds:["identity-cole","identity-motor-rehearsal","identity-gollwitzer"]}},b={schemaVersion:2,revision:2,id:"identity-6",courseId:"identity",locale:"en",title:"Your cue keeps failing? Change one condition",goal:"Use your records to adjust one cue or material, then test the same useful action.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"A beautiful routine is useless when its cue never happens. Test one condition today.",reason:{id:"identity-6-reason",label:"Which convenience will you change to give this action room?",kind:"text",maxLength:160,optional:!0,suggestions:["Use a cue that actually occurs","Keep the needed material nearby","Protect urgent contact while reducing distraction"]},why:{id:"identity-6-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bring back your attempts. Did the cue occur? Were materials available? A specific plan can fail when its assumed situation never happens. If-then planning helps on average, but the cue needs to fit your week.","Habit research links repeated responses with recurring contexts. Change one condition without declaring your surroundings stronger than your choices. Keep your action. Move its material to the cue, or choose a reliable event. Test once and record where the sequence worked or broke. Preserve access, urgent contact, and routines you need."],example:{title:"Leyla's missing tea cue",text:"Leyla planned to write after afternoon tea, but meetings repeatedly removed that break. She changes only the cue: after returning from lunch, open the report already waiting on her desk and write one sentence. She keeps her phone reachable for family contact. On Tuesday the cue occurs and she writes; the sentence still needs a better ending."}},move:{invitation:"Use one record to change one failed condition. Test your existing action at the revised cue.",instructions:["Choose main and backup events you actually encounter.","Change one cue or material, then try the useful minimum."],prompts:[],suggestions:{action:["Write at my revised start cue","Practice beside the ready material","Use my response at the reliable cue"],minimum:["Add one sentence at this cue","Complete one real practice unit","Use one useful response"],cue:["When I return from lunch","When I finish an essential routine","At my next reliable check-in"],place:["Beside my ready draft","At the accessible action setting"],fallback:["After next meeting: one sentence at my desk","Dictate with available equipment","Keep urgent contact accessible"],observation:["Whether the revised cue occurred","Whether the material was ready","What worked or got in the way"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write at my revised start cue",minimum:"Add one sentence at this cue",minutes:2,cueHint:"When I return from lunch",placeHint:"Beside my ready draft",obstacleHint:"The original cue often does not happen.",fallbackHint:"After next meeting: one sentence at my desk",observationHint:"Whether the revised cue occurred"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-6-decision",scenario:"Leyla’s tea break often disappears. Returning from lunch still happens, and her report can stay ready on her desk.",question:"Which adjustment is worth testing first?",options:[{id:"identity-6-earlier-clock",text:"Keep the tea cue, use a clock reminder to protect that break, and write one sentence afterward.",feedback:"A reminder might help noticing, but it does not make the missing tea break happen. The record identifies cue availability as the problem. Test the reliable return event before adding another reminder."},{id:"identity-6-ready-tea-draft",text:"Keep the tea cue and place the draft beside her mug, then write one sentence after tea.",feedback:"Material placement helps when the draft is hard to reach. Here the break itself keeps disappearing, and the draft can already stay ready. Moving it does not supply the missing cue."},{id:"identity-6-reliable-event",text:"Use the lunch return as the cue, keep the draft ready, and test one useful sentence.",feedback:"This addresses the observed break in the sequence. The action stays the same, and the cue already occurs. Record whether the material was ready and the sentence actually happened."}],bestOptionId:"identity-6-reliable-event"}},carry:{takeaway:"Fix the condition your record identifies. Test before adding more rules.",followUp:{questionId:"identity-6-availability-return",question:"Was your revised cue available?",observationPrompt:"Was the material ready? What worked or got in the way?",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"Specific does not automatically mean feasible",paragraphs:["Gollwitzer and Sheeran’s meta-analysis supports specific situation-response plans on average [I01]. It covered varied goals, samples, and methods, rather than one ideal daily routine. “After tea, write” is specific, but specificity does not make tea a reliable event in your week. Feasibility still needs inspection and an actual attempt.","ODA’s revised-cue experiment changes the condition your own record identifies. If the cue did not occur, test another recognizable event. If the cue occurred but materials were missing, make the materials available. If the action was too large, change its size rather than inventing a motivation problem.","This is one teaching adaptation, not evidence that three obstacle plans or a branded stacking method are necessary. The first chip choices form an editable example plan. They become your commitment only when you choose and save what fits your setting."]},{heading:"Context supports practice without deciding everything",paragraphs:["Wood and Rünger describe repeated responses developing in recurring contexts [I06]. Habitual and deliberate processes can operate together. Their narrative review does not establish a universal ranking in which environment changes always beat effort, or prove that every object silently determines your next choice.","For this experiment, material placement is a practical condition you can inspect. Keep the report near the work surface, or make your communication aid available where the conversation happens. State the trade-off: a phone placed farther away may reduce easy access, but urgent contacts or disability supports may require another arrangement.","Changing one condition makes your next record easier to interpret. A useful outcome might be discovering that the new cue also fails. Keep that fact rather than awarding the setup as completed practice. Preparation can be recorded honestly, and the actual action can be rescheduled or adapted."]}],sourceIds:["identity-gollwitzer","identity-wood-runger"]}},w={schemaVersion:2,revision:2,id:"identity-7",courseId:"identity",locale:"en",title:"Missed days? Build a return that fits",goal:"Review the same experiment and choose a feasible next week of practice, support, or recovery.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"The streak broke. Does your next plan serve your life or just repair the number?",reason:{id:"identity-7-reason",label:"Does this experiment still deserve space in your week?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep the useful part","Shrink the demand to my capacity","Choose recovery without catch-up"]},why:{id:"identity-7-direction",label:"Why does this move matter in your actual week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["The famous 66-day figure estimated how automatic a behavior became. It was not a date when people finished changing. Estimates varied widely, and some extended beyond the study’s observation period. They do not tell you when your action should feel easy.","Review this same experiment: useful action, cue, actual attempts, and the condition needing attention. Choose an opportunity that fits your capacity. Repeat, shrink, seek help, rest, or stop a goal that no longer serves you. Do not add a ritual or catch-up debt to prove you finished the course."],example:{title:"Leyla's smaller return",text:"After an illness, Leyla’s report experiment has three days without attempts. She reviews the sentences she actually wrote and the lunch cue that worked. Still exhausted, she chooses recovery today and a check-in tomorrow. She will decide then whether one sentence fits. She records the pause honestly rather than rewriting the missed days or promising a catch-up session."}},move:{invitation:"Review your same experiment. Choose one appropriate next opportunity or save a pause and return date.",instructions:["Keep the useful action; change only what your records justify.","Choose next week’s size and cue without catch-up debt."],prompts:[],suggestions:{action:["Repeat my useful minimum","Try a smaller meaningful unit","Request support for my experiment"],minimum:["Write one usable sentence","Complete one accessible practice unit","Make one practical support request"],cue:["At my next suitable lunch return","When my capacity allows a safe try","At my chosen support check-in"],place:["At my usual accessible setting","In a safe support conversation"],fallback:["Pause and choose a return date","Shrink the actual practice unit","Ask for help with the constraint"],observation:["Whether the action still served my direction","What fit my current capacity","Which condition helped the return"],minutes:[2,1,5],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Repeat my useful minimum",minimum:"Write one usable sentence",minutes:2,cueHint:"At my next suitable lunch return",placeHint:"At my usual accessible setting",obstacleHint:"I want to compensate for unattempted days.",fallbackHint:"Pause and choose a return date",observationHint:"Whether the action still served my direction"},stopRule:"If this involves danger or mistreatment, choose protection or support.",accessibleAlternative:"Type, dictate, use assistance, or choose an equivalent accessible action."},result:{question:"Did you do your chosen minimum?",observationPrompt:"What did you actually do, and what happened next?"},judgment:{primary:{id:"identity-7-decision",scenario:"Leyla missed practice while ill and remains exhausted. Her record shows the lunch cue previously worked.",question:"Which next plan respects the evidence and her capacity?",options:[{id:"identity-7-preserve-volume",text:"Use the familiar cue today and write the usual amount more slowly to keep the routine intact.",feedback:"A familiar cue may help when capacity returns, but it does not override exhaustion. The record supports the cue, not today’s usual volume. Recovery and a dated reassessment can be the appropriate choice."},{id:"identity-7-reassess-capacity",text:"Rest today, choose a dated capacity check, and resume a smaller useful action when it fits.",feedback:"This retains the useful experiment without making recovery a failure. It schedules a decision rather than pretending writing occurred. The next attempt should match the capacity she actually has then."},{id:"identity-7-catch-up",text:"Move the missed work to a longer weekend session so this week still meets the original total.",feedback:"A later session can be chosen for a real need, but missed practice creates no scientific catch-up requirement. An enlarged demand may not fit recovery. Reassess capacity before increasing the next action."}],bestOptionId:"identity-7-reassess-capacity"}},carry:{takeaway:"Keep a useful experiment, revise its demands, and return without a deadline for becoming someone new.",followUp:{questionId:"identity-7-return",question:"Did your chosen return fit your capacity and direction, or does the next plan need changing?",observationPrompt:"What fit your capacity and direction, or what needs changing?",adjustmentPrompt:"What should stay, change, or stop next time?"}},goDeeper:{sections:[{heading:"The famous number was modeled automaticity",paragraphs:["Lally and colleagues followed 96 volunteers choosing eating, drinking, or activity behaviors over 84 days [I04]. There were 82 sufficient-data cases, 62 models, and 39 good fits. In those good-fitting models, time to 95% of the automaticity plateau had a median of 66 days and a range of 18-254 days.","The longer figures were extrapolated beyond observation. The study did not watch everyone “finish a habit,” measure a new personality, or test a rule about two consecutive missed days. One missed opportunity did not materially alter formation in its analysis. That cannot establish a universal recovery rule for longer gaps.","A later review of 20 health-behavior studies also found wide variation [I05]. Only four reported formation times, and 11 studies had high risk of bias. Neither source tells you when writing, listening, or another chosen ODA action must become automatic."]},{heading:"Consolidate the record, not another ritual",paragraphs:["Harkin and colleagues reviewed interventions that increased progress monitoring across 138 randomized studies [I02]. Average goal attainment improved, with a smaller bias-adjusted estimate. Methods and goals varied. The review does not show that a fifteen-minute weekly review, a streak, or a future-self letter is the optimal format.","This course’s consolidation is an ODA design choice. Read the records for the same experiment, distinguish real attempts from plans and pauses, and identify the condition worth keeping. A future plan creates no completed behavior. Missing records stay unknown until you report what happened.","Choose next week’s action size and a recognizable cue only if the experiment still serves your direction. Support, recovery, a boundary, or stopping can be deliberate responses. Keep their names accurate. You do not need a new identity statement, a longer session, or compensation for missed days to make a thoughtful return."]}],sourceIds:["identity-lally","identity-habit-times","identity-harkin"]}},P={id:"identity",title:"Keep slipping back? Change one pattern this week",subtitle:"Seven lessons to find a recurring cue, try a useful response, and improve it from real attempts.",description:"Choose one pattern that crowds out something you want. Try a meaningful response, record the actual result, and refine the cue, preparation, or support that helps it fit your life.",outcome:"One meaningful action, a tested cue, and an honest return plan that fits your actual week.",scope:"For adults who want an everyday way to change a familiar pattern of thinking, feeling or reacting. It draws on Dr. Joe Dispenza and James Clear and says plainly which of their ideas research supports and which it does not. It is not therapy and not a treatment for depression, anxiety, trauma or any illness; if you are struggling, talk to a health professional, and in a crisis call your local emergency number.",photo:{id:"1611569518992-0927098278b7",alt:"A woman walking alone down a dirt road between green trees"},lessons:[{id:"identity-1",schemaVersion:2,v2:p,title:"Still scrolling? Find your changeable moment",minutes:6,goal:"Choose one recurring cue and try a useful response that serves your week.",reading:["A familiar setting can cue a familiar action, even after your priorities change. Habit research separates that repeated response from your whole personality. “After lunch, I scroll before starting” names a pattern. “I am lazy” gives you no moment to work with.","Choose one ordinary cue and one useful alternative. Notice what the old response offers now and what it postpones. Then try the alternative once. This course keeps improving that same experiment. You can start with a small act without rejecting who you are or promising a new personality."],practice:["Choose one familiar cue. Try a response that does something useful for your chosen direction.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What does this pattern protect now and postpone later?",question:"Leyla planned to write after lunch but scrolled. She has five minutes and the report open. Which move starts a useful experiment?",options:["Build a stricter afternoon schedule, then begin the report once the new schedule is complete.","Name what happened after lunch, then write one report sentence and record the cue.","Move tomorrow’s writing before lunch and use today’s remaining five minutes to review the new plan."],correct:1,feedback:"This tests a response in the real setting. The sentence does useful work, and the note identifies the cue. One attempt provides information without proving a whole personality change.",takeaway:"Change one response in one setting. Let the record describe what happened.",sources:["identity-wood-runger","identity-wood-everyday","identity-gollwitzer"],deeper:[{heading:"A pattern is smaller than a person",paragraphs:["Wood and Rünger’s review describes habits as repeated responses associated with recurring contexts [I06]. A setting can call up a familiar response alongside deliberate choices. That is a narrower claim than saying every thought, mood, or difficult day is an automatic program. This lesson asks about one observable behavior, not an “old self” that must be removed.","The diary research used student samples of 70 and 209 people [I07]. Respectively, 35% and 43% of their reports met an almost-daily, same-location definition of habit. Those figures do not describe all adults, and they are not percentages of time spent mind-wandering. Sampling behavior was assessment, not a demonstrated identity treatment.","ODA’s cue-and-response note is a teaching adaptation. Keep only the detail useful for your next choice. An unchanged mood or imperfect afternoon does not invalidate an accurately reported attempt."]},{heading:"Make the alternative consequential",paragraphs:["Gollwitzer and Sheeran’s review combined 94 independent tests involving 8,461 participants [I01]. It found an average goal-attainment benefit from specific if-then plans. The evidence included 83 experimental and 11 correlational tests, with varied goals and methods. It does not establish that this particular ODA sequence changes identity.","For this experiment, connect a recognizable event with a feasible response: when you return after lunch, write one useful report sentence. Specify a cue you actually encounter. Choose an alternative that contributes to your direction, rather than simply opening an app or arranging supplies. Those may be preparation, but the practice should be named accurately.","There is no requirement to interrupt every familiar behavior. Keep routines that serve your life. If the setting calls for safety, rest, or assistance, choose that response deliberately. Review this one attempt before adding another system."]}],example:{title:"Leyla's first report sentence",text:"At 1:30, Leyla returns to her desk and reaches for her phone before writing a report. She wants fewer late evenings. She puts the phone aside and writes one rough opening sentence instead. The wording is awkward, and she later scrolls again. Her record says what she did at the cue, without calling the afternoon a transformation."},photo:{id:"1519087630026-63fb0dab69bb",alt:"A woman looking at her reflection in a wall mirror"}},{id:"identity-2",schemaVersion:2,v2:m,title:"Worry still here? Choose your response anyway",minutes:6,goal:"Use your same cue to do the useful action while an ordinary feeling remains.",reading:["Bring back your cue and action. A familiar feeling is something to notice, not proof of a fixed personality. Naming feelings has a narrow research basis: one small study found a changed brain response when people labeled emotions on faces. It did not test whether your own worry disappears.","Use a label as a description: “Worry is here.” Check whether it points to a real need, then choose your response. You may write your sentence while worried, or seek help if the concern needs action. The useful act counts without a calmer feeling afterward."],practice:["Keep your experiment. Name an ordinary feeling if useful, then do the chosen response.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What is waiting for this feeling costing your direction?",question:"Leyla has five minutes. Her figures match the approved table, and her sentence makes no new calculation. She still feels worried. Which response fits this moment?",options:["Recheck the figures once more so she can feel more certain before writing the sentence.","Draft a provisional sentence and ask a colleague to verify its figure before keeping the line in the report.","Name the worry, write one usable sentence, and record whether the concern needed further action."],correct:2,feedback:"This preserves the feeling and checks its meaning without giving it an automatic veto. The sentence is the practice. If a real concern appears, her next response can be practical help.",takeaway:"A feeling can remain while you choose a useful, safe response.",sources:["identity-lieberman","identity-breines"],deeper:[{heading:"What labeling actually measured",paragraphs:["Lieberman and colleagues studied 30 healthy adults looking at emotional faces in a brain scanner [I10]. Choosing an emotion word produced lower amygdala activation than choosing a gender-matched name. That is a difference in a laboratory brain measure, not a finding that naming your own distress makes it smaller or improves mood for weeks.","ODA uses a short feeling label as optional description. The study did not test this cue, your chosen behavior, or a course about identity. Skip labeling if it adds nothing, and avoid turning every emotion into something you must correct. Grief, anger about unfairness, and fear in danger can deserve a different response.","Bring the observation back to the same action. Did you do it, did you need assistance, or did a real problem change the plan? A record can hold a difficult feeling and a useful behavior without claiming one caused the other."]},{heading:"Support without removing accountability",paragraphs:["Breines and Chen tested compassionate responses in four short experiments, mainly with student or online samples [I11]. Some outcomes supported immediate improvement motivation. In one study, participants spent more time studying after a difficult test than those receiving no intervention. Their later test scores did not significantly differ, and comparison with a self-esteem condition was only marginal.","That evidence does not prove lasting identity change or universal superiority of kindness. It does challenge the assumption that a harsh response is always needed before trying again. This lesson’s instruction to describe a feeling and continue a chosen action is an ODA adaptation, not the tested compassionate-writing procedure.","Use a fair response that keeps responsibility visible. A missing skill calls for learning; an unmet need may call for help. You can act without insulting yourself and can pause without calling the pause a failed personality."]}],example:{title:"Leyla's worried start",text:"After lunch on Thursday, Leyla feels worried about the same report. She checks that she has the required figures, names the worry, and writes her next usable sentence. She still wants to recheck everything. She records the sentence and that the worry stayed. She has practiced writing, not proved that the feeling is a habit."},photo:{id:"1762126242240-cafa01fb1351",alt:"A person in an armchair looking out of a rainy window"}},{id:"identity-3",schemaVersion:2,v2:g,title:"Caught yourself late? Make the next move useful",minutes:6,goal:"Return to your chosen action after a distraction, or repair a response that caused harm.",reading:["Noticing a distraction is different from returning. Keep your chosen cue and action. Add a late-catch response: “If I notice I have drifted, I will do my useful minimum.” Specific cue-and-action plans have improved goal attainment on average in research.","If your response hurt someone, a private catch is not the repair. In a safe setting, acknowledge your part and restart one sentence. If nobody was harmed, return to the task. Record the response, not just notices. You can change the next act without declaring the day ruined."],practice:["Keep your action. Choose what you will do when you notice the pattern late.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What needs a return or repair in this same experiment?",question:"During a safe discussion, Leyla snaps at a colleague. She notices her tone while they are still talking. What best completes the interruption?",options:["Acknowledge the sharp sentence and restate her point respectfully while the conversation is still open.","Pause privately and record the catch, then focus on speaking more patiently in their next discussion.","Explain why the deadline pressure caused her tone, then return to the work discussion without revisiting it."],correct:0,feedback:"This makes the catch consequential. Leyla takes responsibility for her own tone and practices a different response. The colleague does not have to forgive her for the repair attempt to be real.",takeaway:"A catch becomes useful when you return, repair, or choose a safer response.",sources:["identity-gollwitzer","identity-wood-runger","identity-harkin"],deeper:[{heading:"A cue can include late noticing",paragraphs:["Implementation intentions connect a specific situation with a chosen response. Gollwitzer and Sheeran’s synthesis found an average benefit for goal attainment across 94 independent tests [I01]. Goals, delivery, and study methods varied. It does not validate a particular pause word, breathing sequence, or number of daily catches.","This lesson adds late noticing as another possible situation: if you notice scrolling has begun, write your chosen useful sentence. The response is still the same course experiment. A silent cue word is optional shorthand, not the active behavior you are trying to build. No breath or calm feeling is required before returning.","Wood and Rünger describe habits operating alongside deliberate processes [I06]. That leaves room for an intentional response within an imperfect routine. It does not mean every distraction was a habit. Describe what you observed and test whether this cue is recognizable in your actual setting."]},{heading:"Notice, then respond to the consequence",paragraphs:["A record should distinguish noticing, returning, and repairing. Harkin and colleagues reviewed 138 randomized progress-monitoring studies [I02]. Monitoring interventions improved goal attainment on average, though a bias-adjusted estimate was smaller. The review does not establish that counting catches alone changes your relationships or that every private note needs to be shared.","For this ODA adaptation, record the behavior that followed your notice. “I caught my sharp tone” and “I acknowledged it and restated my request” are different facts. If your original task was interrupted, record the useful part you resumed. If you caused no harm, an apology is not required.","Protection takes priority in an unsafe relationship. You do not owe contact, forgiveness, or an explanation to someone who threatens you. Choose a boundary or support step when it fits. Keep those acts named accurately rather than treating every pause as successful repair."]}],example:{title:"Leyla's late catch",text:"At 1:42, Leyla notices she has spent twelve minutes scrolling instead of writing. She closes the feed and adds one useful sentence to her report. Later she notices an abrupt message she sent her colleague. She sends a brief correction of her tone. Neither act erases the lost time, but both are specific responses she can record."},photo:{id:"1626257690705-8d62125575b0",alt:"A man in a dark jacket walking along a city pedestrian lane in daylight"}},{id:"identity-4",schemaVersion:2,v2:f,title:"Busy preparing? Make your next action real proof",minutes:6,goal:"Check that your minimum practices the behavior your direction needs, then do it once.",reading:["Bring back your last attempt. James Clear calls actions “votes” for an identity. That is a metaphor, not a scientific law. You can use it without saying your identity must change first. The useful question is whether this action practices something your direction needs.","Opening a draft proves you opened it. Writing one usable sentence proves you wrote. Both can have a purpose, but name preparation as preparation. Keep the minimum small enough for your week and substantial enough to matter. After an actual attempt, describe only that evidence. “I wrote a sentence” needs no claim about permanent confidence."],practice:["Check your saved minimum. If it only prepares, name that honestly or choose actual practice.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"Is this minimum building the skill or postponing it?",question:"Leyla has five tired minutes and wants report text. Her headings are ready; the next sentence's figure already matches its source. Which minimum does useful work now?",options:["Arrange the notes into a clearer folder so tomorrow’s writing session starts with less friction.","Write one rough sentence in the real report, then decide whether stopping fits her capacity.","Recheck the cited figure against its source, then leave a verified note for tomorrow's sentence."],correct:1,feedback:"This minimum practices the desired behavior and respects the time available. It proves one sentence was written, not that her identity changed. She can stop without making the sentence impressive.",takeaway:"Let your evidence name the behavior. Keep preparation and practice distinct.",sources:["identity-clear-identity","identity-task-belief","identity-activity-identity"],deeper:[{heading:"An identity metaphor has limits",paragraphs:["Clear’s author article presents a desired identity and small supporting actions as a practitioner framework [I15]. It is not a controlled trial proving identity-first change is required or superior. The familiar action-as-vote framing can be memorable without becoming a scientific explanation.","Bandura’s self-efficacy framework concerns perceived capability for a particular task [I17]. Mastery experiences are one source of that belief, alongside observation, persuasion, and physiological information. The framework does not turn one action into a measure of your worth or a verdict about your whole personality.","ODA’s optional evidence statement stays narrow: “I added a usable sentence” or “I made my request.” An untried plan and a correct quiz answer do not establish those behaviors. You may leave identity language out entirely while continuing the same practical experiment."]},{heading:"Behavior and identity are different outcomes",paragraphs:["Rhodes and colleagues reviewed 40 experimental or quasi-experimental effects involving 4,939 adults [I19]. Physical-activity identity changed a little on average, with an effect of g = 0.18. A 30-effect behavior subsample showed a larger average activity effect, but the samples and outcomes differ. Those numbers do not prove identity caused behavior change.","The studies concern physical activity, with heterogeneous results and possible publication bias. They do not validate broad personality transformation, Clear’s vote method, or this report-writing experiment. Difficulty also does not automatically show that a goal matters enough to pursue. It can reveal a missing skill, insufficient resources, or a need to revise the plan.","Use the record to decide what your minimum contributes. Keep a small unit when it fits capacity, increase it only by choice, or change an unsuitable goal. The aim is useful practice in your life, not collecting symbolic votes."]}],example:{title:"Leyla's useful minimum",text:"On Friday, Leyla spends five minutes arranging headings but has written no report text. She checks her experiment and changes the minimum to one usable sentence under a heading. She writes it before stopping. The sentence needs editing. Her optional note says, “I wrote a sentence today,” rather than “I am now a disciplined person.”"},photo:{id:"1787154604447-4a62ed6654e3",alt:"A woman in a dark hijab and sports clothes jogging along a city street"}},{id:"identity-5",schemaVersion:2,v2:y,title:"Rehearsed enough? Give the real moment a chance",minutes:6,goal:"Use optional brief preparation to address one obstacle, then attempt your same real action.",reading:["Rehearsal is preparation, not the action itself. Research on imagining behavior found an average behavioral benefit, but no clear winning type of imagery. It does not prove that imagining the steps beats imagining the outcome, or that a timed identity meditation changes personality.","Use rehearsal if your record shows a preparation gap. Describe or imagine the first step and a likely obstacle. Then try your action at its real cue. If imagery is uncomfortable or unavailable, use words or skip it. Record preparation separately. The attempt can stay awkward, and its outcome remains uncertain."],practice:["If preparation would help, keep it brief. Save the real action as your practice.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"What obstacle would brief rehearsal help you meet?",question:"Leyla knows her first report point and how to enter it. She has ten minutes. Rehearsing a confident session delayed her last two starts. What best connects preparation with practice?",options:["Skip further rehearsal, add one sentence at her report cue, and record where starting was actually difficult.","Spend two minutes rehearsing a smooth start, then write one report sentence before the session ends.","Imagine finishing the report for one minute, then write one sentence and record what helped her start."],correct:0,feedback:"Her record identifies expanding rehearsal, not an unclear first step. Trying the known sentence addresses that obstacle. Record any difficulty the real attempt reveals before deciding whether a specific preparation would help.",takeaway:"Useful rehearsal has an endpoint and a real opportunity beyond it.",sources:["identity-cole","identity-motor-rehearsal","identity-gollwitzer"],deeper:[{heading:"No established winning imagery subtype",paragraphs:["Cole and colleagues combined 94 randomized studies, 123 effects, and 5,685 participants [I03]. Mental simulation had an overall behavioral effect of g = 0.49. Some subtype estimates were numerically larger than others, but the overall subtype comparison was not significant. The process-only subgroup contained just five effects and was uncertain.","Most samples were students, and many studies reported limited information about bias. The review does not establish a superior imagery subtype, an advantage from longer practice, or identity change from a ten-minute meditation. This lesson’s brief preparation is a chosen design, not the reviewed protocol.","Choose words, imagery, or no rehearsal according to the actual preparation gap. A description of a useful first step can be easier to inspect than a perfect future scene. The course record should still ask what happened when that step met the real setting."]},{heading:"Prepare the task you will actually do",paragraphs:["Toth and colleagues’ review of 37 studies concerned motor and task performance [I18]. It reported a small bias-adjusted mental-practice effect, r = .131. Motor-task evidence does not establish changed emotional biology, illness recovery, or whole-person identity change. Rehearsal can support a task without replacing instruction, materials, or real practice.","Specific if-then planning has broader goal-attainment support across varied tests [I01]. For this ODA experiment, connect a real cue with the action you already chose, and use rehearsal only to make the response clearer. Preparing your first report sentence and writing it remain different behaviors. Do not infer one from the other.","Skip scenes involving trauma or distressing memories. You can keep your eyes open, describe the steps without pictures, use assistance, or proceed directly to a safe attempt. If preparation keeps expanding, shrink it rather than requiring another morning ritual."]}],example:{title:"Leyla's imperfect first line",text:"Before Monday’s report session, Leyla describes how she will start: read her last line, then add one sentence even if it sounds clumsy. She rehearses the transition briefly, with eyes open. At her lunch cue, she adds the sentence. It is less fluent than she imagined. She records the real line separately from the preparation."},photo:{id:"1600618528240-fb9fc964b853",alt:"A woman meditating on a wooden deck at sunset"}},{id:"identity-6",schemaVersion:2,v2:b,title:"Your cue keeps failing? Change one condition",minutes:6,goal:"Use your records to adjust one cue or material, then test the same useful action.",reading:["Bring back your attempts. Did the cue occur? Were materials available? A specific plan can fail when its assumed situation never happens. If-then planning helps on average, but the cue needs to fit your week.","Habit research links repeated responses with recurring contexts. Change one condition without declaring your surroundings stronger than your choices. Keep your action. Move its material to the cue, or choose a reliable event. Test once and record where the sequence worked or broke. Preserve access, urgent contact, and routines you need."],practice:["Use one record to change one failed condition. Test your existing action at the revised cue.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"Which convenience will you change to give this action room?",question:"Leyla’s tea break often disappears. Returning from lunch still happens, and her report can stay ready on her desk. Which adjustment is worth testing first?",options:["Keep the tea cue, use a clock reminder to protect that break, and write one sentence afterward.","Keep the tea cue and place the draft beside her mug, then write one sentence after tea.","Use the lunch return as the cue, keep the draft ready, and test one useful sentence."],correct:2,feedback:"This addresses the observed break in the sequence. The action stays the same, and the cue already occurs. Record whether the material was ready and the sentence actually happened.",takeaway:"Fix the condition your record identifies. Test before adding more rules.",sources:["identity-gollwitzer","identity-wood-runger"],deeper:[{heading:"Specific does not automatically mean feasible",paragraphs:["Gollwitzer and Sheeran’s meta-analysis supports specific situation-response plans on average [I01]. It covered varied goals, samples, and methods, rather than one ideal daily routine. “After tea, write” is specific, but specificity does not make tea a reliable event in your week. Feasibility still needs inspection and an actual attempt.","ODA’s revised-cue experiment changes the condition your own record identifies. If the cue did not occur, test another recognizable event. If the cue occurred but materials were missing, make the materials available. If the action was too large, change its size rather than inventing a motivation problem.","This is one teaching adaptation, not evidence that three obstacle plans or a branded stacking method are necessary. The first chip choices form an editable example plan. They become your commitment only when you choose and save what fits your setting."]},{heading:"Context supports practice without deciding everything",paragraphs:["Wood and Rünger describe repeated responses developing in recurring contexts [I06]. Habitual and deliberate processes can operate together. Their narrative review does not establish a universal ranking in which environment changes always beat effort, or prove that every object silently determines your next choice.","For this experiment, material placement is a practical condition you can inspect. Keep the report near the work surface, or make your communication aid available where the conversation happens. State the trade-off: a phone placed farther away may reduce easy access, but urgent contacts or disability supports may require another arrangement.","Changing one condition makes your next record easier to interpret. A useful outcome might be discovering that the new cue also fails. Keep that fact rather than awarding the setup as completed practice. Preparation can be recorded honestly, and the actual action can be rescheduled or adapted."]}],example:{title:"Leyla's missing tea cue",text:"Leyla planned to write after afternoon tea, but meetings repeatedly removed that break. She changes only the cue: after returning from lunch, open the report already waiting on her desk and write one sentence. She keeps her phone reachable for family contact. On Tuesday the cue occurs and she writes; the sentence still needs a better ending."},photo:{id:"1675762647949-1b25f669a687",alt:"A pair of white shoes sitting on a wooden floor"}},{id:"identity-7",schemaVersion:2,v2:w,title:"Missed days? Build a return that fits",minutes:6,goal:"Review the same experiment and choose a feasible next week of practice, support, or recovery.",reading:["The famous 66-day figure estimated how automatic a behavior became. It was not a date when people finished changing. Estimates varied widely, and some extended beyond the study’s observation period. They do not tell you when your action should feel easy.","Review this same experiment: useful action, cue, actual attempts, and the condition needing attention. Choose an opportunity that fits your capacity. Repeat, shrink, seek help, rest, or stop a goal that no longer serves you. Do not add a ritual or catch-up debt to prove you finished the course."],practice:["Review your same experiment. Choose one appropriate next opportunity or save a pause and return date.","Try the saved minimum at your chosen cue, or record a pause.","Record the actual result here; use the dated return to choose your next attempt."],reflection:"Does this experiment still deserve space in your week?",question:"Leyla missed practice while ill and remains exhausted. Her record shows the lunch cue previously worked. Which next plan respects the evidence and her capacity?",options:["Use the familiar cue today and write the usual amount more slowly to keep the routine intact.","Rest today, choose a dated capacity check, and resume a smaller useful action when it fits.","Move the missed work to a longer weekend session so this week still meets the original total."],correct:1,feedback:"This retains the useful experiment without making recovery a failure. It schedules a decision rather than pretending writing occurred. The next attempt should match the capacity she actually has then.",takeaway:"Keep a useful experiment, revise its demands, and return without a deadline for becoming someone new.",sources:["identity-lally","identity-habit-times","identity-harkin"],deeper:[{heading:"The famous number was modeled automaticity",paragraphs:["Lally and colleagues followed 96 volunteers choosing eating, drinking, or activity behaviors over 84 days [I04]. There were 82 sufficient-data cases, 62 models, and 39 good fits. In those good-fitting models, time to 95% of the automaticity plateau had a median of 66 days and a range of 18-254 days.","The longer figures were extrapolated beyond observation. The study did not watch everyone “finish a habit,” measure a new personality, or test a rule about two consecutive missed days. One missed opportunity did not materially alter formation in its analysis. That cannot establish a universal recovery rule for longer gaps.","A later review of 20 health-behavior studies also found wide variation [I05]. Only four reported formation times, and 11 studies had high risk of bias. Neither source tells you when writing, listening, or another chosen ODA action must become automatic."]},{heading:"Consolidate the record, not another ritual",paragraphs:["Harkin and colleagues reviewed interventions that increased progress monitoring across 138 randomized studies [I02]. Average goal attainment improved, with a smaller bias-adjusted estimate. Methods and goals varied. The review does not show that a fifteen-minute weekly review, a streak, or a future-self letter is the optimal format.","This course’s consolidation is an ODA design choice. Read the records for the same experiment, distinguish real attempts from plans and pauses, and identify the condition worth keeping. A future plan creates no completed behavior. Missing records stay unknown until you report what happened.","Choose next week’s action size and a recognizable cue only if the experiment still serves your direction. Support, recovery, a boundary, or stopping can be deliberate responses. Keep their names accurate. You do not need a new identity statement, a longer session, or compensation for missed days to make a thoughtful return."]}],example:{title:"Leyla's smaller return",text:"After an illness, Leyla’s report experiment has three days without attempts. She reviews the sentences she actually wrote and the lunch cue that worked. Still exhausted, she chooses recovery today and a check-in tomorrow. She will decide then whether one sentence fits. She records the pause honestly rather than rewriting the missed days or promising a catch-up session."},photo:{id:"1760715160644-7f5939675b68",alt:"Hikers walking along a trail through a golden meadow"}}]},F=Object.freeze(Object.defineProperty({__proto__:null,COURSE:P,IDENTITY_1_V2:p,IDENTITY_2_V2:m,IDENTITY_3_V2:g,IDENTITY_4_V2:f,IDENTITY_5_V2:y,IDENTITY_6_V2:b,IDENTITY_7_V2:w,SOURCES:C},Symbol.toStringTag,{value:"Module"})),j=[{id:"meaning-frankl",title:"M17 · Viktor Frankl Institute of America · Meaning from a logotherapy perspective",url:"https://viktorfranklamerica.com/meaning-from-a-logotherapy-perspective/",type:"guidance",finding:"Frankl described meaning through creating or doing, experiencing or loving, and an optional stance toward unavoidable suffering.",limitation:"A philosophical and clinical account, not a trial. Suffering is not required, and this reflection does not establish treatment effects."},{id:"meaning-frankl-history",title:"M18 · Viktor Frankl Institute Vienna · Biography",url:"https://www.viktorfrankl.org/biography.html",type:"guidance",finding:"Frankl developed logotherapy before his Nazi imprisonment. The institutional biography documents his life and work.",limitation:"Historical experience does not establish the efficacy of a psychological intervention or require you to find meaning in suffering."},{id:"meaning-act-values",title:"M19 · Bethay, Weinstein & Stubbs · ACT strategies guide (VA MIRECC)",url:"https://www.mirecc.va.gov/MIRECC/VISN16/docs/act-strategies-guide.pdf",type:"guidance",finding:"In ACT, values are ongoing qualities of action; committed action connects them to concrete goals.",limitation:"Professional model guidance, not an experiment. ODA’s compass and short actions are adaptations with no validated score or isolated effect."},{id:"meaning-act-trials",title:"M04 · A-Tjak et al. · 2015 · ACT meta-analysis",url:"https://doi.org/10.1159/000365764",type:"research",finding:"39 randomized trials involving 1,821 people tested full ACT packages for clinically relevant mental or physical problems.",limitation:"Clinical package evidence does not isolate values worksheets, validate this course, or establish superiority to established CBT."},{id:"meaning-sdt",title:"M05 · Ryan & Deci · 2000 · Self-determination theory",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"The theory distinguishes personally endorsed motivation from pressure; some externally introduced responsibilities can become personally endorsed.",limitation:"A theory article, not a motive test. Guilt, pleasure, bodily energy, and whether others notice do not diagnose a value’s authenticity."},{id:"meaning-sdt-interventions",title:"M06 · Ntoumanis et al. · 2021 · Health motivation interventions",url:"https://eprints.whiterose.ac.uk/id/eprint/155741/",type:"research",finding:"73 health intervention studies with 30,088 participants found average improvements in autonomous motivation and health behavior, with heterogeneous effects.",limitation:"58 randomized and 15 quasi-experimental studies used varied supported programs. A brief values worksheet is not the studied intervention."},{id:"meaning-support",title:"M20 · National Institute of Mental Health · Depression",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"Persistent low mood, hopelessness, loss of interest, or impaired functioning deserves professional evaluation and support. US crisis support is available through 988.",limitation:"Loss of meaning alone does not diagnose depression. ODA is educational support and cannot treat depression or manage an acute crisis."},{id:"meaning-carrillo",title:"M09 · Carrillo et al. · 2019 · Best Possible Self meta-analysis",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"29 studies with 2,909 participants supported average improvements in well-being, positive feelings, and optimism. Reductions in negative feelings and depression were not established.",limitation:"Both symptom confidence intervals crossed zero; only three studies measured depression. Mostly short-term, varied protocols. Neither meaning nor future achievement was established."},{id:"meaning-best-possible-self",title:"M10 · King · 2001 · Writing about life goals",url:"https://doi.org/10.1177/0146167201277003",type:"research",finding:"81 undergraduates were randomized across four writing conditions. The future-writing task used 20 minutes on each of four consecutive days.",limitation:"The original task did not test this short, values-linked ODA adaptation. It did not establish greater meaning, illness prevention, or actual future attainment."},{id:"meaning-planning",title:"M11 · Gollwitzer & Sheeran · 2006 · Implementation intentions",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 independent tests with 8,461 participants supported average goal-attainment benefits from plans linking a specific situation to an intended response.",limitation:"The pool included experimental and correlational tests. Contexts varied; planning is not action, and the review did not establish increased meaning or this combined ODA flow."},{id:"meaning-mental-contrasting",title:"M13 · Wang, Wang & Gai · 2021 · Mental contrasting and planning",url:"https://www.frontiersin.org/articles/10.3389/fpsyg.2021.565202/pdf",type:"research",finding:"24 independent studies from 21 articles, with 15,907 participants, found a modest average goal-attainment effect, g = 0.336 [0.229, 0.443].",limitation:"Publication bias and varied formats limit precision. The combined values, future-scene, and action adaptation was not tested; structural barriers are not personal failures."},{id:"meaning-monitoring",title:"M14 · Harkin et al. · 2016 · Progress monitoring",url:"https://eprints.whiterose.ac.uk/id/eprint/87431/1/bul%20harkin%20raw%20final.pdf",type:"research",finding:"138 randomized studies found average goal-attainment benefits from increased monitoring, d = 0.40 [0.32, 0.48].",limitation:"Small-study asymmetry was detected; a sensitivity analysis estimated d = 0.19. Heterogeneous goals and methods do not validate ODA’s next-day timing, meaning effects, or compulsory public tracking."},{id:"meaning-habits",title:"M15 · Lally et al. · 2010 · Habit formation",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"An 84-day observational study followed 96 participants. Modeled automaticity grew at varying rates; one missed opportunity had little measured impact.",limitation:"The often-quoted 66-day median and 18–254-day range are modeled estimates, with longer values extrapolated. They are not deadlines or evidence about repeated gaps or values becoming automatic."}],v=[{schemaVersion:2,revision:2,id:"meaning-1",courseId:"meaning",locale:"en",title:"Busy all week. What actually mattered?",goal:"Give one chosen contribution or relationship a useful action today.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Another week of work, chores, and scrolling? Give one thing you care about an actual turn.",reason:{id:"meaning-1-reason-attention-cost",label:"What optional activity would you postpone to give this direction two minutes?",kind:"text",maxLength:160,optional:!0,suggestions:["Postpone optional scrolling","Move a nonurgent chore","Give connection a small opening"]},why:{id:"meaning-1-why",label:"What matters enough to receive your attention this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["You do not need one grand purpose before doing something you care about. Frankl’s philosophy describes several possible routes: creating or doing, experiencing or loving, and a stance toward unavoidable hardship. These are prompts, not a test or a proven treatment. You can leave hardship out.","Choose one contribution or relationship for this course’s continuing experiment. Give it a small action, a real opening, and a record afterward. Asking a question and listening is an action. Listing who matters is preparation. Your mood can stay unchanged; notice what you actually do."],example:{title:"Tomás’s dinner question",text:"At Tuesday dinner, Tomás realizes he has barely heard his daughter all week. He puts his phone away, asks about her science project, and listens to her answer. She gives him two short sentences before leaving. He records that he asked and stayed attentive. The conversation was brief, but it happened."}},move:{invitation:"Give your chosen relationship or contribution one useful action.",instructions:["Choose one direction to keep through this course.","Do a small act, then record what happened."],prompts:[],suggestions:{action:["Ask and listen without checking my phone","Finish one useful project sentence","Offer one specific piece of help"],minimum:["Ask one question and listen","Write one usable sentence","Make one specific offer"],cue:["When we sit down after dinner","When I open my project","At my next safe check-in"],place:["At the kitchen table","At my usual work surface","In a safe message thread"],minutes:[2,5],fallback:["Use a safe voice or text message","Choose another available opening","Ask for practical support"],observation:["What I asked and heard","The useful sentence I produced","Whether my offer was made"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask and listen without checking my phone",minimum:"Ask one question and listen",minutes:2,cueHint:"When we sit down after dinner",placeHint:"At the kitchen table",obstacleHint:"The person is unavailable or my attention wanders.",fallbackHint:"Use a safe voice or text message",observationHint:"What I asked and heard"},stopRule:"Choose a safe, wanted interaction. Helping must fit your resources and boundaries.",accessibleAlternative:"Use your usual communication method, an assisted contribution, or a private creative act."},result:{question:"Did you do your chosen act?",observationPrompt:"What did you contribute, ask, or hear?"},judgment:{primary:{id:"meaning-1-dinner-opening-decision",scenario:"Tomás chose to hear about his daughter’s project tonight. She has five minutes before leaving. The dinner dishes can wait; he also wants to prepare a useful question.",question:"Which use of this opening serves his chosen direction?",options:[{id:"listen-now",text:"Ask about the project and listen now, then record what actually happened.",feedback:"This uses the opening for the attentive conversation he chose. The answer may be short or distracted. Dishes and more preparation can wait without making connection the right priority for everyone."},{id:"meaning-1-share-chore",text:"Wash dishes together during the five minutes and ask about the project while clearing the table.",feedback:"A shared chore can support connection. Here Tomás chose focused listening, and the dishes can wait. Protect a brief conversation rather than splitting his attention unless they both prefer the shared task."},{id:"meaning-1-prepare-question",text:"Use the five minutes to prepare a thoughtful project question, then send it after she leaves.",feedback:"Preparing a question can make a later conversation easier. Here she is available and he already knows the topic. Ask now; record no occasion if she chooses not to talk."}],bestOptionId:"listen-now"}},carry:{takeaway:"Give what matters an actual turn, then bring back the facts.",followUp:{questionId:"meaning-1-return",question:"What happened when your chosen opening arrived?",observationPrompt:"What act happened, and was the opening available?",adjustmentPrompt:"What would you move or change for the next opening?"}},goDeeper:{sections:[{heading:"A philosophy with more than one route",paragraphs:["Frankl’s three routes come from a philosophical and clinical account, not a checklist everyone must complete. Creating may mean useful work or a deed. Experiencing may mean noticing beauty or attending to a relationship. An attitude toward unavoidable suffering is another possibility, never a requirement. You can choose contribution or connection without describing pain. Frankl’s Institute of America account describes these routes [M17].","The Vienna institute’s biography documents that Frankl was developing logotherapy before his Nazi imprisonment [M18]. His later experience is part of his history, not evidence that a brief lesson treats distress. This course borrows questions from the philosophy and leaves answers with you. If no grand answer appears, you can still choose a modest action. An attentive question, a useful paragraph, or a bounded offer of help gives your selected direction something observable."]},{heading:"From noticing to a real opportunity",paragraphs:["A meaningful-looking plan and a completed action are different records. Planning research supports specifying an opportunity and a response: when a recognizable situation occurs, do the behavior you intend. Gollwitzer and Sheeran pooled 94 independent tests involving 8,461 participants [M11]. Goal attainment improved on average, but tests included different populations, goals, and designs. The result does not establish that planning raises meaning or that this course’s combined philosophy and action flow works.","ODA’s adaptation lets you choose one direction, an act, and a feasible minimum. Keep the first act relevant: listening to one answer serves connection; merely opening a contacts list is preparation. Record an unavailable opening as no occasion, and a future appointment as planned. You do not need to prove that the conversation changed your life. Its practical value is information for your next choice, including whether another setting, support, or a different direction would suit you better."]}],sourceIds:["meaning-frankl","meaning-frankl-history","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-2",courseId:"meaning",locale:"en",title:"What matters gets your leftover minutes?",goal:"Protect a small action for your existing direction and name what must wait.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"You say this matters. Does it get time, or whatever is left after everything else?",reason:{id:"meaning-2-reason",label:"What will you move so this direction gets time?",kind:"text",maxLength:160,optional:!0,suggestions:["Move optional scrolling","Keep a smaller commitment","Make room for careful work"]},why:{id:"meaning-2-why",label:"What will you move so this direction gets time?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A goal is something you can finish, such as visiting someone Sunday. A value is an ongoing way you want to act, such as being attentive. That distinction comes from a therapy model, not a rule that goals are less important. Missing one destination does not settle which direction you want.","Reuse your experiment’s direction and action. Look at the next available slot. Two worthwhile things may compete for it. Choose a useful minimum and say what will wait. This is a real trade-off, not proof that the other value disappeared. Do the act before judging the choice."],example:{title:"Tomás makes room",text:"On Wednesday, Tomás has ten minutes before a household task. He wants another conversation and also wants to read. He gives two minutes to his daughter’s project, then starts the task. Reading waits until Thursday. His daughter seems distracted, and he records that too. He chose a bounded act rather than fitting everything in."}},move:{invitation:"Keep your direction. Give its next act a feasible slot.",instructions:["Name one competing use of this time.","Choose a useful minimum and do it."],prompts:[],suggestions:{action:["Ask and listen in my protected slot","Write a useful project sentence","Complete one bounded care task"],minimum:["Listen to one answer","Produce one usable sentence","Complete one small agreed task"],cue:["When we sit down after dinner","At my protected project slot","After an existing care routine"],place:["At the kitchen table","At my usual work surface","Where the task is needed"],minutes:[2,5],fallback:["Use a shorter available conversation","Reduce the useful task size","Ask to share the responsibility"],observation:["The act and what waited","Time I actually used","Whether the smaller version served my direction"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask and listen in my protected slot",minimum:"Listen to one answer",minutes:2,cueHint:"When we sit down after dinner",placeHint:"At the kitchen table",obstacleHint:"Two worthwhile commitments compete for the same slot.",fallbackHint:"Use a shorter available conversation",observationHint:"The act and what waited"},stopRule:"Do not displace urgent care or needed recovery. Change the slot or size instead.",accessibleAlternative:"Use assisted communication, a seated task, or support to protect the same direction."},result:{question:"Did you do the protected minimum?",observationPrompt:"What did you do, and what did you leave for later?"},judgment:{primary:{id:"meaning-2-chosen-commitment-decision",scenario:"Tomás promised an attentive conversation before his daughter’s trip. Tonight’s ten minutes are their last opening. He also values finishing a nonurgent reading chapter; a longer call can wait until next week.",question:"Which choice keeps his commitment within this slot?",options:[{id:"reading-later",text:"Listen briefly now and choose another reading slot, accepting that this time is limited.",feedback:"This keeps the conversation he chose while tonight’s opening exists. Reading still matters and can have another slot. The case turns on his commitment and timing, not which value outranks another."},{id:"full-both",text:"Try to finish the chapter while listening, so neither important commitment has to wait.",feedback:"Combining tasks can protect reading time, but it divides the attention he promised. Use a short listening minimum now and move reading, rather than claiming that both full commitments fit."},{id:"meaning-2-next-week-call",text:"Read tonight and schedule a longer conversation next week, giving both commitments their own protected time.",feedback:"Separate slots can be sensible, and a longer call may be worthwhile. It still misses the before-trip conversation he chose. Keep the small commitment now; schedule a longer follow-up separately."}],bestOptionId:"reading-later"}},carry:{takeaway:"A direction can survive a missed goal. Give it a feasible action now.",followUp:{questionId:"meaning-2-return",question:"Did your protected slot serve the direction you chose?",observationPrompt:"Did the minimum serve your direction, and what had to wait?",adjustmentPrompt:"Keep the trade-off or change the slot or size?"}},goDeeper:{sections:[{heading:"Direction and destination are different tools",paragraphs:["The ACT strategies guide by Bethay and colleagues describes values as chosen qualities of ongoing action and committed action as linking those qualities to concrete goals [M19]. Being attentive is a direction. Listening to one answer tonight is a finite act. They work together. You can finish the act without finishing attentiveness, and you can revise a goal while keeping the direction. These are distinctions within the ACT model, not experimentally discovered universal categories.","ODA’s compass is a teaching adaptation: choose a life area, name the quality you want to express, consider your circumstances, and choose a feasible act. It has no validated score cutoff. You do not need to rate every area or repair the largest numerical gap. A person with care duties, limited energy, or an inflexible shift may choose sustainability first. Use your actual week to decide what gets a turn, rather than treating the compass as a verdict on your life."]},{heading:"A brief action is not a therapy package",paragraphs:["A-Tjak and colleagues reviewed 39 randomized trials with 1,821 participants facing clinically relevant mental or physical problems [M04]. Those studies tested full acceptance and commitment therapy packages, with varying conditions and comparisons. They did not isolate a values compass, establish the effect of this single worksheet, or show that ODA delivers therapy. A useful framework can guide a choice without inheriting the entire package’s clinical evidence.","The scheduling component has separate support from specific cue-response planning research [M11]. A cue such as sitting down after dinner is more recognizable than “sometime this week.” That evidence concerns goal attainment, not feeling fulfilled. Keep your minimum meaningful and its cost visible. If you postpone a nonurgent task, name the next slot rather than pretending the trade-off vanished. If the slot threatens essential care or recovery, shrink the act, obtain help, or choose a different opening."]}],sourceIds:["meaning-act-values","meaning-act-trials","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-3",courseId:"meaning",locale:"en",title:"Your choice can still feel difficult",goal:"Act on one reason you endorse while respecting responsibilities and constraints.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Still feel guilty about a choice you care about? That feeling does not decide whether the choice is yours.",reason:{id:"meaning-3-reason",label:"Which reason do you endorse, and what must you protect?",kind:"text",maxLength:160,optional:!0,suggestions:["Care for people I love","Keep financial responsibilities","Choose one elective commitment"]},why:{id:"meaning-3-why",label:"Which reason do you endorse, and what must you protect?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A responsibility learned from family can become one you personally endorse. Motivation research distinguishes acting from endorsed reasons and acting under pressure, but it does not offer an instant authenticity test. Feeling guilty, tired, or pleased tells you something about your experience. It does not settle which value belongs to you.","Look at the same direction you have been testing. Name a reason you still support and a constraint you need to respect. Keep essential obligations. Change one low-cost elective choice, then do the useful act. Mixed motives are allowed. You do not need perfect certainty first."],example:{title:"Tomás keeps an endorsed reason",text:"On Thursday at the kitchen table, Tomás feels guilty about declining an optional work chat. He still endorses being present with his daughter and keeps his required shift. During their two minutes he asks about her model and listens. He records the conversation and the unease. His reason remained chosen even though the guilt stayed."}},move:{invitation:"Test one endorsed reason through your existing small act.",instructions:["Keep necessary obligations and name one elective trade-off.","Do the act without demanding a clear feeling."],prompts:[],suggestions:{action:["Ask and listen for a reason I endorse","Make one elective project contribution","Decline one optional competing invitation"],minimum:["Listen to one answer","Produce one useful sentence","State one clear availability limit"],cue:["When we sit down after dinner","At my elective project slot","When the optional invitation arrives"],place:["At the kitchen table","At my usual work surface","In a safe message thread"],minutes:[2,5],fallback:["Keep obligations and shrink this act","Choose a lower-cost elective choice","Ask for support with the constraint"],observation:["What I chose despite mixed feelings","The reason I still endorse","The obligation I protected"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask and listen for a reason I endorse",minimum:"Listen to one answer",minutes:2,cueHint:"When we sit down after dinner",placeHint:"At the kitchen table",obstacleHint:"I feel pressure, and some responsibilities cannot be dropped.",fallbackHint:"Keep obligations and shrink this act",observationHint:"What I chose despite mixed feelings"},stopRule:"Avoid irreversible changes. Protect essential income, care, safety, and needed support.",accessibleAlternative:"Use a private or assisted choice, a safe written limit, or practical support."},result:{question:"Did you carry out your chosen act?",observationPrompt:"What did you choose, and which responsibility did you protect?"},judgment:{primary:{id:"meaning-3-elective-cost-decision",scenario:"Tomás values income and tonight’s family conversation. The networking chat is repeated tomorrow with the same contacts; skipping tonight affects no paid shift. Guilt still pushes him to attend every event.",question:"Which choice tests his reason at a manageable cost?",options:[{id:"meaning-3-attend-and-reschedule",text:"Attend tonight’s chat and schedule a family conversation after his next shift, preserving both commitments.",feedback:"Rescheduling can protect two worthwhile commitments. Here the same contacts are available tomorrow without income loss. Moving tonight’s chosen conversation responds to pressure while passing up an available lower-cost alternative."},{id:"endorsed-choice",text:"Keep the required shift, decline tonight’s optional event, and use the conversation slot he values.",feedback:"This tests the reason he endorses while protecting income and retaining tomorrow’s networking opportunity. Guilt may remain. If the professional cost were different, another trade-off could be appropriate."},{id:"meaning-3-split-evening",text:"Join the chat briefly, then shorten the family conversation so he stays visible at both.",feedback:"A split can work when both openings are scarce. Here networking repeats tomorrow. Dividing tonight protects visibility at the cost of the attention he chose; use the separate available opening instead."}],bestOptionId:"endorsed-choice"}},carry:{takeaway:"Endorse a reason, respect its costs, and test it in a small choice.",followUp:{questionId:"meaning-3-return",question:"Do you still endorse the reason after making the choice?",observationPrompt:"What reason do you endorse now, including uncertainty or change?",adjustmentPrompt:"Keep the reason, revise it, or get support with its cost?"}},goDeeper:{sections:[{heading:"Inherited does not mean inauthentic",paragraphs:["Ryan and Deci’s self-determination theory describes how externally introduced motives can become personally endorsed [M05]. A family responsibility can be difficult, relational, and yours. Enjoyment is one possible reason to act; caring about someone’s security is another. This does not make every pressured commitment healthy. It means origin, discomfort, or recognition alone cannot decide authenticity. Ask which reasons you currently endorse and which pressures constrain the choice.","The nobody-watching question is an optional reflection prompt, not a validated test. Guilt does not prove a borrowed value, and bodily energy does not prove a true one. Asking why can help you reflect. It cannot certify that one motive is your true motive. You may find mixed reasons and still make a deliberate choice. Protect necessary income and care, acknowledge cultural commitments, and test a reversible elective action. No change in career, relationship, or family obligation is required to finish this lesson."]},{heading:"Support changes motivation; a worksheet has limits",paragraphs:["Ntoumanis and colleagues pooled 73 health-domain intervention studies involving 30,088 participants [M06]. The programs supported average improvements in autonomous motivation and health behavior, with substantial variation. The pool contained 58 randomized and 15 quasi-experimental studies. This evidence concerns supported health interventions. It does not show that three questions reveal a hidden true motive, that external motives are always harmful, or that a short ODA exercise reproduces the programs.","The ACT model also connects chosen ongoing qualities with concrete action [M19]. Here that connection is an ODA adaptation, not a tested combined treatment. Use the next attempt to learn something specific: did this choice fit your responsibilities, and do you still endorse its reason? An uneasy feeling can remain in the record. If pressure involves coercion or danger, protection and support take priority over experimenting with compliance. You can change the direction, keep it privately, or pause without explaining yourself."]}],sourceIds:["meaning-sdt","meaning-sdt-interventions","meaning-act-values"]}},{schemaVersion:2,revision:2,id:"meaning-4",courseId:"meaning",locale:"en",title:"A hard chapter owes no silver lining",goal:"Protect your chosen direction with one practical request, boundary, or humane act.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Trying to make this pain meaningful? Start with what can be helped, and let the meaning question wait.",reason:{id:"meaning-4-reason",label:"What practical change would make this direction sustainable?",kind:"text",maxLength:160,optional:!0,suggestions:["Share a care task","Protect needed rest","Ask for qualified support"]},why:{id:"meaning-4-why",label:"What practical change would make this direction sustainable?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["An event may be unchangeable while present arrangements can still change. An illness deserves care and assessment, not automatic placement in a “nothing can be done” column. Frankl’s idea of a stance toward unavoidable suffering is a philosophical possibility. It is not a duty to find a gift in pain.","Return to your experiment. If strain is making its action unsustainable, change the support around it. Ask for one practical task, set a safe boundary, or protect needed rest. These can serve the same direction. Record the actual request or change. Feeling meaningful is not the requirement."],example:{title:"Tomás shares the care load",text:"On Friday, Tomás feels drained after arranging his father’s visits. He wants to keep caring without losing every evening. At the kitchen table he sends his brother a request to handle Saturday’s transport. His brother has not replied by bedtime. Tomás records the request. The sadness remains, and he does not turn it into a lesson."}},move:{invitation:"Keep the direction. Change one burden that can be helped.",instructions:["Check for a practical change before an attitude exercise.","Make one specific request or safe protective act."],prompts:[],suggestions:{action:["Ask for help with one care task","Set one safe availability boundary","Request qualified support"],minimum:["Send one specific help request","State one clear limit","Make one support contact"],cue:["After dinner before planning visits","When the next request arrives","At my chosen support opening"],place:["At the kitchen table","In a safe message thread","In my accessible private space"],minutes:[2,5],fallback:["Ask another suitable support person","Keep the boundary private and get help","Choose an accessible support route"],observation:["The request and any response","The practical arrangement I changed","Whether I made the support contact"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Ask for help with one care task",minimum:"Send one specific help request",minutes:2,cueHint:"After dinner before planning visits",placeHint:"At the kitchen table",obstacleHint:"The first person cannot help, or contact is unsafe.",fallbackHint:"Ask another suitable support person",observationHint:"The request and any response"},stopRule:"For US crisis support, call/text 988; elsewhere use local crisis support. In immediate danger, use local emergency services.",accessibleAlternative:"Use an assisted request or rest. Seek professional support sooner if hopelessness persists or daily functioning suffers."},result:{question:"Did you make your chosen practical move?",observationPrompt:"What did you request or change, including no response?"},judgment:{primary:{id:"meaning-4-transport-constraint-decision",scenario:"Saturday’s medical transport leaves Tomás exhausted. His brother offered to drive if confirmed tonight. Visits can be shorter, but transport is required. Free community transport has no Saturday space.",question:"Which arrangement addresses the current burden?",options:[{id:"meaning-4-shorten-visits",text:"Shorten Saturday’s visit and keep driving, so he reduces the demand without coordinating another person.",feedback:"Shorter visits can protect energy and may still help. They do not change the required driving that is draining him. Confirm the available transport offer, then choose a sustainable visit length."},{id:"meaning-4-community-route",text:"Ask community transport about a cancellation place and wait for that answer before confirming his brother.",feedback:"Community transport could be a useful future route. Saturday has no confirmed space, while his brother’s offer needs an answer tonight. Secure the available help rather than making it depend on a cancellation."},{id:"share-task",text:"Ask his brother to handle transport, then choose a visit length he can sustain.",feedback:"This uses the available offer for the burden that can change, while keeping medical transport covered. The request can be completed before agreement arrives. Record an unanswered request as such."}],bestOptionId:"share-task"}},carry:{takeaway:"Change the help and the arrangement before demanding a better attitude.",followUp:{questionId:"meaning-4-return",question:"What help or practical change followed your request?",observationPrompt:"What response or arrangement changed, including no reply?",adjustmentPrompt:"What help, boundary, or rest fits the remaining burden?"}},goDeeper:{sections:[{heading:"Past facts and present possibilities",paragraphs:["Frankl’s account includes a possible stance toward suffering that truly cannot be avoided [M17]. This is philosophical guidance, not evidence that attitude cures illness or makes trauma useful. A death or past event cannot be reversed. Current symptoms, treatment options, social support, and daily arrangements may still be changeable. Do not place a diagnosis, another person’s harm, or lack of assistance in an unchangeable column without considering help.","The ACT model offers chosen qualities of action during difficult feelings [M19]. It does not require making those feelings disappear or remaining in preventable danger. Your experiment can retain care as its direction while changing from another visit to a request for shared transport. Rest, a boundary, or getting information may be the appropriate act. These are choices to assess in context, not proof of a noble attitude. You may leave the meaning question unanswered, and you never owe an account of suffering to ODA."]},{heading:"Support does not wait for purpose",paragraphs:["The National Institute of Mental Health describes depression symptoms and professional evaluation and treatment options [M20]. Persistent hopelessness, low mood, loss of interest, or difficulty functioning deserves support. Loss of meaning alone is not a diagnosis, and a course cannot make that assessment. You can seek help before symptoms reach any duration threshold. Do not wait to complete the course or produce a values answer before contacting a doctor or mental health professional.","In the United States, call or text 988 for suicide or emotional crisis support. For immediate danger use emergency services. Elsewhere use local crisis or emergency resources. The appropriate next move in a crisis is human help, not another reflection exercise. Outside crisis, your request can stay specific and modest: a practical care task, time to recover, or an appointment. No reply is still a factual observation. If the first route is unavailable, seek another suitable route rather than interpreting that obstacle as a failure of meaning."]}],sourceIds:["meaning-frankl","meaning-act-values","meaning-support"]}},{schemaVersion:2,revision:2,id:"meaning-5",courseId:"meaning",locale:"en",title:"Your imagined future needs one real piece",goal:"Use a modest future scene to choose a concrete act for your existing direction.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Your future looks clear in your head. What piece of it will exist in your actual week?",reason:{id:"meaning-5-reason",label:"What must change this week for that future to fit?",kind:"text",maxLength:160,optional:!0,suggestions:["Show up for connection","Make one useful artifact","Respect my budget and energy"]},why:{id:"meaning-5-why",label:"What must change this week for that future to fit?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Future writing has clearer research support for optimism and positive feelings than for reducing depression or negative feelings. It does not establish that the imagined life happens. A short scene can be preparation for your experiment, not evidence that you have acted.","Picture an ordinary near-future day if that helps. Keep your existing direction and choose its next visible piece: a real conversation, useful sentence, or specific request. Face the obstacle and your resources. Then do the piece. Skip future imagery if it is unhelpful. You can choose the action directly instead."],example:{title:"Tomás’s ordinary Tuesday",text:"At Saturday breakfast, Tomás pictures a Tuesday when care duties are shared and he helps at home. The scene is preparation. He turns one part into action: writing a clear label for his daughter’s school model. He finishes the label at the kitchen table; the rest of the model still needs work."}},move:{invitation:"Turn one piece of your future into today’s existing act.",instructions:["Use a short scene if useful. This is preparation.","Name a real obstacle, then do one relevant piece."],prompts:[],suggestions:{action:["Write one useful project sentence","Make one useful project sketch","Send one relevant feedback request"],minimum:["Produce one usable sentence","Draw one usable outline","Send one specific feedback question"],cue:["When I open my project","When the project needs an outline","At my protected work slot"],place:["At my usual work surface","At the kitchen table","In a safe message thread"],minutes:[2,5],fallback:["Choose a smaller relevant contribution","Use a text description instead","Ask for help with access"],observation:["The piece I actually contributed","What the obstacle changed","The request and any response"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Write one useful project sentence",minimum:"Produce one usable sentence",minutes:2,cueHint:"When I open my project",placeHint:"At my usual work surface",obstacleHint:"The imagined version exceeds my available resources.",fallbackHint:"Choose a smaller relevant contribution",observationHint:"The piece I actually contributed"},stopRule:"Keep the future modest and safe. Skip imagery if distress grows; avoid costly commitments.",accessibleAlternative:"Choose the act directly, use words instead of imagery, or make an assisted contribution."},result:{question:"Did you produce your chosen piece?",observationPrompt:"What actually existed or happened after your attempt?"},judgment:{primary:{id:"meaning-5-feedback-opening-decision",scenario:"A designer has one finished sample and a colleague’s feedback opening tonight. The intended future is shared work; stronger equipment can be borrowed next week, but this sample needs none.",question:"Which move tests that direction within current resources?",options:[{id:"meaning-5-prepare-presentation",text:"Spend tonight improving the sample’s presentation, then ask for feedback at the colleague’s next opening.",feedback:"Better presentation can clarify a sample. This one is finished, and the feedback opening is tonight. Send a specific question now; use the answer to decide whether presentation needs work."},{id:"share-sample",text:"Protect the budget and send the existing sample with one specific feedback question.",feedback:"This tests a relevant behavior within current resources. Future writing and goal attainment are different outcomes. An imperfect reply still gives information for the next attempt."},{id:"meaning-5-borrow-equipment",text:"Wait for next week’s borrowed equipment, then make a stronger sample before asking for feedback.",feedback:"Borrowing can protect the budget when equipment is necessary. This sample needs none, and the colleague is available now. Test shared work with the existing sample before expanding its requirements."}],bestOptionId:"share-sample"}},carry:{takeaway:"A future scene is preparation. Give its direction one real piece today.",followUp:{questionId:"meaning-5-return",question:"Did your act connect the future scene to this week?",observationPrompt:"What piece existed, and how did it serve your direction?",adjustmentPrompt:"What resource or obstacle should the next piece address?"}},goDeeper:{sections:[{heading:"What future writing has actually shown",paragraphs:["Carrillo and colleagues combined 29 studies with 2,909 participants [M09]. The pooled results supported average improvements in well-being, optimism, and positive feelings. Reductions in negative feelings and depressive symptoms were not established. Their confidence intervals included zero, and only three studies assessed depression. A positive-looking average number cannot settle an uncertain estimate. The studies mostly measured short-term outcomes and used varied writing protocols; they did not establish greater meaning or actual future achievement.","King’s original future-writing task used 20 minutes on each of four consecutive days, with 81 undergraduates randomized across four writing conditions [M10]. The short, near-future, values-linked scene here changes the dose and purpose. It is an ODA adaptation, not that original procedure. Optional longer writing needs its own time. You do not have to produce an ideal five-year life or compare yourself with it. An ordinary possibility can be enough to select a practical next act."]},{heading:"Give the future a present obstacle",paragraphs:["Mental contrasting with implementation intentions joins a feasible wish, its desired outcome, a present obstacle, and an if–then response. Wang and colleagues reviewed 24 independent studies from 21 articles, with 15,907 participants [M13]. Goal attainment showed a modest average effect, g = 0.336, with a 95% confidence interval of 0.229 to 0.443. Publication-bias adjustment gave a smaller estimate; varied delivery and study quality limit certainty. There is no universal proven session length.","This course combines a future scene with your existing direction and a concrete act. That package has not been tested. Treat a missing resource, care duty, or unsafe setting as a real constraint, not an internal weakness. A practical response might be a smaller relevant artifact, a request for help, or a different opportunity. Record the actual artifact or interaction separately from the scene. If imagining the future adds pressure or distress, leave it out and continue with a directly chosen act."]}],sourceIds:["meaning-carrillo","meaning-best-possible-self","meaning-mental-contrasting"]}},{schemaVersion:2,revision:2,id:"meaning-6",courseId:"meaning",locale:"en",title:"Another missed plan? Keep what worked",goal:"Use your records to repeat, adapt, or stop one values-linked experiment next week.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Another missed plan? Use your actual attempts to choose what comes next.",reason:{id:"meaning-6-reason",label:"Which act earned another place in your real week?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep a useful small act","Change the cue that failed","Protect a sustainable direction"]},why:{id:"meaning-6-why",label:"Which act earned another place in your real week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Planning an act and doing it are different. Research supports cue-linked plans and progress monitoring for goal attainment on average. Neither establishes that a daily act increases meaning. Keep your experiment’s facts separate from the feeling it gave you.","Look back at the same direction and your actual records. Which opening happened? Which minimum served its purpose? Choose one thing to repeat or change next week. Keep the useful act; drop extra rituals. A missed opportunity is information, not a habit deadline or a verdict on your values. Support, rest, and stopping a harmful plan remain options."],example:{title:"Tomás plans from his records",text:"On Sunday at the kitchen table, Tomás sees two conversations, one unavailable opening, and an unanswered help request in his records. Two minutes after dinner worked better than a late evening slot. He asks his daughter about the model again and listens. For next week he keeps that cue, with another support request if visits crowd it out."}},move:{invitation:"Use your records. Keep one useful act for the next week.",instructions:["Compare the actual openings and minimums you tried.","Change one condition, then make the next attempt."],prompts:[],suggestions:{action:["Repeat my useful listening act","Repeat my useful project contribution","Make the support request my records suggest"],minimum:["Listen to one answer","Produce one usable sentence","Send one specific support request"],cue:["When we sit down after dinner","At my tested project cue","Before the next care arrangement"],place:["At the kitchen table","At my usual work surface","In a safe message thread"],minutes:[2,5],fallback:["Use my tested smaller version","Choose another realistic opening","Get support or pause this plan"],observation:["The act and whether the cue happened","What my changed condition allowed","Whether the minimum still served my direction"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}]},suggested:{action:"Repeat my useful listening act",minimum:"Listen to one answer",minutes:2,cueHint:"When we sit down after dinner",placeHint:"At the kitchen table",obstacleHint:"The old slot no longer fits my responsibilities.",fallbackHint:"Use my tested smaller version",observationHint:"The act and whether the cue happened"},stopRule:"Change or stop plans that conflict with safety, care, or needed recovery.",accessibleAlternative:"Keep one accessible act, ask for support, or choose rest without adding a new ritual."},result:{question:"Did you do the next minimum?",observationPrompt:"What did you actually do, and did the chosen cue occur?"},judgment:{primary:{id:"meaning-6-tested-opening-decision",scenario:"Tomás’s late-night slot failed twice because visits ran late. Dinner supported two brief conversations. Weekend availability is uncertain. He wants contact next week and can use the dinner opening again.",question:"Which next-week plan best uses these records?",options:[{id:"meaning-6-earlier-night",text:"Move the evening conversation thirty minutes earlier, aiming to keep a longer uninterrupted discussion.",feedback:"An earlier slot could preserve a longer conversation. The records still show visits running late, and do not establish that this shift avoids them. Test the dinner opening that already supported contact."},{id:"meaning-6-weekend-conversation",text:"Reserve a longer weekend conversation so weekday visits no longer compete with the planned contact.",feedback:"A weekend conversation may be valuable if they agree a slot. Availability is uncertain here. Keep the tested dinner minimum for next week and arrange a longer conversation when a real opening exists."},{id:"tested-cue",text:"Keep connection, use the dinner minimum, and record the next attempt before changing anything else.",feedback:"This repeats an opening that supported the chosen act. It does not guarantee another conversation. Record whether the cue occurred and what happened, then decide whether more support or a change is needed."}],bestOptionId:"tested-cue"}},carry:{takeaway:"Keep one direction, one useful act, and a record that improves the next attempt.",followUp:{questionId:"meaning-6-return",question:"Did the condition chosen from your records help the next act?",observationPrompt:"Did the cue occur, and what did that condition enable?",adjustmentPrompt:"Repeat the condition, change it, get support, or stop?"}},goDeeper:{sections:[{heading:"Planning and monitoring answer behavioral questions",paragraphs:["Gollwitzer and Sheeran pooled 94 independent tests with 8,461 participants [M11]. Specific situation-response plans improved goal attainment on average, across varied designs and settings. Harkin and colleagues reviewed 138 randomized monitoring studies [M14]. Their pooled goal-attainment estimate was d = 0.40, with a 95% confidence interval of 0.32 to 0.48. Small-study asymmetry was detected, and a sensitivity analysis estimated d = 0.19. These results concern goal attainment, not a promise of fulfillment.","ODA’s receipt and next-day return have not been validated by these reviews. Their purpose is to compare a particular commitment with a factual attempt, then choose a better fit. Public tracking is unnecessary. Keep sensitive details off ODA if you prefer. A future plan stays planned, and an absent report stays unknown. You can repeat an effective minimum without increasing its size. A practical support request or rest plan may serve the same direction more appropriately than another demanding performance."]},{heading:"A habit estimate is not a deadline",paragraphs:["Lally and colleagues followed 96 participants in an 84-day observational study [M15]. Participants chose eating, drinking, or activity behaviors with daily cues. Modeled automaticity grew at widely differing rates. The familiar 66-day median and 18–254-day range describe fitted estimates, with longer estimates extending beyond observation. They are not deadlines for your action, evidence that values become automatic, or proof that several missed days have no effect. A single missed opportunity had little measured impact in that study.","Your experiment uses a nonfood, values-linked act and a next-day review. That is an adaptation, not the study protocol. Consolidate what your records support: a workable cue, a useful minimum, and a response to the actual obstacle. Leave out an exercise that did not help. Do not repair an interrupted week by doubling every demand. Choose the next feasible opportunity, ask for support when needed, and keep the historical record intact when you change the plan."]}],sourceIds:["meaning-planning","meaning-monitoring","meaning-habits"]}}],O=[{id:"meaning-1",practice:["Choose one contribution or connection; hardship reflection is optional.","Name a useful act and a safe opening.","Do the chosen act and record what happened."],correct:1,photo:{id:"1469474968028-56623f02e42e",alt:"A lone figure on a rock above a misty valley"}},{id:"meaning-2",practice:["Reuse your chosen direction and act.","Protect a feasible slot by naming one nonurgent trade-off.","Do the useful minimum and record what waited."],correct:2,photo:{id:"1470071459604-3b5ec3a7fe05",alt:"Clouds drifting over green cliffs and a valley"}},{id:"meaning-3",practice:["Name a reason you endorse while allowing mixed motives.","Protect necessary obligations and choose one reversible elective trade-off.","Carry out the act and record the choice without grading guilt."],correct:0,photo:{id:"1447752875215-b2761acb3c5d",alt:"A wooden footbridge through a green forest"}},{id:"meaning-4",practice:["Check what practical help or protection is possible.","Choose a specific request, safe boundary, or needed rest.","Carry out the chosen move without requiring meaning or a silver lining."],correct:2,photo:{id:"1519681393784-d120267933ba",alt:"Stars above snowy mountains at night"}},{id:"meaning-5",practice:["Optionally picture a modest near-future scene; this is preparation, not the original writing protocol.","Name one real obstacle and a feasible response.","Do one relevant piece and record it separately from the scene."],correct:1,photo:{id:"1501785888041-af3ef285b470",alt:"A calm lake surrounded by mountains"}},{id:"meaning-6",practice:["Compare the actual attempts for your existing direction.","Choose one condition to repeat or change next week.","Try the useful minimum and record the cue and act."],correct:1,photo:{id:"1472214103451-9374bd1c798e",alt:"A green meadow with trees in soft light"}}],L={id:"meaning",title:"Busy but directionless? Give what matters a turn",subtitle:"6 lessons to turn one valued direction into real acts, honest records, and a workable next week.",description:"Choose one contribution or relationship worth attending to. Test a small action, face its trade-offs, and adjust from what actually happens.",scope:"For adults who feel busy but directionless, are at a crossroads, or want their days to reflect what they care about. It is education and self-reflection, not therapy or treatment. If emptiness or hopelessness persists or daily functioning becomes difficult, talk to a doctor or mental health professional. You can seek support sooner. For thoughts of suicide or an emotional crisis in the US, call or text 988; elsewhere use local crisis support. For immediate danger, use local emergency services.",outcome:"One values-linked experiment with actual attempt records and a next-week plan that respects your responsibilities.",photo:{id:"1500530855697-b586d89ba3ee",alt:"A road winding through open hills toward the horizon"},lessons:v.map((e,t)=>{const a=O[t],n=e.judgment.primary,r=n.options.find(o=>o.id===n.bestOptionId),d=n.options.filter(o=>o.id!==n.bestOptionId).map(o=>o.text);return d.splice(a.correct,0,r.text),{...a,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,reflection:e.direction.reason.label,question:`${n.scenario} ${n.question}`,options:d,feedback:r.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds}})},E=Object.freeze(Object.defineProperty({__proto__:null,COURSE:L,MEANING_LESSONS_V2:v,SOURCES:j},Symbol.toStringTag,{value:"Module"}));export{h as M,U as a,K as b,z as c,E as d,F as i,I as m};
